-- fierymud-rs playtest r14 B4: room extra descriptions lost their line breaks on import.
--
-- World.parse folded every `~` string onto one line, so the Academy directory sign (519:2, 519:8)
-- and the other multi-line extra descriptions of the zones below were imported as one long line.
-- The parser now keeps the layout (MudData.read_text); this patch repairs rows imported before that.
--
-- Zones: 9, 12, 14, 15, 16, 20, 22, 23, 30, 35, 40, 43, 51, 53, 54, 55, 60, 61, 62, 80, 83, 85, 86, 88, 100, 102, 103, 117, 120, 123, 125, 133, 160, 162, 163, 164, 169, 172, 173, 178, 180, 185, 187, 188, 237, 238, 300, 302, 350, 360, 361, 363, 364, 370, 410, 411, 430, 462, 464, 472, 476, 477, 478, 480, 481, 484, 489, 490, 492, 495, 502, 510, 511, 520, 530, 533, 534, 550, 551, 554, 556, 564, 580, 583, 584, 586, 587, 588, 590, 615. 1487 extra descriptions.
--
-- Guarded: a row is rewritten only while it holds the folded text (no line break, equal to the new
-- text once whitespace is collapsed), so anything edited in Muditor since is left alone. Idempotent:
-- after a run the row holds the new text, so a rerun matches nothing.
-- Generated by scripts/gen_room_extra_desc_newlines_sql.py from lib/world/wld/*.wld.

BEGIN;

UPDATE "RoomExtraDescriptions" AS d
SET description = v.txt
FROM (VALUES
  (9, 0, ARRAY['stardust', 'dust', 'cloud']::text[], $d$The cloud may look ethereal, but you don't seem to be in any danger of
floating away... although it would be difficult to tell if you were...$d$),
  (12, 12, ARRAY['wall', 'ice']::text[], $d$     You touch your finger to the slick surface of the cavern's wall.  Quickly
you jerk away, rubbing and soothing the flesh of your hand.  The walls must be
ice - that would explain the numbing cold that bit your outstretched finger.
Beneath the mirror-smooth ice, colors shimmer and glow, lighting the cavern
with a dim and almost sourceless light.$d$),
  (12, 12, ARRAY['portal']::text[], $d$     Through the magic of the Worldsong, Selina can open gateways to the many
worlds of the mutliverse.  Though none are currently open, the portals to
these worlds shimmer and glow in phase with Selina's beautiful notes, windows
that lead to any number of worlds.$d$),
  (12, 12, ARRAY['pool']::text[], $d$     The cavern's floor is bowl-shaped and filled with a vast sea, a
glistening pool of magical waters.  The liquid is steel-blue and aquamarine
all at once, and it glows serenely from within.  The waterfall continuously
pours into the pool, though ripples pass not across its mirrored surface, and
it has no evident outpouring.  Surely the liquid is freezing cold!$d$),
  (12, 12, ARRAY['waterfall']::text[], $d$     The waterfall pours down from far above, its source shrouded by the cold
mist that fills the cavern.  It plummets hundreds of feet, crashing into and
filling the pool that dominates the grotto's floor.  Gazing into its churning
maw, you feel a deep peace and calm come over you, and you find it difficult
to turn away.$d$),
  (12, 12, ARRAY['floor', 'ground']::text[], $d$     Most of the cavern's floor is filled with a vast pool, though where you
stand the ground is solid, albeit peculiar.  It must be ice, like the walls,
but it is a white so deep it is black, a smooth onyx that reflects your stare
and your soul.  A narrow path leads all the way around the pool and behind the
waterfall itself, though you do not trust the slick surface enough to venture
far from where you stand.$d$),
  (12, 12, ARRAY['portal', 'door']::text[], $d$     Gazing into the silver-blue pool, you see a shimmering white sphere.
Within the sphere you can see blurry shapes, though you are completely unable
to discern what they may be.  With a start of realization, you suddenly know
that you stare into one of the famed portals spun by Selina's Worldsong.$d$),
  (12, 19, ARRAY['helmsman']::text[], $d$The helmsman of the Myst's Mistress stands here clutching the wheel with
sure, steady hand. His eyes continuously scan the waters the lie ahead
double checking the lookouts posted in the rigging above.  He is wearing
black pants and blouse with a sash of deep purple silk encircling his waist.
Miraculously these clothes are immaculate and do not show even a hint at
spending many days in the sun and spray.  Attached to the sash is a large
cutlass in a finely tooled leather scabbard.  By the look of him you decide
that you have no desire to find out how skilled he is with his weapon and
quickly search for something safer to direct you gaze towards.$d$),
  (12, 29, ARRAY['fire', 'fireplace']::text[], $d$   Hanging over the fire is a nicely sized iron pot, a delicious smell wafting
from it.$d$),
  (12, 29, ARRAY['counter', 'holder', 'utensils']::text[], $d$   There is a large assortment of items here, everything from spoons to
strainers, from wood to all varieties of metals.  One item in particular stands
out: a large mortar and pestal.  Fine dust still lines the little ceramic bowl
and the counter, showing this counter is frequently used.  Looking closer, you
see that the dust is simply what remains of a massive cooking project that
Daedela undertook yesterday.$d$),
  (12, 29, ARRAY['windsill', 'bread']::text[], $d$   The bread is made of the freshest hand-prepared ingredients and baked with
pure love.  Sadly, this is all that remains of the faerie's latest epic
bakeathon.$d$),
  (12, 29, ARRAY['boxes']::text[], $d$   It's hard to imagine someone who would have seven boxes labeled 'Plain
Thread' and actually have each one packed full!  Skimming the box labels, you
see hundreds upon thousands of labels for materials of all kinds.  'Natural Red
Velvets', 'Blue Indian Silks', 'Grecian Clay Beads', and a strange-smelling box
labeled 'Blossom Pleens' are just a few of the rare materials that you see.
$d$),
  (12, 29, ARRAY['special', 'box']::text[], $d$   This box is made of mahogany, hinged with obsidian clasps and wrapped in
sheets of precious silver spider webs.  Written on it in dark indigo ink is the
word 'Souls'.$d$),
  (12, 29, ARRAY['table', 'sewing']::text[], $d$   Disheveled fabrics cover half-used patterns, spools of thread and yarn
tangle together in knots of gorgeous chaos.  Needles, sewing shears, thimbles,
small cutting knives and all manner of other tools of creation are kept in
little pockets and drawers throughout the table.  Of the projects on the table,
half-built worlds, fleeting dreams, long-built desires, extinct and even
yet-to-come creatures are but a few things that seem to be under current
construction.$d$),
  (12, 33, ARRAY['pool', 'reflecting']::text[], $d$   As you stare into the pristine waters, you start to see the entire realm of
Ethilien.  As you gaze deeper into the pool at an area of the realm, your sight
focuses in and you can see a closer view of that region.  If you concentrated
you can even magnify your sight deep enough to see the grains of dirt on the
ground.  With this observation point, you can see everything that is happening
within the realm.$d$),
  (12, 46, ARRAY['north', 'sky', 'opening', 'air']::text[], $d$The grotto appears to be embedded in the face of an extremely high cliff.  It
stretches for at least a mile or two to the east, while on the west, it curves
gently northward for a few hundred yards.  The ground below is obscured by
mists fed from a thin waterfall that slowly drifts from the point of the
western promontory.  Dark green trees carpet the land.  A lake sits between
mountain ranges far to the northwest.$d$),
  (12, 46, ARRAY['waterfall']::text[], $d$The water falls from the tip of a promontory about five hundred yards to the
west.  It is somewhat lower than the grotto, so the stream that feeds it can be
seen sparkling as it rounds a corner on its way to free-fall.  Shortly after
beginning its plunge, the water breaks up and spreads.  Long before it reaches
the ground below, it has become a diffuse plume of drifting mist.$d$),
  (12, 46, ARRAY['forest']::text[], $d$The forest below the cliff is dark green, suggesting conifers.  Nothing more
can be discerned from this great height.$d$),
  (12, 46, ARRAY['railing', 'iron']::text[], $d$The railing is wrought iron.  The primary rail has a two-inch cross-section and
passes from the right side of the opening, where it is affixed with thick
bolts, to the balcony on the left, where it rises with the curve of the floor
to protect the balcony's end as well.  Iron posts support it at six-foot
intervals.$d$),
  (12, 46, ARRAY['balcony']::text[], $d$The balcony occupies the western side of the grotto.  It rises about five feet
above the pool and is perhaps ten feet away from it, and is wide enough to
accommodate a sofa, lengthwise.  There are in fact three sofas, two of which
face each other obliquely while facing somewhat toward the pool.  The third
faces the grotto's opening at an angle.  Bookshelves line the grotto wall on
the balcony.$d$),
  (12, 46, ARRAY['pool']::text[], $d$The pool is steaming mildly.  It looks to be comfortably warm.  It's possible
to sit all around its edges with at least one's head above the water.  Nearer
its center it goes down to about five feet.  It is fifteen feet across and
shaped like a rough ellipse.  An aqua color is somewhat visible.  A constant
current slowly flows in through an opening on the south end, and out another on
the north.$d$),
  (12, 98, ARRAY['creature', 'flameling', 'familiar']::text[], $d$Roughly the shape of a spider, but with only six legs, the creature of flame
hops from table to table tending the experiments.$d$),
  (12, 98, ARRAY['table', 'alabaster']::text[], $d$The tables are made of a gleaming white stone, shot through with veins of that
shade of red that consumes the coals of a low-burning fire.  The veins glow
slightly with an internal light and heat, pulsing with their hue as the veins
of a living creature might pulse with its blood.$d$),
  (12, 98, ARRAY['window', 'outside']::text[], $d$Outside the single narrow window dark clouds of ash hang low, obscuring most of
the world.  The room is located within a tower built completely of the essence
of flame.  What little can be seen of the ground below through the clouds of
ash is nothing but broken rock and volcanic glass.$d$),
  (14, 0, ARRAY['priest', 'Aurius']::text[], $d$This picture shows a young man battling a huge white dragon, with shadows of
other heroes in the background.  The young man is pale of skin and has short,
black hair and bright green eyes.  The holy markings on his raiment and his
deity's symbol around his neck proclaim him to be a priest.  A small plaque at
the bottom of his picture reads "Aurius Lord Tepes, Scourge of Evil".$d$),
  (15, 0, ARRAY['pier']::text[], $d$   Crafted out of the finest gopher wood, this pier is made to last.  It boldly
juts out into the cove, and looks like it would be fun to jump off of.$d$),
  (15, 1, ARRAY['grey', 'stone', 'gray']::text[], $d$   Gray/stone-Each cut block has been ground to a smooth finish, but remains
unpolished and unadorned and generally unmarred by the forces of time and
weather.  Creating these blocks must ahve required lots of willpower, and hours
upon hours of hard dedicated labor.$d$),
  (15, 1, ARRAY['pllar', 'pillars']::text[], $d$   Each of these enormous stone pillars is made of numerous round blocks of
solid stone, keeping the weight of the ceiling from crashing down into the
hall.$d$),
  (15, 1, ARRAY['arch', 'archway']::text[], $d$   Dark obsidian that has been crafted into an ancient gothic archway, leading
into a pitch-black room beyond.  Numerous religious symbols and icons are
carved into the archway, indicating that this is not a safe place for the
unknowing.  Seven tiny purple candles have been ensconed in the archway, three
along each side and one at the top.  They burn very dimly, more to create
shadows from object, the light by which to see.$d$),
  (15, 1, ARRAY['ceiling']::text[], $d$   The ceiling of the entrance hall is smooth much like the floor and walls,
but some imperfections in the stone add texture to the room.  A hole in the in
the middle of the ceiling allows natural light to fill the room.$d$),
  (15, 1, ARRAY['rune', 'runes', 'symbols']::text[], $d$   These ancient runes seem to be moving slowly across the floor in a seemingly
random pattern.  They don't seem to make any sense to you, but you can tell
that they have a definite purpose.$d$),
  (15, 1, ARRAY['floor']::text[], $d$   The floor is smooth bare rock cut directly from the stone of the island
itself, uniting the artificial and the natural.$d$),
  (15, 2, ARRAY['candle', 'candles']::text[], $d$   The candles lighting the outer perimeter of the shrine are a deep purple in
color and burn with a flickering light that does not drive back the shadows so
much as invite them to dance.  Made of soft beeswax, they must be replenished
often from a stack that sits behind the altar.  The lone candle on the altar
itself is made of a much harder, dark blue wax and burns slowly yet steadily
against the dark.$d$),
  (15, 2, ARRAY['altar']::text[], $d$   A moderately sized altar of rare black marble, it is inset with many runes
to spread its protection over the entire guildhall.  On the front is a large
symbol: an inverted triangle surrounded with a sphere on each side.$d$),
  (15, 2, ARRAY['mosaic', 'mosaics', 'wall', 'walls']::text[], $d$   Barely visible in the dim lightning is a single mosaic running clockwise
through the entire room that shows many different scenes from the mythology of
the Goddess Kourrya.  Looks like mosaic1 would be a good place to start.$d$),
  (15, 2, ARRAY['mosaic1']::text[], $d$   Here is the fabled story of Kourrya's ascension, with a humanoid figure
dressed in purple and blue dying in the service of a blond-haired prince, her
soul rising like a phoenix and joining with the shadow forces of the great
cavern of her sacrifice and becoming something much greater.  The story
continues on mosaic2.$d$),
  (15, 2, ARRAY['mosaic2']::text[], $d$   Here is a mosaic of the young goddess making a deal with a massive dragon
while strange creatures indiscriminately destroy cities and feast upon others
in the background.  This marks the beginning of her fame as the Devourer of
Souls.  The story continues on mosaic3.$d$),
  (15, 2, ARRAY['mosaic3']::text[], $d$   This mosaic shows the goddess Kourrya in her own realm, watching over the
worlds while being attended upon by her servant souls, some looking like
ghostly humans and others looking like only indefinite blobs, or like nothing
that was ever human.  The story continues on mosaic4.$d$),
  (15, 2, ARRAY['mosaic4']::text[], $d$   The final mosaic shows Kourrya engaged in discussion with the founding
Weavers of Fate, smiling in delight at the chance to have mortal agents in the
world once again.$d$),
  (15, 3, ARRAY['chime']::text[], $d$   A tiny trinket of a thing, each of the metal chimes is engraved with symbols
for wind and air, elements commonly associated with the mind and the intellect.
Truely, it must have another purpose other than to create pretty sounds.$d$),
  (15, 3, ARRAY['section4']::text[], $d$   A brief history of the major powers in the realms, identifying common
enemies and allies makes up the fourth part of the tapestry.$d$),
  (15, 3, ARRAY['section3']::text[], $d$   A record of all the names of the clan members is embroidered in this
section.$d$),
  (15, 3, ARRAY['section2']::text[], $d$   The gathering of the five founders of the Weavers, their names and titles
recorded in simple symbols creates the original section of the tapestry.$d$),
  (15, 3, ARRAY['section1']::text[], $d$   Though not the original section of the great tapestry, the creation myths of
the realms are woven together, creating an ideal about the foundation of life
and being: balance.$d$),
  (15, 3, ARRAY['sections']::text[], $d$   There are many sections on the great tapestry, and studying the entire thing
could take hours.  Looking at section1 would be a good place to start.$d$),
  (15, 3, ARRAY['tapestry']::text[], $d$   This giant tapestry is dozens of years old and has been worked on numerous
times.  Every kind of material has been used to create the most perfect color
and texture for every single minute detail-leaves of tree are actually dyed
with colors derived from tree leaves.  Apparently, it's a visual record of the
entire history of the Weavers and their interactions with the world, told in
symbols and pictures.  There are several distinct sections that have been added
to what was probably the original tapestry.$d$),
  (15, 3, ARRAY['loom']::text[], $d$   What could easily be considered an industrial loom rests here.  It is a
machine that can take years to learn to use at all, let alone with any degree
of proficiency, and only those spinners with a supernatural hand can hope to
ever master it.  The loom is also a symbol of the work that the weavers do, the
tapestry is truly just a metaphor for the results of the work.  Threads made of
a multitude of colors and materials are organized in a huge cabinet near the
loom, ready to be used at any time.$d$),
  (15, 3, ARRAY['ladders']::text[], $d$   These sturdy wooden ladders are mounted on tracks which allow a person to
roll from one side of a wall to another.  The ladders reach floor to ceiling.
When rolling on the tracks, they make very little noise.$d$),
  (15, 3, ARRAY['shelves', 'bookshelves']::text[], $d$   Hese enormous bookshelves are each about twenty feet wide and fifty feet
tall, fitting tightly together from floor to ceiling, and wall to wall.  Each
unit is made of highly finished oak, very plain but attractive.  Attached to
the bookcases is an intricate system of rolling ladders which allow access to
the various scrolls, books, and tomes of knowledge.$d$),
  (15, 3, ARRAY['lamps']::text[], $d$   Each oil lamp here has a unique cut crystal hood.  Some are stained in many
colors, others are either stained or perhaps burned completely black, and some
have no staining or coloring at all.  However, regardless of the style or
design, each lamp is a small work of art.$d$),
  (15, 3, ARRAY['tables']::text[], $d$   Each oak table is finished in the same varnish as the bookshelves, bringing
the room together.  Fine crystal hooded oil lamps adorn several of the tables,
providing reading light for those who wish to study.  Random stacks of books
remain unshelved on several of the tables, breaking the orderly fashion of the
rest of the room.$d$),
  (15, 3, ARRAY['chairs']::text[], $d$   The large chairs are very comfortable and make excellent places to sit and
read for hours on end.  Each leather armchair looks like it is fairly old.$d$),
  (15, 33, ARRAY['table', 'circular']::text[], $d$   This large table has a hole cut into the exact middle, allowing somebody, if
they wished, to stand in the middle of it and give a presentation to the rest
of the table.  The runes seem to leave this object alone, as it is not a
natural part of the room.$d$),
  (15, 33, ARRAY['throne5']::text[], $d$   A small tree springs up from the floor, forming a rather comfortable seat in
the fork of its limbs.  Several of the branches form a crude triangle.  A snake
has wrapped itself around the triangle, and will allow none to sit in the chair
except for Janara.  Oddly, the triangle with the snake appears to be a symbol,
as well as a means of protection.$d$),
  (15, 33, ARRAY['throne4']::text[], $d$   Constructed from crystal clear ice, this throne is as hard to sit upon as it
looks.  Mist rolls off of it as water in the air condenses due to the extreme
cold of this chair.  Krytonius is the only person who can sit in this chair,
because everybody else would just freeze to death.  A larger-than-life
snowflake sits atop the throne, mounted on crystal pole which protrudes from
the throne itself.$d$),
  (15, 33, ARRAY['throne3']::text[], $d$   A rocking chair constructed of the finest wood belongs to the wisest and
oldest weaver.  A soft pillow on the seat provides the old man with much needed
cushioning for his increasingly boney posterior.  A small bedpan lays beside
the chair, just in case the urge arises, and there isn't enough time to get
back to town.  A strange symbol of a wolf holding a crystal ball in its jaws is
painted onto the back of the rocking chair.$d$),
  (15, 33, ARRAY['throne2']::text[], $d$   A large twisted onyx rock forms crude seat.  There appears to be no
comfortable way to sit in this chair, and you begin to question the sanity of
the one who sits here.  A crest, consisting of two swords crisscrossed over a
shield suggests to you that this chair belongs to Nuggz.$d$),
  (15, 33, ARRAY['throne1']::text[], $d$   The symbol of a pentagram with a slim crescent moon on either side is set in
silver on this chair.  Clearly, this is Cerworn's seat.  An extremely
decorative piece of furniture, the designs on it are intricate and complex,
with one image flowing into the next like a giant web.  The chair is made of
black-veined white marble and has white velvet padded cushions on the seat and
the back.$d$),
  (15, 33, ARRAY['rune', 'runes']::text[], $d$   Etched into the walls are dark purple runes that contain no meaning for you.
They glisten in the light cast by the flambeux placed in the corners of the
room.$d$),
  (15, 33, ARRAY['flambeau', 'flambeaux']::text[], $d$   Each flambeau is made out of wrought iron, blacked from constant flames
being burned in them.  There are four in all, one in each corner of the room.
$d$),
  (15, 33, ARRAY['pews', 'benches']::text[], $d$   Each section is marked with a different symbol, dividing the sections in
good, neutral and evil, indicating where one is to sit during meeting.$d$),
  (16, 0, ARRAY['sign', 'small']::text[], $d$Beware the pit viper.  Many have tried, few have succeeded. This is your warning!

--The dwarves$d$),
  (16, 1, ARRAY['tracks']::text[], $d$Apparently small furry creatures have been here, maybe rabbit or hare.
The paw print, however, is much larger than the average pet.$d$),
  (16, 4, ARRAY['tracks']::text[], $d$Different sized paw prints and footprints are scattered about,
along with a snake trail leading to the east.$d$),
  (16, 5, ARRAY['e', 'east', 'eas', 'ea']::text[], $d$The cliffside is solid rock, with granules of dirt falling
occasionally between crevices and peaks.$d$),
  (16, 5, ARRAY['tracks', 'animal']::text[], $d$These tracks are large paw prints, and various scattered dirt...
caused by large wings perhaps?$d$),
  (16, 6, ARRAY['animal', 'tracks']::text[], $d$  The tracks range in size, but appear to be mostly giant paw prints,
seemingly from rabbits.  A trail left by what appears to be a snake of sorts
leads off to the south.$d$),
  (16, 7, ARRAY['animal', 'tracks']::text[], $d$  There are various-sized tracks leading off in many directions.  Most appear
to be rabbit paws, although of a much larger variety than the average
household pet.  There is also what appears to be a snake trail leading
off to the south.$d$),
  (16, 8, ARRAY['sign']::text[], $d$If you're reading this, you must have survived the boa constrictors.  Beware,
this pit is not the only trap out there!  The pit vipers await!
-- The dwarves$d$),
  (16, 9, ARRAY['tracks']::text[], $d$  Various tracks lead off in every direction, although most appear to be
large paw prints.  Rabbits come that big?!  A snake trail leads east
and south.$d$),
  (16, 10, ARRAY['tracks', 'animal']::text[], $d$Little dust swirls dot the area, appearing to have been caused by large
wings.  Large paw prints are also scattered about.  A snake trail leads
south.$d$),
  (16, 11, ARRAY['steps']::text[], $d$  Upon closer examination, hammer marks and chips become apparent.  Although
crude, each step looks to be enough to support the weight of even the largest
barbarian, maybe even a small army.$d$),
  (16, 12, ARRAY['ground']::text[], $d$  There appears to be something hidden in the dirt here.  Maybe a search would
reveal it...$d$),
  (16, 12, ARRAY['tracks', 'animal']::text[], $d$  A variety of animal tracks lead off in different directions.  Most prominent
is a snake trail, coming from the north and leading off to the east.$d$),
  (16, 14, ARRAY['tracks', 'animal']::text[], $d$  Various paw prints and dust swirls are scattered about, but most noticeable
is a snake trail, coming from the west, heading north.$d$),
  (16, 14, ARRAY['painting']::text[], $d$A large picture, painted onto this wall, shows a man standing next to what
appears to be a young boy, pouring a liquid from one beaker to another. A
large rabbit sits next to the young boy.$d$),
  (16, 15, ARRAY['sand']::text[], $d$   This is your second warning, the pit viper is a vicious predator, and has
been know to kill young dwarfs.$d$),
  (16, 21, ARRAY['painting']::text[], $d$A picture is crudely painted on the wall here, of a young boy surrounded by
what appear to be two-headed children.  A sorcerer stands just outside the
circle, wand in hand, scowling.$d$),
  (16, 22, ARRAY['painting']::text[], $d$A crude picture is painted on the wall here, showing a man, lying on the
ground, with blood pouring from his body.  A young boy stands nearby, tears
running down his face.  In the background is a sorcerer, grinning evilly.$d$),
  (16, 24, ARRAY['tracks', 'animal']::text[], $d$A variety of animal prints lead off in different directions, including
some interesting scrape marks heading north.$d$),
  (16, 27, ARRAY['claw', 'scrapings']::text[], $d$It appears some animals dug their claws in, in an attempt to keep themselves
from heading north.  The long scrape marks seem to show they failed.$d$),
  (16, 27, ARRAY['tracks', 'animal']::text[], $d$These trails lead off in various directions, including some paw prints and
a snake trail.$d$),
  (16, 32, ARRAY['painting', 'picture']::text[], $d$This picture shows a young boy, neck-deep in mud or dirty water.  A Bile
Rot appears in the foreground, on a dirt road.  The Bile Rot appears not to
have noticed the young boy.$d$),
  (16, 34, ARRAY['grooves']::text[], $d$There are well-worn grooves here, along with partial paw prints and
boot prints.  Something or someone must have been walking this trail for
years, to wear into the rock like that.$d$),
  (16, 36, ARRAY['picture', 'painting']::text[], $d$The picture shows a boy walking through the streets of Mielikki.  He's covered
in dirt, and his clothes hang loosely off him.  Of all the people looking at
each other, noone is looking at him.$d$),
  (16, 38, ARRAY['markings', 'animal', 'rocks']::text[], $d$There are a variety of paw prints, dwarven footprints, and boot prints
leading off in various directions.  There's also what appears to be a
snake trail, heading to the east and south.$d$),
  (16, 38, ARRAY['bits', 'black']::text[], $d$Upon closer inspection, the bits appear to be soot.  A good amount of the soot
is on the south side of the room, dissipating towards the east, west, and
north.$d$),
  (16, 40, ARRAY['painting']::text[], $d$The painting shows a young man, standing on the top plateau here, looking
out over the dairy farm.  A team of dwarves, behind him, appear to be working
on the side of the mountain.$d$),
  (16, 43, ARRAY['skin', 'snake']::text[], $d$This skin is about four feet long, with a nasty-looking black splotch
near where the head would've been.  It appears freshly cast off.$d$),
  (16, 47, ARRAY['tracks', 'animal']::text[], $d$Various tracks lead off in different directions, and a snake trail leads
off to the south.$d$),
  (16, 49, ARRAY['picture', 'painting']::text[], $d$This appears to be a laboratory of sorts:  machinery everywhere, beakers
boiling... A regular-sized rabbit stands to the left of a young man, and a
large, mutant rabbit stands to the right of the young man.$d$),
  (16, 57, ARRAY['scattered', 'tracks']::text[], $d$A variety of boot and paw prints lead off to the north and west.  A snake
trail is also apparent, leading north, west, and somehow, straight into the
rock wall to the south.$d$),
  (16, 73, ARRAY['table']::text[], $d$Made of solid granite, it appears the table has grown out of the floor.  Small
markings along the surface indicate it was carved by hammer.$d$),
  (16, 73, ARRAY['sconce']::text[], $d$Shaped like a sorcerer's hat, the sconce appears to have been cut directly
into the wall.$d$),
  (16, 75, ARRAY['bed']::text[], $d$The bedframe is stone, on which a comfortable-looking mattress resides.
A soft down comforter covers the mattress.$d$),
  (16, 75, ARRAY['sconce']::text[], $d$Carved into the wall, the sconce is shaped like a wizard's wand, with the
light it gives off coming from the lightning bolts streaking from the tip.$d$),
  (16, 76, ARRAY['painting', 'large']::text[], $d$In the painting, a small army of dwarves are holding a variety of tools.
A young-looking man is standing near them, arms folded.  There are scrape
marks around the painting, as if it gets moved often.$d$),
  (16, 78, ARRAY['sign']::text[], $d$Stuck on the wall, near the door to the south, the sign reads "Please
remove any footwear, and don a labcoat, before entering"$d$),
  (20, 9, ARRAY['wagon', 'cart']::text[], $d$You see the remnants of what once must have been a wagon of some sort.  The
one remaining wheel appears to have the bushes pushed aside nearby it.$d$),
  (22, 2, ARRAY['Sign']::text[], $d$Be good and ye might just be released, be proud
and ye shall certainly be further punished.$d$),
  (22, 10, ARRAY['river', 'blood', 'torrent', 'torrents', 'rivers']::text[], $d$   Torrents of red flow in every direction, covering the already reddish land
with an even brighter crimson shade.  The smell rising from it is a familiar
one - blood.  Legend has it that the blood spilled in every battle makes its
way here, though where it goes from here no one knows for certain.$d$),
  (22, 10, ARRAY['rocks', 'rock', 'weapons', 'bones']::text[], $d$   Wherever the blood river does not rush, the dry land is filled with broken
chunks of rocks, steaming with evaporating blood.  Shards of shattered weapons
stick out at odd angles, some rusted into nearly nothingness and many others
looking as sharp as the day they were forged.  Splintered bones litter the
ground as well, making walking rather dangerous.$d$),
  (22, 11, ARRAY['chandelier']::text[], $d$   Crystals take the pale blue glow and refract it into thousands of tiny beams
of light, casting a mottled luminescence over the room.  Ordinary candles would
no doubt melt in the room's heat.$d$),
  (22, 11, ARRAY['stained', 'glass', 'window', 'windows']::text[], $d$   Dark shards of glass are illuminated into figures of demons battling angels
while mortals, tiny creatures in the background, quake in terror of the
unknown.$d$),
  (22, 12, ARRAY['plants']::text[], $d$   Looking like nothing so much as the tortured souls of twisted trees, massive
plants seem to shriek in agony, dissolving even as they grow.  Smaller,
parasitic plants grow on the trees and periodically release spores, giving the
entire area a thick miasma that makes it impossible to see the sky.$d$),
  (22, 13, ARRAY['plants']::text[], $d$   Broken leaves of the plant reveal a sticky goo on the inside, which probably
helps it survive the flames.  However, breaking a leaf to get at the goo is
tough - a leathery skin covered in barbs protects the plant.$d$),
  (22, 13, ARRAY['chained', 'figures']::text[], $d$   The chained figures seem to be of many races: humans, dwarves, elves, even
orcs and trolls.  None of them look happy.$d$),
  (22, 14, ARRAY['mountain', 'mountains', 'ice', 'iceberg', 'icebergs']::text[], $d$   From tiny chunks of ice encasing evil-looking animals to huge mountains that
could contain entire nations, the ice of the dark sea glows a faint green.
Some icebergs are stuck together with many figures inside, while others contain
only single creatures.  All have features locked into expressions of terror.
$d$),
  (22, 14, ARRAY['sky', 'starless']::text[], $d$   Impossible to tell how far up it extends, the velvet sky seems at once close
and impossibly far away.  The only perspective is provided by the icebergs.
$d$),
  (22, 15, ARRAY['corpses', 'weapons', 'flies', 'swarm']::text[], $d$   Many corpses look bloated from the heat and have turned a sickly
yellow-green.  Weapons are rusted or, in some cases, coated with a nasty goo
that looks quite poisonous.  The swarm of flies feasts upon dead and living
alike, undoubtedly spreading nasty diseases with every bite.  All in all, this
place seems like an extremely dangerous place to hold a battle.$d$),
  (22, 15, ARRAY['army', 'armies', 'battle']::text[], $d$   Each army seems to be composed solely of one type of creature: goblins,
drow, harpies, hellhounds and the like.  No single army has a definate
advantage, since the terrain is constantly shifting and a good position one
moment may be completely undone with a surprise avalanche.  Demons float over
the armies, overseeing the battles and occasionally descending and whipping a
certain army to a certain goal.$d$),
  (22, 16, ARRAY['stands']::text[], $d$   Demonic forms clutter the great stands of this arena. Different
forms from large ogres to smaller goblins all chanting for death.
All chanting toward the great throne toward the north, chanting for
Ac....$d$),
  (22, 16, ARRAY['walls', 'archway', 'stone']::text[], $d$   Ancient stones abound these great walls. Dark red in color or just
tainted from all the blood that has splattered on them over the ages,
they stand with great presence and dominate the surroundings. Each
stone seems to have demonic etchings carved into it, unique from the
others but pulsating with great power.$d$),
  (22, 16, ARRAY['throne', 'lightning', 'seat']::text[], $d$   A massive stone throne, outlined with polished charcoal black marble,
stands erect at the northern edge of the arena. It's large glowing emblem
showing it's relative vacancy. Although it seems empty a mighty presence
still manages to make itself known as bright flashes of lightning
periodically reveal the outline of a giganic being.$d$),
  (22, 16, ARRAY['emblem']::text[], $d$   Two half crescents, one pointing to the sky and the other pointing
toward the ground, overlap each other every so slightly as they are
intersected vertically by a large lightning bolt.$d$),
  (22, 17, ARRAY['mirror', 'frame', 'silk']::text[], $d$   A long oval mirror set horizontal rather than the customary alignment of
vertical flashes continuously with images of this plane and others.  Cities
past and present vie with images of volcanoes, whirlpools, tornadoes and other
places of heavy activity, be it mortal or natural in nature.  The frame is a
work of art in itself: the scarlet silk that edges the mirror is embroidered
with golden runes of magic and slender outlines of fantastical creatures doing
battle.  Its value alone would be worth the price of a soul.$d$),
  (22, 18, ARRAY['window', 'windows', 'arched', 'rift']::text[], $d$   Windows arched into gothic points appear on all sides of the circular room,
though an especially large one rises to the north.  Flashing with colors that
change almost too quickly for the mind to comprehend, scenery which may be real
and may just be a trick of the eyes, and warped textures that make it
impossible to tell the distance between here and there, the Rift is massive in
both size and power.  Someone who could control it would have access to any
plane they wished, at any time in its history.  In other words, it would take a
true planewalker to go any nearer without having their minds and bodies torn
asunder, but the reward would be beyond imagining.$d$),
  (22, 18, ARRAY['center', 'desk', 'souls', 'pentagram', 'blood']::text[], $d$   In the dead center of the room facing the largest window is a massive desk
made of the swirling grey-black mass that is the physical appearance of forged
souls.  The pentagram it sits in the exact center of is arranged so that on
point faces west, one south, one east and two north.  The pentagram is formed
by a shallow trough in the floor that is filled with constantly moving,
steaming hot blood.  The chair set at the desk is almost a throne; and why
should it not be, as this is the seat of power of Crown Prince Belial himself?
$d$),
  (23, 20, ARRAY['patchwork']::text[], $d$Written in the stony patchwork are words carved by its mason:

    The Borderhold: now bigger, better, and more border-holding! -Laoris 2006$d$),
  (23, 47, ARRAY['squares']::text[], $d$The squares seem to represent the borderhold's enemies.  One is marked
'dryad's, while several others read 'orc'.$d$),
  (23, 47, ARRAY['large-black-board', 'myriad-chalk-diagrams']::text[], $d$The chalk diagrams on the black board consist of several complicated diagrams.
At the center of the board, a large circle with the words "Toldar Keep" has
been drawn, with several arrows pointing outwards at squares.  A procession of
triangles runs just above the large circle, and a thin line stretches out from
either side of it.$d$),
  (30, 1, ARRAY['trees', 'tree', 'ancient']::text[], $d$These trees have stood here, praising Mielikki for untold centuries.  Their
mighty branches form a natural green canopy above the temple, reducing the
effects of Mother Nature here, but not entirely eliminating them.$d$),
  (30, 6, ARRAY['office', 'templar']::text[], $d$This is a low wooden building.  Its age is indeterminate.  It appears to be
made of a local soft wood, which is stained from many seasons of weathering.$d$),
  (30, 6, ARRAY['stone', 'stones', 'marble']::text[], $d$The marble is of a medium gray variety.  Its shade varies from stone to stone,
but is always attractive.  It bears little resemblance to any local rocks.$d$),
  (30, 6, ARRAY['tree', 'trees']::text[], $d$The trees are tall and slender.  Their light gray bark is unmarred, and their
gently spreading branches provide shade for the entire plaza.  Each tree is
surrounded by a knee-high wall of stone, in which a small garden of simple
flowers grows.$d$),
  (30, 71, ARRAY['post', 'rusty']::text[], $d$The word rusty might be too kind. You wonder why it hasn't
crumbled into a pile of dust. Its definately very old.$d$),
  (30, 71, ARRAY['sign', 'large', 'important', 'warning', 'text', 'words']::text[], $d$
               * * * * * WARNING! * * * * *

You are about to leave the protected Village of Mielikki!
The Guardians of Mielikki cannot protect you if you choose
to travel the BlueFog Trail. All recent reports indicate
that the trail is overrun by extremely dangerous monsters
and that the Seaport of Specula has sealed itself off.

Travel is at your own risk!$d$),
  (30, 200, ARRAY['gate']::text[], $d$   Large black metal gates bar the entrance north into
the garden. There appears to be something written on the
main support of the grand gates, it reads:

  "Dedicated to the memory of our beloved friend and mentor
   Pergus, Rick Sala, this 9th Day of July, 2006."$d$),
  (30, 201, ARRAY['plaque']::text[], $d$The Druid's life, as it be known,
Is carved for all upon the stone
To leave a lasting legacy
For all who open eyes to see.

So enter, breathe its air,
Discover life's true meaning there,
Written within the stars, so bright,
Your path of everlasting light.

Then set your foot upon this path
And do not contemplate the math.
The sky, unfurled before you now
Will sanctify your sacred vow.

The Druid's circle, once complete,
Will lay its blessings at your feet
And bring your spirit home, at last,
To a garden of peace and love so vast.$d$),
  (30, 201, ARRAY['granite', 'stones', 'stone']::text[], $d$   The stones are all flat and smooth and look eerily alike as if each were an
exact replica of the other.  Each stone is a circle itself, with a large enough
diameter to stand within.  There is a small plaque near one of the stones.$d$),
  (30, 201, ARRAY['etching', 'base']::text[], $d$To a friend, Pergus (Rick Sala),
May your memory live on and grow like a giant oak.
- Zantir 2006

Live thy Life,
Young and old,
Like yon oak,
Bright in spring,
Living gold;

Summer-rich
Then; and then
Autumn-changed
Soberer-hued
Gold again.

All his leaves
Fall'n at length,
Look, he stands,
Trunk and bough
Naked strength.

Alfred, Lord Tennyson$d$),
  (30, 201, ARRAY['oak', 'tree']::text[], $d$   The oak tree looks to have several delicately crafted faces all over the
trunk that appear to change both location and expressions upon every glance.
It appears as if this tree holds a spirit of some sort for year of age on the
tree.  A small etching is inscribed at the base of the tree.$d$),
  (30, 202, ARRAY['oak', 'trellis', 'sapling', 'vines']::text[], $d$   Young, vigorous oak saplings have set their roots into the black soil and
have been coaxed by the druids to grow into a canopy above the garden,
shielding it from harsh weather and giving those who walk under it a beautiful
green light by which to see.  Reaching for the sun are flowers of a deep purple
growing from vines: the short-lived but exquisitely beautiful morning glory,
symbolizing transience.$d$),
  (30, 202, ARRAY['altar', 'flame']::text[], $d$   The altar is about chest-high to a human and is made of stone quarried in
the depths of the Wailing Mountains, famous for its durability.  The flame on
the front is surely a dwarven creation, for no other race can make the stone
seem to come alive.  Indeed it seems to be moving in concert with the actual
flame set on top of the altar, which seems to have no source yet provides a
constant light.  On the back of the altar is an inscription.$d$),
  (30, 202, ARRAY['inscription']::text[], $d$In memory of Pergus, Rick Sala.
You will always be missed,
my dear friend.  May others
follow in your footsteps and
your ideals never be forgotten.
-Kourrya, 2006$d$),
  (30, 202, ARRAY['jewel-like', 'flowers']::text[], $d$   These flowers are rich with the colors of gemstones, bringing to mind
sapphires, amethysts, rubies, emeralds, and more.  Each has four soft petals
and its own gentle yet sweet scent.  The soil they are planted in was imported
from the volcanic Fiery Island, where the richest loam can be found.$d$),
  (30, 204, ARRAY['inscription']::text[], $d$The inscription written into this large willow reads:

Rick Sala: June 1st, 1974 - June 21st, 2006
A dear friend, although your are gone you shall not be
forgetten, for you memory and spirit lives on in all
that we do and all that this represents.$d$),
  (30, 204, ARRAY['willow', 'tree']::text[], $d$   This massive tree seems to be ancient as its large trunk is several
meters around, at least. Its branches hang down protecting everything
beneath it and hiding all the small animals that call this their home.
An inscription is carved into the side of this tree.$d$),
  (30, 206, ARRAY['etchings', 'bas-relief', 'scenes']::text[], $d$   The pool's pearly exterior depicts detailed scenes and symbols in light,
bas-relief etchings.  One scene records a commanding druid, arms outstretched
among the nature around him, exuding a sense of natural harmony.  Another image
shows a man engulfed in fire, molten streams of lava coursing on the ground
around him.  Six monstrous rats are drawn before him, their sharply-fanged
snouts facing outwards from his figure.  Continuing around the pool, the third
image portrays the same man engulfed by fire standing above the curvature of
the world, his right arm sweeping across its face creating forest and desert
alike in its path.  The fourth and final etching illustrates another man,
standing beside a woman and cradling a young girl in his arms.  They stand
among a background of lightly etched roses.$d$),
  (30, 206, ARRAY['opal', 'benches']::text[], $d$   Seven benches encircle the marble cobblestone footpath, placed at regular
intervals.  Carved from the rarest of black opal, the benches are all
identical, each polished surface etched with an elaborate capital D.  The sides
of the benches are etched with elaborate Highlands patterns resembling clovers
and spear-shaped leaves.$d$),
  (30, 206, ARRAY['flowers', 'growths', 'bush', 'lily', 'cornflower', 'lilies', 'cornflowers', 'trunk', 'trunks', 'bark']::text[], $d$   Around the base of each apricot tree, a wide circle of bush lilies and
cornflowers grow intertwined, rising upwards where they meet the trunks.  The
brilliant bittersweet-hued bush lilies and indigo cornflowers grow beautifully
from glossy green-leaved stalks.  On each trunk, the stalks creep vine-like up
the bark, flowers blooming continually along the creepers.  The lilies and
cornflowers weave magnificient patterns across the dusky bark, almost seeming
to form cognizant meaning but ultimately indistinguishable from natural
growths.$d$),
  (30, 206, ARRAY['cobblestone', 'marble', 'path', 'footpath']::text[], $d$   Interlocking bricks of varied sizes, form a circular footpath surrounding
the fountain.  The cobblestones are all pitch-black marble, light veins of
poppy jasper running through at regular intervals.  Light glances off the
polished surfaces of the stones, forever spellbound in a lustrous state.$d$),
  (30, 206, ARRAY['spheres', 'lanterns', 'sphereical', 'lights']::text[], $d$   Hovering spellbound above each corner of the pool, the spherical lanterns
appear as simple globes of glowing light.  They emit no heat, and when looked
at directly seem to be very soft and muted, yet their illumination brightens
the room as daylight.  The spheres seem to be locked in their positions above
the pool, just below the canopy above, and undoubtedly could not be moved by
any natural means.$d$),
  (30, 206, ARRAY['diamond', 'pool', 'pearlescent', 'fountain', 'pyramid', 'pyramidal']::text[], $d$   Shaped like a square, each corner of the pool points to a different cardinal
direction.  The edge of the pearlescent pool rises several hand-widths from the
ground, enclosing the water within.  The pool appears to be carved from a large
single mass of pearl, undoubtedly supernatural in origin.  Elaborate bas-relief
etchings cover the outer surface of the pool, depicting various scenes.  In the
center of the pool, a pyramid of the same pearl rises out of the water,
bubbling fresh, clear water from its tip.  Dancing rainbows of light flicker in
the water cascading down the fountain's pearly surface.$d$),
  (30, 206, ARRAY['ivy', 'vines', 'variegated', 'canopy', 'up', 'u']::text[], $d$   The ivy vines grow out of the apricot tree trunks and into their boughs
above, branching outward to hang across the open air between the trees.
Dozens of vines lie above, forming an elaborate interlocking canopy of leaves.
Each leaf is vaguely heart-shaped, with a green interior and a white border.
Periodically along the vines, small green flower buds pop out from between the
leaves.$d$),
  (30, 206, ARRAY['blossoms', 'petals', 'apricot', 'trees', 'tree']::text[], $d$   The white petals of the apricot blossoms flutter soundlessly on dark-brown,
nearly-black branches.  Each flower has a unique pattern of dotted white
petals, pink and purple sepals, and soft yellow anthers.  They look extremely
fragile, emphasized by the periodic cascades of petals in the air as the breeze
fluctuates.  The apricot trees have no true leaves, locked in an immutable
state of blossom.$d$),
  (30, 208, ARRAY['pillar', 'pillars', 'inscription']::text[], $d$There is a name at the base of each pillar.  Daroowise, Nameless, Trystan,
Brilan, and Pergus.$d$),
  (30, 210, ARRAY['light', 'column', 'beam']::text[], $d$For the strength and solidarity provided by our now absent friend and mentor.
Peace upon your soul Rick, Pergus, Daroowise.  You shall be forever missed.

-Tanle retired Implementor and Friend - July 2006$d$),
  (35, 18, ARRAY['trees', 'tree']::text[], $d$These trees are simply huge. Some of them look to be at LEAST twenty
feet in diameter, and are probably several centuries old.$d$),
  (35, 29, ARRAY['trees', 'tree']::text[], $d$These trees are simply huge. Some of them look to be at LEAST twenty
feet in diameter, and are probably several centuries old.$d$),
  (35, 30, ARRAY['trees', 'tree']::text[], $d$These trees are simply huge. Some of them look to be at LEAST twenty
feet in diameter, and are probably several centuries old.$d$),
  (35, 31, ARRAY['trees', 'tree']::text[], $d$These trees are simply huge. Some of them look to be at LEAST twenty
feet in diameter, and are probably several centuries old.$d$),
  (35, 32, ARRAY['trees', 'tree']::text[], $d$These trees are simply huge. Some of them look to be at LEAST twenty
feet in diameter, and are probably several centuries old.$d$),
  (35, 33, ARRAY['trees', 'tree']::text[], $d$These trees are simply huge. Some of them look to be at LEAST twenty
feet in diameter, and are probably several centuries old.$d$),
  (35, 34, ARRAY['trees', 'tree']::text[], $d$These trees are simply huge. Some of them look to be at LEAST twenty
feet in diameter, and are probably several centuries old.$d$),
  (35, 35, ARRAY['trees', 'tree']::text[], $d$These trees are simply huge. Some of them look to be at LEAST twenty
feet in diameter, and are probably several centuries old.$d$),
  (35, 36, ARRAY['trees', 'tree']::text[], $d$These tress are simply beyond belief! You don't see a tree in this
area that is less than 30 feet in diameter, and SOME of them look to
be as much as 50 feet across! Some of these trees must be a thousand
years old, possibly even thousands. Very impressive, indeed!$d$),
  (35, 37, ARRAY['trees', 'tree']::text[], $d$These tress are simply beyond belief! You don't see a tree in this
area that is less than 30 feet in diameter, and SOME of them look to
be as much as 50 feet across! Some of these trees must be a thousand
years old, possibly even thousands. Very impressive, indeed!$d$),
  (35, 39, ARRAY['trees', 'tree']::text[], $d$These tress are simply beyond belief! You don't see a tree in this
area that is less than 30 feet in diameter, and SOME of them look to
be as much as 50 feet across! Some of these trees must be a thousand
years old, possibly even thousands. Very impressive, indeed!$d$),
  (35, 40, ARRAY['trees', 'tree']::text[], $d$These tress are simply beyond belief! You don't see a tree in this
area that is less than 30 feet in diameter, and SOME of them look to
be as much as 50 feet across! Some of these trees must be a thousand
years old, possibly even thousands. Very impressive, indeed! And
in particular, one tree, a mighty oak, stands a little apart from
all the rest.$d$),
  (35, 101, ARRAY['carving']::text[], $d$The carving is a circle composed of five circles linked together.
In the center of the five circles is carved the guild icon.$d$),
  (35, 101, ARRAY['door']::text[], $d$The heavy wooden door is new looking and very sturdily made.
It's bordered with metal reinforcements and accoutrements.
There is a carving in the center of the door.$d$),
  (40, 2, ARRAY['symbol', 'marking', 'markings']::text[], $d$   This looks rather old.  It appears to be some sort of scaled like creature
cringing away from a small outline of a creature.  The small unknown creature
seems to be rather harmless due to its lack of size, against the other cringing
from it.  The scaled creature points southward.$d$),
  (40, 3, ARRAY['markings', 'marking', 'tablet', 'sand']::text[], $d$   A scaled creature stands chained with his head hanging as it appears a soul
or spirit is rising out of him.  Or perhaps into him.  Six little outlines of
very small creatures surround the scaled one.$d$),
  (40, 4, ARRAY['markings', 'marking', 'mark', 'marks']::text[], $d$   The markings have been scared by long deep claw marks through them.
Obviously whatever made these marks must have considerable strength.$d$),
  (40, 5, ARRAY['symbol']::text[], $d$   Four moons hang above a shadowy creatures head, while the unknown creature
looks to be consuming a spirit or soul.  A word is writen above the head of the
creature.  It says, Norhamen.$d$),
  (40, 6, ARRAY['tapestry']::text[], $d$   Hanging here is a remarkable work of art.  A stunning shield in the shape of
a dragon.  The crest has four sections one blue, the second black, the third
white, and the fourth is two colors divided, green with an twisted blood like
red.  The black has the same strange creature as the symbol before indented into
it.  The white has a small gem indented into the color itself.$d$),
  (40, 7, ARRAY['up', 'ceiling']::text[], $d$   Bodies of the rotting creatures that were slain are held to the ceiling by
some sort of stakes.  The expression on their faces alone is a warning of the
power that took them.$d$),
  (40, 8, ARRAY['chain', 'chains']::text[], $d$   Thick iron chains hang bolted into the strong stone walls.  They seem to be
very old as rust has withered away much of their strength.  Tiny spikes inside
the cuffs suggest that these forms of bondage were used for much more then
imprisionment.$d$),
  (40, 9, ARRAY['pillar']::text[], $d$   Words seem to have etched by some sharp tool or claw.  They say, Damned are
the righteous that venture forth into the darkness.  For knowing not of thy sin
thy own soul shall be eaten with thine body left for eternal torture.  All be
WARNED!  Leave before thy soul departs.  -Traton The name signed in blood
leaves little doubt this man meant the words he wrote perhaps not just of
insanity.$d$),
  (40, 9, ARRAY['crest', 'tapestry']::text[], $d$   This family crest is different than the others.  It consist of towershield
with four divided colors and a strange cloaked man wielding a staff in the
center of the colors.  The colors from clockwise starting top left are blue,
black, silver, yellow.$d$),
  (40, 10, ARRAY['fireplace']::text[], $d$   A fairly small fireplace compared to many.  This one must have been made
just to heat the cold hall.  Ashes lay in a mysterious pattern.  Perhaps a
closer look may reveal silent secrets.$d$),
  (40, 10, ARRAY['ash', 'ashes']::text[], $d$   A strange symbol awakes the ashes that holds it.  At a simple glance it
looks like two lines dawning a outline of some creature or spirit.  The lines
seem to be words.  They read, Norhamen beneti sovering tarlon campri.$d$),
  (40, 11, ARRAY['pillar', 'stone']::text[], $d$   This massive structure seems to be way over sized for its needs.  Almost
like it would be fit for a castle instead of a small hall like this.  Tiny
inscriptions are clawed into the stone.  They say, Darkness seeks the light and
innocent, to these I offer thee All Mighty Lord Norhamen!$d$),
  (40, 11, ARRAY['circle', 'remains']::text[], $d$   Child by child nine in all, are formed into an obviously unholy symbol.
Eight corpses form the wicked circle while the nineth is placed into the
center.  All lying on their backs with their eyes open as wide as if they had
seen the depths of hades themselves.$d$),
  (40, 12, ARRAY['shelf', 'shelve', 'shelves']::text[], $d$   An overflow of books rest here upon the shelf, built out of unidentifiable
wood due to the damage and age.  The shelves stand about five feet tall, and 4
shelves to hold books.  A small tarnished yellow paper sticks out between two
books on the third shelf up.$d$),
  (40, 13, ARRAY['suit', 'armor', 'arm']::text[], $d$   This man or creature must have deeply desired this floating book, for he was
impaled with a claymore by the slayer while reaching for its leather bounds.$d$),
  (40, 13, ARRAY['book', 'tome']::text[], $d$From what can be seen, it is no ordinary book.  This tome floats in place as if
it were waiting patiently for its owner to retrieve it.  The edges of the pages
glow a bright red the more one approaches it.  Perhaps it is to ward off ones
who should not possess it.  Simple leather bonds tie this tome together with a
small word engraved into the top.  The word reads, Sahemin.$d$),
  (40, 15, ARRAY['corpse', 'remains']::text[], $d$   Hung to the wall by thick rusted chains is a corpse of an unknown creature.
Much to a lizard does it favor yet human in build.  Little flesh is left
clinging as maggots gorge upon the rotten remains of the fallen.  The faint
readable expresion upon his face is nothing short of utter terror or horror of
what occurred on the eve of his demise.$d$),
  (40, 15, ARRAY['pillar']::text[], $d$   This massive structure is obviously constructed to withstand insane amounts
of weight yet the weak ceiling seems to be the only weight in need of support.$d$),
  (40, 15, ARRAY['pool', 'blood']::text[], $d$   Flowing like a river of wine, blood tremors over the stone floor of this
hall.  Perhaps about one to two inches in depth.  And covers the entire floor.
Even as many corpses lay fallen, there must be more somewhere for this much
blood to flow as it does.$d$),
  (40, 16, ARRAY['chair', 'tiny']::text[], $d$   This appears to be a small childs chair.  A stray arrow has pierced through
the back of the chair, nearly going completely through the thin wood, something
must have stopped it.  With closer inspection it appears a small childs
skeleton barely within todlers age rest here with this arrow thrusted through
him or her.  A tragidy such a loss of innocence.$d$),
  (40, 17, ARRAY['tapestry']::text[], $d$   Boardered in blood red, background in grey, a cloaked man wields a staff
kneeling before a demonic looking creature.  The creature seems to tower the
kneeling human.  Looking like death itself, the ghastly being stands erect
peering down at the human below.  His body a grey and black taint.  Four moons
hover over his head.  The kneeling man remarkably resembles the other man in
the portrait.$d$),
  (40, 17, ARRAY['portrait', 'man', 'picture']::text[], $d$   This portrait is in beautiful condition, astounding that such could endure
battle and the decay of age and yet not even a stain upon the canvas.  A man
stands quaintly with staff in hand and cloak flowing over him.  His hood is
folded back just enough to catch a glimpse of his face.  A rough looking man
indeed, by the apperance of his eyes seem to bear an overbearing presence.  A
little metal plate is nailed into the frame.  The word on the metal plate
reads, Sahemin.$d$),
  (40, 18, ARRAY['pillar', 'pillars', 'wall', 'walls']::text[], $d$   Scorched by fire decayed by time and yet these mere mounds of stone stand
patiently waiting like sentinels, ever so strong and wise.  Marks have been
sheered though this thick stone by some fearfully powerful force.  Four marks
on each pillar and appear to be two to three inches in depth.  Certainly a
force that has done this must be one to reckon.$d$),
  (40, 18, ARRAY['skeletons', 'skeleton', 'bone', 'bones']::text[], $d$   Here lays those who are withheld in purgatory with unknown reason.  There
souls seem to scream out cries of help and pain.  Perhaps they seek more then
deliverance.  Perhaps vengenge.$d$),
  (40, 19, ARRAY['scroll', 'parchment']::text[], $d$   Made of a piece of solid darkness here lies a parchment graced by words of
blood.  The language seems to be very old and obviously not used often.  It
seems to say, Darkness hear my call unto you.  The rest appears illegiable.$d$),
  (40, 19, ARRAY['wall', 'walls', 'words']::text[], $d$   Words made of fire seem to be engraved into the walls.  They don't seem to
be legible.  Perhaps they are an ancient ward or incantation.$d$),
  (40, 21, ARRAY['footprints', 'footprint']::text[], $d$   Tiny footprints run eastward, such as size of a small child, they look to be
human or human like.$d$),
  (40, 21, ARRAY['circle', 'blood']::text[], $d$   Looks to be painted by hand, perhaps a tribute to oneself for slaying
another.  About two feet wide, in a complete circle and the line seems to be
one to two inches thick.$d$),
  (40, 21, ARRAY['ceiling']::text[], $d$Seemingly caving under somethings immense weight, the stone presses downward,
but no sand nor dirt seems to be visible.$d$),
  (40, 22, ARRAY['pile', 'wood']::text[], $d$   Stacked about three feet tall and two feet wide, dry wood apparently from
the ceiling lays blocking some of the faint light the flows behind the wood.$d$),
  (40, 23, ARRAY['gauntlet']::text[], $d$Draped in blood the gauntlet reaches out of the steady stream of blood towards
the heavens.  Made of solid steel or light iron, it would seem this creature
did not die a painless death.$d$),
  (40, 24, ARRAY['corpse', 'creature']::text[], $d$Stomach turning comes to mind when laying eyes upon such a sight.  This
creature is nowhere near human in form yet indeed a monstrosity.  Whatever this
creature is or was, it's fashion of death appears to have came from a sharp
thrust of a sword through the neck.  Indeed a painful way to perish, gasping
and choking on ones own blood.$d$),
  (40, 24, ARRAY['tower', 'shield']::text[], $d$An old tower shield stands here, resting firmly against the wall.  This shield
seems well acquainted with age but is obviously quite large for anyone but of a
giants strength to wield.  The way the shield stands it seems it could almost
be a door.$d$),
  (40, 25, ARRAY['footprints', 'footprint', 'small']::text[], $d$   Pressed in dried blood and dust these footprints appear to be of children.
Only three sets of prints appear visible but they are straight, perhaps more
could have followed in rows.$d$),
  (40, 25, ARRAY['gargoyle', 'gargoyles']::text[], $d$   Majestic yet frightfully haunting these lifelike stone gargoyles are resting
silently on a perch as if ready to pounce on intruders from above.$d$),
  (40, 25, ARRAY['ceiling', 'cathedral']::text[], $d$   A wonder indeed rest upon the eyes here.  Words fall short of explaining the
pure and angelic beauty of the craftmanship that formed this ceiling.  The
entire ceiling looks to handcrafted from stone, perhaps marble.$d$),
  (40, 26, ARRAY['paintings', 'painting']::text[], $d$   Several paintings rest upon the walls of this hall.  A man cloaked stands
upon a large rock above what appears to be soldiers of another army.  The
cloaked man has his arms wide open and wields a staff.  The soldiers look to be
trying to find cover as balls of fire hurdles towards them, some have already
crashed into the ground exploding.  A sickening view lies here.  The soldiers
that once before were fleeing from the balls of fire are now tied to rocks,
trees, and locked in cages.  Some demon like scaled creatures are torturing the
victims, beheading, impaling then on spears and stakes, severing limbs, and
throwing rats upon them to feast while they still breathe.$d$),
  (40, 28, ARRAY['claw', 'marks', 'mark', 'wall']::text[], $d$Three lines, each at least two inches in depth.  They appear to be made from a
claw or talon.  Rest assure matter not what engraved them, strength was not in
lack.$d$),
  (40, 28, ARRAY['rafter', 'writing', 'writings', 'engravement']::text[], $d$Upon age and destruction, the engraving is barely legible.  It states,
'Stairway to the Angels'.$d$),
  (40, 29, ARRAY['wall', 'walls', 'engravings', 'stone']::text[], $d$Not your usuall set of depictions.  These gracefull carvings show beautiful
floral designs as embroidery.  Within the delicate flowers and fine lay armies
under siege.  War between what appears to be very vile creatures and humans.
The human men and the creatures flow over hillside and tree lines decimating
each other.  Sorcerer and shaman appear to battle with fierce magic as the
warriors massacre each other.$d$),
  (40, 29, ARRAY['powder']::text[], $d$The powder is very thin and faint.  It appears to have born of rock, perhaps
from earthquakes or another source of tremendous shaking.  The powder could
have easily have fell from the ceiling, which is also built of marble.$d$),
  (40, 29, ARRAY['fog']::text[], $d$Grey in color, much darker than your average fog.  The blanket of it appears so
thick one could slice it with a blade.  It seems to surround the entire area,
where it ends is anything but visible.$d$),
  (40, 30, ARRAY['pillar', 'pillars']::text[], $d$The pillars appear to be crafted from the same wood the floor carries.
Extremely dark but not black in color.  Stain or paint hase not been used on
this wood.  The wood seems very dense, perhaps it was chosen for such a virtue
along with it's beauty.$d$),
  (40, 34, ARRAY['sword']::text[], $d$What power it must have taken to thrust a sword into stone such as this!  The
sword appears smaller that a bastard sword.  Or even a claymore, but the bottom
edge is jagged and serrated.  The handle is green and has a curving hand guard,
the metal is of no familiar.  Alas the blade is far to deep to be removed by
mortal strength.$d$),
  (40, 34, ARRAY['painting', 'plaque']::text[], $d$The painting isnt very large, around two feet tall, a foot in length.  One man
stand facing outwards, the other has his back turned to the first.  The first
man is neatly dressed, no beard, wearing a hat, and bears a sword with what
appears as perhaps a family crest.  The other is dressed much like the first
alas, his clothes are much darker and he bears no sword, but a knife he wields
in his right hand.  The plaque below reads simply 'Brothers'.$d$),
  (40, 35, ARRAY['footprint', 'foot', 'print']::text[], $d$The footprint itself is odd in shape and fairly large.  Around two feet in
length and only three very large front toes.  And at the heal, it looks like
there may have been another toe.  Due to the scratch marks it would seem that
the toes had talons.  The imprint is about 2 inches deep.  Either the creature
was very weightful, or very powerful.  But hopefully not both..$d$),
  (40, 36, ARRAY['drape', 'drapery']::text[], $d$The white is barely seen as bloodstained as it is.  It looks as if it has had a
rough life.  Tassels thread off the bottom of the drape.  The drape may be made
of some kind of silk.$d$),
  (40, 36, ARRAY['basin', 'bowel']::text[], $d$This basin is very large.  Perhaps ceramic, lightly colored with blue and
white, tis a beautiful piece.  It is empty, but perhaps was used to hold water
and wash ones hands.$d$),
  (40, 36, ARRAY['cloth', 'towel']::text[], $d$A small towel, perhaps used to dry ones hands after cleaning them.  Its color
would be white if not for the red of the blood that has dried within its
threads.$d$),
  (40, 37, ARRAY['painting']::text[], $d$This painting is about a foot and half in length, and around half that wide.
An Angel soars infont a wonderous light, wings spread.  A long white robe flows
down her body, and her head is tilted facing the heavens.  Just below her a
Paladin or knight stands vagrantly, armored in light with sword in hand, as if
he was protecting.  Setting below the knight in large print is the word
"Chivalry."$d$),
  (40, 38, ARRAY['tapestry']::text[], $d$Black with white lettering, the tapestry is small in size, only about two feet
in length and width.  A sword claims the middle of the tapestry, facing
downward and thrust into a golden sun.  The word "Chivalry" is sewn below the
sun.$d$),
  (40, 38, ARRAY['painting']::text[], $d$Another small painting, around two feet long and half that in width.
Background in black, with a armored man holding a baby.  The man is armed with
sword at his side, and warm smile across his face.  He wears the family crest
upon his armor.  He may have been a guard or perhaps even royalty.$d$),
  (40, 38, ARRAY['rattle']::text[], $d$A simple rattle enough, broken harshly in two.  Made of the same dark wood that
crafts all other wood.  The pieces are only a few inches apart, resting on the
stone floor.$d$),
  (40, 39, ARRAY['bed', 'beds']::text[], $d$Three beds only a few feet apart, made of the same dark wood as the pillars and
cribs.  The first, closest to the southern door, has the legs in the front
cleaved off, with some sort of blade.  The second closest, has the remains of a
child, held in bondage and damned by the unholy.  The Third has a small childs
skull resting upon a pillar at the foot of the bed.$d$),
  (40, 39, ARRAY['blade', 'sword']::text[], $d$Long indeed, but the sword is not quite the length of a bastard or claymore
sword.  Its metal is not familiar, and its bottom edge is serrated and jagged
all the way to the tip.  It has a curving handguard and is green.  The blade
itself is a darker green in color.$d$),
  (40, 40, ARRAY['portal']::text[], $d$   The portal shimmers and shines without need of light.  The portal is
obviously unstable with its convulsions of darkened flare and kindle.  The
disruption of space is surrounded by an ungodly large jade altar.  Small steps
lead upward to enter the portal.$d$),
  (40, 40, ARRAY['altar']::text[], $d$   This is a well crafted altar, completely carved from a solid piece of blazed
jade.  The flame lent the jade a blackened taint.  The altar surrounds the
entire portal, even placing steps leading to walk into the dark glow.  The
construct is huge, it seems unnatural as darkness upon a angels soul.  It must
have been place here.$d$),
  (40, 42, ARRAY['banister']::text[], $d$Beauty indeed is but a result of the craftmanship that constructed such a
railing.  Still in fair shape, the handwork alone must have taken many hours.$d$),
  (40, 43, ARRAY['mirror']::text[], $d$The mirror appears to be crafted from the same wood found outside in the halls
flooring, and pillars.  Reflections glide along the smooth finish on the glass,
almost as if the reflection itself were alive.  Fog fades slowly as it seems to
vent from behind the mirror.$d$),
  (40, 46, ARRAY['door']::text[], $d$Quaint yet beautiful in it's own right.  An essence of craftmanship with
strength bound.  The door is about six feet tall, perhaps four to five feet in
width.  A thick, dark grained wood, with a elegant brass handle.$d$),
  (40, 47, ARRAY['tapestry']::text[], $d$Flowing like wine, the tapesty waves without stillness, as if it were in an
ocean breeze.  The family crest rest in the middle, it consist of a black and
white dragon facing outwards, standing side by side in arms.  A white and black
sword cross each other below the dragons.  A word is sewn below the swords, it
says Chivarly.  Perhaps this is a symbol of partnership or brotherhood.$d$),
  (40, 47, ARRAY['table']::text[], $d$Beauty and elegance have found harmony here.  This table seems to made of the
very same dark wood that all the other wooden creations consist.  Around the
rim of the table the edge has been ribbed, etched into the table itself are two
dragons facing one another.  One seems to be of color, the other without, a
sword meets them between their heads.$d$),
  (40, 54, ARRAY['drapery', 'draperies']::text[], $d$Made of a luscious black velvet, they are about six feet in length, and three
feet wide.  One hanging on each side of the doorway.  Both are torn and faded
in some areas but still hold strongly.$d$),
  (40, 54, ARRAY['walls', 'words']::text[], $d$Changing brightness as if the words were throbing in pain, it's almost as if
they had been written in fire.  Only by source of sorcery could this have been
achieved.  The words are of an unknown language, but perhaps it could be
learned.$d$),
  (40, 54, ARRAY['tapestry']::text[], $d$A large tapestry, at least six feet length and almost that in width.  The
border is done in gold, two snakes criss crossing each other, weaving to their
meeting upon the top.  A king stands proudly, wearing a lavish red cloak and
elegant leather studded armor.  A golden crown rest atop his brow, and his arm
lies on the shoulder of another man.  The other man, stands smiling with his
arm around the kings waist.  The man wears a dark flowing robe over his body,
his hair is black and has a neatly trimmed beard.  Below the men the word
written "Chivarly" stands proudly, sewn in gold.$d$),
  (40, 54, ARRAY['bed']::text[], $d$A lovely four post bed, with an astounding crafted headboard.  It consist of
the same dark wood found else where in the castle rooms and halls.  It's large
indeed, but fit for a king.  The sheets are dark, almost black in color.  It
has a canopy covering the top, with a curtain dangling down.$d$),
  (40, 55, ARRAY['armor', 'suit']::text[], $d$Tarnished and old, it's a set of full plate mail, with bracers and gauntlets.
Ones average height, the helm has a closing gate mask, and steel woven collar.$d$),
  (40, 56, ARRAY['swords', 'axes', 'spears', 'darts', 'southern', 'eastern', 'wall']::text[], $d$Every blade and weapon imaginable is hanging upon these walls.  Double-bladed,
and battle axes.  Bastard, claymore, short, and long swords.  Mixed among them
are assorted spears and throwing darts.  A few are rusty but considering the
length in time that may have passed, they are immaculate.$d$),
  (40, 56, ARRAY['painting']::text[], $d$A noble painting indeed.  The background is cast in black, with a man in full
armor, cradling a small infant.  The mysterious man dons the family crest upon
his armor.  His hair is soulless black, yet a warming smile upon his face.
Below the armored man, is written "Lajon and child".$d$),
  (40, 56, ARRAY['blade', 'sword']::text[], $d$The blade is that of a short sword.  The metal of the blade itself is a
blue-silver steel color.  The handle is wraped in leather with the traditional
handguard.  The faimly crest appears on the blade just above the handle.  The
blood, stained upon the steel, is dried and cracked.  It doesnt seem to have
been touched since the dawn of time.$d$),
  (40, 56, ARRAY['door']::text[], $d$   This is not any usual paint, it seems as if the writting is nearly magical.
It glows faintly, through dim and bright, the point is clear.  The word written
is "Forgiveness!  ", and glows red brightly and dim with intensity.  As if the
feeling that compelled the one to write it, is within it.$d$),
  (40, 57, ARRAY['window', 'light']::text[], $d$The window cast a shallow light through the hall.  Tis a simple but elegant
unstained glass.  Three feet tall and one or two feet wide.  The glass is
clear, without color.  This must be result of magic, for the window itself is
black as night.  The tower itself seems to be underground.  Yet the grey blue
light that haunts the stillness, is glowing from such unknown power.$d$),
  (40, 58, ARRAY['wall']::text[], $d$Oily to the touch, and lay heavy within the lungs.  These walls are caked with
the substance.  The air seems to carry the oil.  Perhaps the oil is what is
causing the tainted air to shimmer and discolor.$d$),
  (40, 58, ARRAY['floor', 'footprints']::text[], $d$At least two inches in depth, the feet that crushed this stone must have been
extremely powerful, or weighty.  The prints are at least two feet in length and
only about a half a foot wide.  Three claws extend forward, they scratched the
stone.  And perhaps a talon on the heel.  These prints seem to have ventured
from the west, and extend to the east.$d$),
  (40, 68, ARRAY['tapestry']::text[], $d$A lovely tapestry indeed.  Simple yet perfectly in order.  It hangs about six
feet long and at least half that in width.  Velvet black, with the family crest
sewn in golden color.$d$),
  (40, 69, ARRAY['corpse']::text[], $d$Alas just bones, the rotted flesh lay beneath where it fell ages before.  The
remains are suspended at least five feet off the ground.  Large strength was
inherited within this dark beast.  The sword thrusted through the chest, right
through the brestplate.  A crown lay smashed only a few feet from the corpse.
Perhaps this was at one time a king of this castle.$d$),
  (40, 72, ARRAY['horn']::text[], $d$Some sort of trumpet perhaps, but a horn indeed.  Golden and dusty, it's made
out of brass.  It may have been a warning signal for the guards to ready
against attack.$d$),
  (40, 74, ARRAY['painting']::text[], $d$Grining wickedly a tall, firmly built, and shadowy creature looks forward, arms
stretched as to touch the planes.  He is consuming a soul, with a look of
maddening enjoyment.  Four moons angle over his head, dawning the only light
within the painting.$d$),
  (40, 74, ARRAY['table']::text[], $d$Made of the same darkened wood as seen elsewhere within the castle walls.  The
table is only four feet tall or so, layered with many candles that would burn
below the painting sitting above.  Carved in the front brim of the table, are
the words "Norhamen, Lord of Darkness"$d$),
  (40, 75, ARRAY['barrel']::text[], $d$The barrel is about the same size as a normal ale keg.  There is no lid and it
seems to be filled with a strong smelling heavy clear oil.$d$),
  (43, 0, ARRAY['columns']::text[], $d$   A ticket booth is built into the entryway.  People can pay a few coins to
see the shows and be entertained for the evening.$d$),
  (43, 1, ARRAY['seat', 'seats']::text[], $d$   Each seat is very soft and comfortable!  Obviously, each patron needs to be
comfortable enough to sit for two solid hours, which these seats definitely
allow for.  Every seat in the house has an excellent view of the stage, making
this an ideal space to watch a performance in.$d$),
  (43, 2, ARRAY['seat', 'seats']::text[], $d$   Each seat is very soft and comfortable!  Obviously, each patron needs to be
comfortable enough to sit for two solid hours, which these seats definitely
allow for.  Every seat in the house has an excellent view of the stage, making
this an ideal space to watch a performance in.$d$),
