  (43, 10, ARRAY['seat', 'seats']::text[], $d$   Each seat is very soft and comfortable!  Obviously, each patron needs to be
comfortable enough to sit for two solid hours, which these seats definitely
allow for.  Every seat in the house has an excellent view of the stage, making
this an ideal space to watch a performance in.$d$),
  (43, 11, ARRAY['ceiling']::text[], $d$   Just as extravagant as the detailed walls, the upper crowing of the theatre
is ringed with faux gold cherubim faces, enclosing a huge dome.  At the apex of
the dome is a huge relief of a golden sun, its beams blazing outward.
Openings in the ceiling allow for lights to be hung and light both the house
and the stage.  In a full production, the stage is lit as if by a multicolored,
radiant sun.$d$),
  (43, 12, ARRAY['ceiling']::text[], $d$   Just as extravagant as the detailed walls, the upper crowing of the theatre
is ringed with faux gold cherubim faces, enclosing a huge dome.  At the apex of
the dome is a huge relief of a golden sun, its beams blazing outward.
Openings in the ceiling allow for lights to be hung and light both the house
and the stage.  In a full production, the stage is lit as if by a multicolored,
radiant sun.$d$),
