  (43, 18, ARRAY['ceiling']::text[], $d$   Just as extravagant as the detailed walls, the upper crowing of the theatre
is ringed with faux gold cherubim faces, enclosing a huge dome.  At the apex of
the dome is a huge relief of a golden sun, its beams blazing outward.
Openings in the ceiling allow for lights to be hung and light both the house
and the stage.  In a full production, the stage is lit as if by a multicolored,
radiant sun.$d$),
  (43, 19, ARRAY['ceiling']::text[], $d$   Just as extravagant as the detailed walls, the upper crowing of the theatre
is ringed with faux gold cherubim faces, enclosing a huge dome.  At the apex of
the dome is a huge relief of a golden sun, its beams blazing outward.
Openings in the ceiling allow for lights to be hung and light both the house
and the stage.  In a full production, the stage is lit as if by a multicolored,
radiant sun.$d$),
  (43, 20, ARRAY['ceiling']::text[], $d$   Just as extravagant as the detailed walls, the upper crowing of the theatre
is ringed with faux gold cherubim faces, enclosing a huge dome.  At the apex of
the dome is a huge relief of a golden sun, its beams blazing outward.
Openings in the ceiling allow for lights to be hung and light both the house
and the stage.  In a full production, the stage is lit as if by a multicolored,
radiant sun.$d$),
  (43, 26, ARRAY['Table', 'Tables', 'Prop', 'Props']::text[], $d$   These tables are where actors are SUPPOSED to return their hand props after
bringing them off stage.  Everything from a fake cigarette, which is cheap and
easily replaceable, to a real steel sword, which is expensive and very, very
dangerous, can qualify as a prop, so it is vital that everything be returned to
its proper place.$d$),
  (43, 30, ARRAY['Table', 'Tables', 'Prop', 'Props']::text[], $d$   These tables are where actors are SUPPOSED to return their hand props after
bringing them off stage.  Everything from a fake cigarette, which is cheap and
easily replaceable, to a real steel sword, which is expensive and very, very
dangerous, can qualify as a prop, so it is vital that everything be returned to
its proper place.$d$),
  (43, 38, ARRAY['tools']::text[], $d$   Saws, hammers, nails, even crank drills are all around this room.
Everything could be described in one of two ways: well loved or junk.$d$),
  (43, 39, ARRAY['tools']::text[], $d$   Saws, hammers, nails, even crank drills are all around this room.
Everything could be described in one of two ways: well loved or junk.$d$),
  (43, 40, ARRAY['tools']::text[], $d$   Saws, hammers, nails, even crank drills are all around this room.
Everything could be described in one of two ways: well loved or junk.$d$),
  (43, 45, ARRAY['makeup', 'counter']::text[], $d$   Every shade of color in the rainbow is scattered about in this dressing
room.  Streaks and stains are all over the mirror and the counter.$d$),
  (43, 45, ARRAY['mirror']::text[], $d$   Are those lip prints on the mirror?  Was the actor seriously kissing his own
reflection?!  Something else catches your attention though.  It looks like
something is poking out from behind the mirror.$d$),
  (43, 47, ARRAY['couch']::text[], $d$   Wow, this thing is filthy!  Talk about your second-hand goods.  Someone
probably picked this up off the street and stuck it in here for lack of a
better place to put it.$d$),
  (43, 49, ARRAY['couch']::text[], $d$   Though the actual couch is falling apart, a make-shift cover of clean sheets
has been tucked over it, and a few pillows are tossed onto the couch for
effect.  Fortunately, the sheets are very dark in color so most stains don't
show on it, though an occasional makeup streak is visible.$d$),
  (43, 49, ARRAY['star']::text[], $d$   Written in beautiful, flowing script is the name and title, 'Fastrada, Queen
of all that is'.$d$),
  (43, 52, ARRAY['Note', 'notes', 'poster', 'posters']::text[], $d$   Tacked on one of the walls is a large piece of paper that reads, 'The part
is to be portrayed by an actor of enormous power!  ' The actor has obviously
let the 'power' go to his head.$d$),
  (43, 53, ARRAY['book']::text[], $d$   Quick, easy recipies are combined with every happy homemaker's desire to
make her husband both happy and dead.  Seditious plots against every Emperor in
history are laid out in detail, along with suggested deviations to '...  Keep
your homemade plot from becoming too cliche and most importantly, too
noticeable.  ' What kind of housewife and mother could possibly need a book
like this?$d$),
  (43, 58, ARRAY['pile', 'piles', 'garbage']::text[], $d$   Old costumes, parts of old sets, rotten food, pages from old scripts, even
production posters litter the loft.  A couple of the piles have been pushed
together though, almost like something was using them as a bed.$d$),
  (43, 59, ARRAY['pile', 'piles', 'garbage']::text[], $d$   Old costumes, parts of old sets, rotten food, pages from old scripts, even
production posters litter the loft.  A couple of the piles have been pushed
together though, almost like something was using them as a bed.$d$),
  (43, 60, ARRAY['pile', 'piles', 'garbage']::text[], $d$   Old costumes, parts of old sets, rotten food, pages from old scripts, even
production posters litter the loft.  A couple of the piles have been pushed
together though, almost like something was using them as a bed.$d$),
  (43, 61, ARRAY['pile', 'piles', 'garbage']::text[], $d$   Old costumes, parts of old sets, rotten food, pages from old scripts, even
production posters litter the loft.  A couple of the piles have been pushed
together though, almost like something was using them as a bed.$d$),
  (43, 62, ARRAY['pile', 'piles', 'garbage']::text[], $d$   Old costumes, parts of old sets, rotten food, pages from old scripts, even
production posters litter the loft.  A couple of the piles have been pushed
together though, almost like something was using them as a bed.$d$),
  (43, 63, ARRAY['pile', 'piles', 'garbage']::text[], $d$   Old costumes, parts of old sets, rotten food, pages from old scripts, even
production posters litter the loft.  A couple of the piles have been pushed
together though, almost like something was using them as a bed.$d$),
  (51, 71, ARRAY['amulet']::text[], $d$On his chest is an amulet with odd inscriptions.
It even seems to glow somewhat with a circular
pattern within as though it has had a piece
removed.....$d$),
  (51, 71, ARRAY['dagger']::text[], $d$   The sorcerer's dagger looks crude but sharp nonetheless.  It also seems to
glow with the same energy as the lightning?$d$),
  (51, 90, ARRAY['stone']::text[], $d$It looks like the other side has been carefully fitted to the wall. You'd
be willing to bet that you're looking at the other side of a secret door!$d$),
  (53, 15, ARRAY['floor', 'mandala']::text[], $d$   The mandala encompasses nearly the entire floor.  Traditional colors - deep
blues, rich reds, vibrant yellows, and calming greens - are incorporated to
stimulate different chakras and aspects of consciousness.$d$),
  (54, 1, ARRAY['sign', 'plaque', 'writing', 'wall']::text[], $d$
Beware! Unknown evils lie below...
  --Stratos GreyCloak$d$),
  (54, 1, ARRAY['portal', 'gate', 'gateway', 'opening', 'door']::text[], $d$The portal appears to shimmer in and out of existance, as if not entirely of
this world. Perhaps it leads to some OTHER world? Looks easy enough to open.$d$),
  (54, 2, ARRAY['portal', 'gate', 'gateway', 'door', 'opening']::text[], $d$The portal appears to shimmer in and out of existance, as if not entirely of
this world. Perhaps it leads to some OTHER world? Looks easy enough to open.$d$),
  (54, 61, ARRAY['writing', 'glowing', 'inscription', 'sign', 'plaque', 'wall', 'west', 'western']::text[], $d$
The evil seems to be strongest to the south. Be careful!
  --Stratos GreyCloak$d$),
  (55, 5, ARRAY['sign', 'signpost', 'post']::text[], $d$* * * * * WARNING! * * * * *

You are entering an area of active combat between the forces of good and
evil. We don't care which side you are on just know that goodies should
go east and evils should go west.  We're not helping you get your dead
stinkin carcass back either so don't come crying to us.$d$),
  (60, 5, ARRAY['peephole', 'peep', 'hole']::text[], $d$Looking through the peephole, you can barely see the next room.  Something
is partially covering the peephole.$d$),
  (60, 15, ARRAY['gate', 'gates']::text[], $d$The gates are sealed and, when you look closely, you see that there are slits
that have dwarven eyes peering suspiciously out. You wonder what could have
happened for the dwarves to seal themselves in like that.$d$),
  (60, 26, ARRAY['warehouse', 'remains']::text[], $d$The warehouse is old and falling apart.  Many of the windows are missing as
are large portions of the roof.  A door lies open before you.$d$),
  (60, 29, ARRAY['crate']::text[], $d$This is an old crate, the wood broken and rotted. What's left of its
contents is strewn about on the floor with rat droppings in it.$d$),
  (60, 35, ARRAY['rope']::text[], $d$The rope is very thick and extends down through a trapdoor in the floor.
The rope has many knots to ease your climb down.$d$),
  (60, 43, ARRAY['crate']::text[], $d$This is an old crate, the wood broken and rotted. What's left of its
contents is strewn about on the floor with rat droppings in it. It
looks like there might be a trapdoor under the crate.$d$),
  (60, 43, ARRAY['trapdoor']::text[], $d$Moving a crate, you find a trapdoor. Looking at the trapdoor, you get a
sense of evil, as if evil had taken a physical form and became this door.$d$),
  (60, 44, ARRAY['furniture', 'broken']::text[], $d$This is what looks like the remains of a table and several chairs. It
looks as if an elephant sat on them.$d$),
  (60, 45, ARRAY['menu', 'wall']::text[], $d$              Welcome to Shingle's Soup Kitchen!
                    Today's Specials Are:
        SOS on a Plate ...................... 25 coins
        SOS on a Roll  ...................... 15 coins
        SOS on a Shingle .................... 1 coin$d$),
  (60, 53, ARRAY['east', 'bar']::text[], $d$The room is rather packed tonight. You can see a set of stairs going
up to the private rooms and a casino just to the south of the bar.$d$),
  (60, 53, ARRAY['man', 'colorful']::text[], $d$You see a colorful man before you. He is dressed in silks of from many
parts of the world and is seemingly a pleasant man. But as you watch him,
you can see him give an experienced look at you from the corner of his
eye, as if sizing you up. I'm sure he's just looking to see if you're
going to cause trouble. Or is he..
The Colorful Man is in  excellent condition.$d$),
  (60, 54, ARRAY['bar']::text[], $d$The bar here is quite busy tonight. People of all races and sizes are
pushing their way up to the bar. There is a sign above the bar.$d$),
  (60, 54, ARRAY['sign']::text[], $d$                Welcome to the Red Feathered Nest!
                          House Rules
                      =================
                        1) No Fighting
                        2) No Spitting
                        3) If you aren't drinking, get out
                           and make room for someone that is$d$),
  (60, 63, ARRAY['cask', 'beer', 'secret']::text[], $d$You see a large cask of filled with beer. But something about it is strange.
The other casks have water droplets forming on them, this one doesn't.$d$),
  (60, 66, ARRAY['rope']::text[], $d$The rope is heavy, but very worn from a lot of use.  It is knotted to ease
your climb down.$d$),
  (60, 70, ARRAY['walls', 'marble', 'streaks']::text[], $d$The marble walls seem to suck up the light from your lantern. The red
streaks in the marble DO look like blood and on closer examination,
there are dried spots on the wall.$d$),
  (60, 70, ARRAY['spots', 'dried', 'blood']::text[], $d$This can only be dried blood. Bits and pieces of hair and bone fragments
are clotted into the spot. Something died very violently here.$d$),
  (60, 71, ARRAY['archway', 'door']::text[], $d$The archway is carved with a strange style... not quite dwarven but
the workmanship is exquisite, assuming you like bones and skull decor.
But wait a second.. those don't look quite like stone...$d$),
  (60, 71, ARRAY['bone', 'bones', 'skull']::text[], $d$Upon closer examinationon the archway's construction, you can see that
the bones and skulls aren't carved, but REAL! The bones are from dwarves,
elves, humans and even some from creatures that you don't even recognize.
It looks as if the red light is holding them together to form this arch.$d$),
  (60, 71, ARRAY['carvings', 'carving']::text[], $d$Red carvings on a black field read:

    "Welcome to the Temple of Blackmourne. Enter and pay homage."$d$),
  (60, 72, ARRAY['statue', 'skeleton']::text[], $d$The statue is forged from a strange metal, the like you've never seen
before. It is blackish and has a strange shine to it. The skeleton
itself is that of a warrior, judging from its build, whoever it was
must have been huge in life. Its four fingers are wrapped around an
ancient sword.$d$),
  (60, 72, ARRAY['sword', 'ancient']::text[], $d$This sword dates back at least 300 years, to the time of the Rift Wars.
The workmanship on the blade is the best you have even seen.$d$),
  (60, 76, ARRAY['altar']::text[], $d$The altar that stands before you has a groove cut down the center that
leads to a spigot, underneath which can be placed a bucket or container.
The groove is stained in blood. The altar itself is made of a strange metal,
the carvings look too realistic to have been carved by hand. This altar
has an evil aura about it, as if it was alive.$d$),
  (60, 76, ARRAY['crack']::text[], $d$There is a small crack between the altar and the floor. Maybe the altar
can be moved to reveal what is underneath.$d$),
  (60, 89, ARRAY['shelves']::text[], $d$The shelves are lined with many books and ceremonial trappings. There
is a chest on one of the shelves.$d$),
  (61, 6, ARRAY['board', 'bulletin']::text[], $d$Under the rosters and duty assignments you see a wanted poster that reads:

***************************************************************************

                                 WANTED
                              DEAD or ALIVE
                            (preferably DEAD)

                                L O G A N

                            1,000,000,000 coins$d$),
  (61, 12, ARRAY['behemoth', 'giant', 'head']::text[], $d$This is the most ugly behemoth head you have ever seen! (If you have
ever seen any.) Underneath the head is a small brass plaque.$d$),
  (61, 12, ARRAY['sign']::text[], $d$The sign reads:

Instructions provided by Shawn (Who else would.)

               BUY  - Buy a drink from Shawn (That's me)
               LIST - Shawn will show you a list of the
                      local specialties with prices.

               Don't ask to run a tab!!!!!! No credit here!$d$),
  (61, 19, ARRAY['fountain', 'monument']::text[], $d$The fountain is huge. It is made of black marble and looks like it took many
men many months to make. There is some writing carved onto it. It has a
strange aura around it.$d$),
  (61, 19, ARRAY['writing', 'carving']::text[], $d$To all those of MEGADEATH gone from us and those still alive:
                  You will not be forgotten.

              "The Few, The Proud, The Well Armed"$d$),
  (61, 26, ARRAY['sign']::text[], $d$The sign reads.

           BUY   -  Buy something on the list
           LIST  -  List goods for sale with prices
           VALUE -  The Grocer will tell you how much
                    he will pay you for an item.
           SELL  -  To sell an item to the Grocer.
                    (Assuming he wants to buy it)$d$),
  (61, 35, ARRAY['sign']::text[], $d$The sign reads as follows:

              WELCOME to Jarad Grindstone's Dwarven Bakery!
               The Finest Bread goods this side of Anduin

             List - Jarad will give you a list of breads available
                    for sale with the price.
             Buy  - Buy one of Jarad's fine breads or pastries

                    All service with a smile!   8-)$d$),
  (61, 63, ARRAY['crate']::text[], $d$  This crate is filled with weapons and armours that look like they've seen
many a battle.$d$),
  (62, 24, ARRAY['sign']::text[], $d$The sign reads:

     Our many friends in the magical and wisdom-seeking fields will
     especially appreciate our fine clothing.$d$),
  (80, 26, ARRAY['fence']::text[], $d$The fence looks very sturdy, but could use a coat of
paint! There are some small holes in the fence.
Through the holes you see glimpses of a forest, it
looks impassable.$d$),
  (80, 50, ARRAY['fence']::text[], $d$The fence looks very sturdy, but could use a coat of
