  (83, 31, ARRAY['engravings', 'engraving']::text[], $d$                        Inside this Tree rests the great Injoni Rif
                             May this God among men R.I.P.$d$),
  (85, 3, ARRAY['gate', 'huge_gate', 'huge']::text[], $d$You are dwarfed by this massive gate. It pulsates with color and is made
of some material you are totally unfamiliar with. As you reach your hand out
and touch the gate, you are surprised that it is ice cold. Then before
you can pull your hand away it instantly becomes white-hot. The only
thing you are sure of is the craftsmanship is amazing, definitely dwarven
in origin.$d$),
  (85, 4, ARRAY['gate', 'huge_gate', 'huge']::text[], $d$You are dwarfed by this massive gate. It is jet black in color and made
of some material you are totally unfamiliar with. As you reach your hand out
and touch the gate, you are surprised that it is ice cold. Then before
you can pull your hand away it instantly becomes white-hot. The only
thing you are sure of is the craftsmanship is amazing, definitely dwarven
in origin.$d$),
  (85, 9, ARRAY['tombstone', 'desecrated']::text[], $d$This tombstone has almost been completely destroyed by some unknown person
or creature. The only thing you can make out is a partial name, B r  k.
Most of the letters are illegible. It appears as something is carved into the back of the tombstone.$d$),
  (85, 9, ARRAY['back']::text[], $d$You finally manage to turn the tombstone over, piecing together some parts
you read:
You may have cheated death for now, but I have all eternity.
There is more but you can't seen to make it out.$d$),
  (85, 10, ARRAY['arch', 'typanum']::text[], $d$An intricate carving of immense detail. It seems to depict this Cathedral and
the surrounding graveyard. The sky as depicted is ripped open and there are
demons and lightning flooding down from the heavens. It also appears that there
are a pair of huge, evil eyes in the background.$d$),
  (85, 24, ARRAY['outline']::text[], $d$Yep its an outline. It's the outline of a door. There is no visible way
to open it and the veins running through the stone are very strange.$d$),
  (85, 24, ARRAY['vein', 'veins']::text[], $d$The veins of this rock are not some colored mineral, but actual veins
that pulse rhythmically, as blood flows through.$d$),
  (85, 24, ARRAY['words', 'carved-words']::text[], $d$The language is one that you have never seen, yet you know what it says:
Know the name of who you seek.$d$),
  (85, 27, ARRAY['glass', 'stained', 'stained_glass', 'stained-glass']::text[], $d$In this final rendering the glass is mostly black. There is a pair of red
demon eyes in the background. In the foreground is the priest, drawn and
quartered, his soul is forcibley being extracted from his body. Blood flows
from his eyes. It drips down the glass and runs down the wall.$d$),
  (85, 28, ARRAY['stained', 'glass', 'stained-glass', 'stained_glass']::text[], $d$The glass starts with a rendering of this church. A solitary man stands at the
pulpit, preaching. It appears all is normal. Except for a pair of floating
eyes in the background, watching with great interest. A single letter
sits atop each of the stained glass windows, carved from solid gold.$d$),
  (85, 29, ARRAY['glass', 'stained_glass', 'stained-glass', 'stained']::text[], $d$This next rendering seems to take place on the Observation Balcony you
observed, when you entered. The priest from the previous glass seems to be
cohorting with some properly dressed individuals. The tone and colors have
changed from light to very dark.$d$),
  (85, 31, ARRAY['glass', 'stained', 'stained-glass', 'stained_glass']::text[], $d$The next scene shows the priest surrounded by horrid demons, cowering
in the corner. The ciborium lies at the feet of a HUGE demon, and some of the
red liquid runs out of the corner of his mouth. It is pointing at the priest
and laughing. In the background the sky is black and demons and creatures
pour down from the sky.$d$),
  (85, 32, ARRAY['glass', 'stained', 'stained-glass', 'stained_glass']::text[], $d$In this scene, the priest is sharing a meal and drink with fellow priests
and some of the properly dressed individuals. You notice the ciborium and other
vessels are all filled with the liquid from the fountain. Strangely the shadows
cast by the people in the glass are that of demons.$d$),
  (85, 34, ARRAY['glass', 'stained', 'stained-glass', 'stained_glass']::text[], $d$The priest from the original is now shown speaking to something that is cloaked
in the shadows. In the background is a small ornate fountain and next to it a
beautiful ciborium sits, filled with an unknown red liquid.$d$),
  (85, 38, ARRAY['bookshelf']::text[], $d$A simple, worn bookcase stands here against the wall. With hundreds of titles
on the shelf a true intellectual would be happy for years.$d$),
  (85, 39, ARRAY['statue', 'crowning', 'crowning_statue']::text[], $d$The statue is highly polished marble and beautilully carved. It is the in likeness
of the founder of this Cathedral, Ziijhan. The statue seem to have undergone
some type of metamorphosis, but not by any physical means. Some unknown power
has turned the statue into a frightening humanoid. Its eyes glow blue. It is
watching.$d$),
  (85, 39, ARRAY['clerestory']::text[], $d$Red stained-glass windows grace the clerestory high above. A creepy red light
filters down, turning everything in sight blood-red.$d$),
  (85, 39, ARRAY['table', 'sacrificial_table', 'sacrificial']::text[], $d$A mysterious black cloth, with tiny flecks of gold sparkles as it lies
across the table. Its beautiful, but in the same way as an arrow frog is
beautiful.$d$),
  (85, 49, ARRAY['clerestory']::text[], $d$The errie light that filters down through the windows above is caused not by
red stained glass, but from clear glass coated with a thick film of red blood
that flows over them.  You can see it drips down, yet never hits the altar
below.$d$),
  (85, 52, ARRAY['clerestory']::text[], $d$The errie light that filters down through the windows above is caused not
by red stained glass, but from clear glass coated with a thick film of red
blood that flows over them. You can see it drips down, yet never hits
the Altar below.$d$),
  (85, 78, ARRAY['mold', 'indentation']::text[], $d$It is in the shape of a cross and crescent moon. It looks like something
could fit inside of it.$d$),
  (85, 78, ARRAY['symbols', 'unholy', 'symbol', 'unholy-symbols']::text[], $d$Several symbols cover the wall here. The are all raised off the wall except
one, which is more like an mold or and indentation.$d$),
  (86, 46, ARRAY['rotted', 'wooden', 'sign']::text[], $d$It reads:
All is quiet on all fronts. Enjoy the peace and prosperity brought to us by the king.$d$),
  (86, 54, ARRAY['small', 'sign']::text[], $d$It reads:
Next guard meeting 15:00.
Next training-- day of the coyote, 06:00

Captain of the Guard$d$),
  (86, 58, ARRAY['sign', 'golden']::text[], $d$It reads:
Residence of the King and Queen of the MeerCats, meetings by appointment only.
NO Trespassing!!!$d$),
  (88, 3, ARRAY['hedge']::text[], $d$It's just a shrubbery hedge, but it's kept perfectly pruned, and is
dotted with little pink flowers amidst its dark green leaves.$d$),
  (100, 1, ARRAY['alcove']::text[], $d$This alcove is empty.  Once it seems that there were some candles or other
religious articles placed here, but for now there is nothing.$d$),
  (100, 6, ARRAY['rose', 'arctic', 'roses', 'vine', 'vines', 'pillar', 'pillars']::text[], $d$Seeming too delicate to survive in this harsh environment, the blue arctic rose
represents the arctic god Haddixx.$d$),
  (102, 33, ARRAY['picture', 'pictures', 'wall', 'walls', 'animals']::text[], $d$There is a large cat here, carved into the ice on the northern wall.  On the
ceiling are some smaller symbols, including a tiny triangle surrounded by
spheres and the the inscription "Kourrya 2008".$d$),
  (102, 36, ARRAY['graffiti', 'picture', 'pictures']::text[], $d$Cut into the ice is a large picture of a feline with rather ferocious-looking
fangs, surrounded by other symbols like a lightning bolt, a sun, a snowflake,
and other weather-related pictograms.$d$),
  (103, 2, ARRAY['sculptures']::text[], $d$   One sculpture really catches the eye: a purple teardrop shed from a blue
eye.  The artist's signature on the piece says "Kourrya 2006".$d$),
  (103, 6, ARRAY['altar']::text[], $d$   A single flame has been carved into the stone of the altar and embossed with
silver.  Below it in tiny Elven runes is the inscription: "Lost, but never
forgotten.  Rick Sala 6-21-2006"$d$),
  (103, 7, ARRAY['sign', 'list', 'prices', 'price', 'services']::text[], $d$Hot Springs -    Red Token
Massage -        Blue Token
Gourmet Meal -   Green Token$d$),
  (103, 36, ARRAY['bed', 'pillow', 'pillows', 'quilt', 'quilts']::text[], $d$This single bed is set into the wall of the room under the north window.
Piled high with handmade quilts and embroidered pillows, it would make a superb
reading nook or napping spot.  The colors of the quilts and pillows don't seem
to have any pattern to them, as nearly every color imaginable is represented.$d$),
  (117, 74, ARRAY['puddles', 'puddle', 'mud', 'muddy']::text[], $d$The mud is thick, gooshing around anything that comes in contact with it.
There are several small puddles of it , seemingly footsteps of something large.$d$),
  (117, 90, ARRAY['purple', 'little', 'flower', 'bizarre']::text[], $d$This flower is rather small and pointy.  It has large leaves for the size of
the stem.  Both the leaves and the stem are a dull, purple hew, while the bud
of an omni-present flower atop the stem is a much more lush purple.$d$),
  (117, 102, ARRAY['carving', 'stone', 'stones', 'rocks', 'little', 'side']::text[], $d$The little carving on the side of the large, sharp stone is an ancient, dead
text.  Next to the writing is a little carving of what appears to be a giant
lizard of some indistinguishable form.  The other little rocks about truly look
to be blood-stained from many years ago, as the weather has nearly washed them
clean.$d$),
  (117, 123, ARRAY['rock', 'break', 'hole']::text[], $d$There is a small hole in the wall, perhaps large enough for a person to squeeze
through.  The jagged rocks would be painful if they somehow grabbed some skin
on the way through.  Inside through the hole is a dark cavern.$d$),
  (120, 14, ARRAY['altar']::text[], $d$Ancient etchings trace the edge of the altar's surface.  The letters are old
and worn, barely legible after all these ages.  They read:

"Ah! A nimble mind and wakened body. Truly coffee is a gift of the spirit."$d$),
  (120, 15, ARRAY['tree', 'trees']::text[], $d$The trees are mighty beyond all comprehension.  Dried graying moss clings to
the bark, but they are otherwise untouched by any sign of corruption.  Lesser
trees do crowd around their bases.  Perhaps seeking a drink from the precious
water that flows here, but none intrude into this central place.  The massive
Rhell trees seem to stretch up beyond the reach of vision.$d$),
  (120, 16, ARRAY['altar']::text[], $d$Ancient etchings trace the edge of the altar's surface.  The letters are old
and worn, barely legible after all these ages.  They read:

"If a man has no tea in him, he is incapable of understanding truth and beauty."$d$),
  (120, 17, ARRAY['altar']::text[], $d$Ancient etchings trace the edge of the altar's surface.  The letters are old
and worn, barely legible after all these ages.  They read:

"When ale thou quaffest, call upon earth's might - 'tis earth drinks in the floods."$d$),
  (120, 18, ARRAY['altar']::text[], $d$Ancient etchings trace the edge of the altar's surface.  The letters are old
and worn, barely legible after all these ages.  They read:

"Water is the most perfect traveller because when it travels it becomes the path itself!"$d$),
  (120, 22, ARRAY['building', 'structure']::text[], $d$It is quite some distance to the southwest.  From here, it is only possible to
determine that it rises a single story, and that it is in a state of disrepair.$d$),
  (120, 26, ARRAY['sapling', 'saplings']::text[], $d$   The young rhells are brave, but their elder siblings demonstrate the
difficulty of surviving long in these woods.  The larger the Rhell, the
sicklier it is (excluding the mighty adults), and no young Rhell is taller than
fifty feet, save a few lifeless husks.  Nevertheless, a few small saplings
strive vigorously.$d$),
  (120, 33, ARRAY['track', 'tracks']::text[], $d$The tracks of deer are easily seen, along with smaller less clear impressions.
Bootprints, fairly common on the path to the south, are much less common here.$d$),
  (120, 34, ARRAY['mist', 'blue']::text[], $d$The mist curls up in loose tendrils, to the west, in a roughly parallel
north-south path that lies within view, though depressed into the ground
slightly.  Perhaps there is a cliff near there, and the path is below that.
That is the only explanation you can think of for the light blue mist, which
seems magical in nature.$d$),
  (120, 34, ARRAY['track', 'tracks']::text[], $d$There are as many tracks on the ground here as elsewhere, and bootprints can be
seen here and there.  But while there is nothing strange about the animal
tracks, the bootprints seem to be traveling in a loop - as if the traveler
tended to enter from the south, but usually turn back again.  There is no
obvious reason for this behavior.$d$),
  (120, 46, ARRAY['altar']::text[], $d$Ancient etchings trace the edge of the altar's surface.  The letters are old
and worn, barely legible after all these ages.  They read:

"Yet do I fear thy nature; it is too full o' the milk of human kindness to catch the nearest way."$d$),
  (120, 48, ARRAY['tracktracks', 'bootprint', 'bootprints']::text[], $d$The dry ground is somewhat dusty, so the prints of larger creatures can be
seen.  The tracks of deer are particularly obvious.  There are plenty of
bootprints too, going both north and south along the path.$d$),
  (120, 49, ARRAY['mist', 'blue']::text[], $d$The mist curls up in loose tendrils, to the west, in a roughly parallel
north-south path that lies within view, though depressed into the ground
slightly.  Perhaps there is a cliff near there, and the path is below that.
That is the only explanation you can think of for the light blue mist, which
seems magical in nature.$d$),
  (120, 49, ARRAY['track', 'tracks', 'bootprint', 'bootprints', 'prints']::text[], $d$Animal tracks crisscross the ground.  Among them are the prints of heavy boots,
traveling in both directions.$d$),
  (120, 76, ARRAY['blue', 'fog', 'wall']::text[], $d$The fog is clearly of supernatural origin. Its evil nature is
obvious to you; nothing this thick and mysterious can be here
for any good reason.$d$),
  (120, 77, ARRAY['blue', 'fog', 'wall']::text[], $d$The fog is clearly of supernatural origin. Its evil nature is
obvious to you; nothing this thick and mysterious can be here
for any good reason.$d$),
  (120, 91, ARRAY['structure', 'manger', 'shelter']::text[], $d$The wooden structure is so rickety it sways dangerously even in the
most gentle of winds. It looks like it'd fall apart at a harsh word.
But you can see that it's age, not bad building, that account for
this shelter's condition. The center of the structure has a manger
built into it.$d$),
  (120, 92, ARRAY['bones', 'skeletons']::text[], $d$The skeletons appear to be of tiny animals. Some appear to be those
of dogs, or cats, or small rodents, but you can spot some impossibly
small deer-like ones as well.$d$),
  (120, 92, ARRAY['jar', 'jars', 'glass', 'shelves']::text[], $d$The wooden shelves are falling apart now, but at one time they must
have lined the entire west and south walls. Glass jars of varying
sizes and appearance crowd what few standing shelves there are, with
shards all over the floor marking where jars were once. Most of the
jars are empty, with a weird slimy film coating their insides, but
in some, you can see various bones and skeletons.$d$),
  (120, 98, ARRAY['wall', 'mist', 'fog', 'mists', 'glow']::text[], $d$The glowing wall seems as soft as clouds, but when you reach out
to touch it, you discover it's as solid as stone. The wisps of fog
seem to pulse with hidden anger as you approach, and it's with relief
that you back off.$d$),
  (120, 100, ARRAY['wall', 'mist', 'fog', 'mists', 'glow']::text[], $d$The glowing wall seems as soft as clouds, but when you reach out
to touch it, you discover it's as solid as stone. The wisps of fog
seem to pulse with hidden anger as you approach, and it's with relief
that you back off.$d$),
  (120, 105, ARRAY['statue']::text[], $d$The statue is of a man whose features are very unlike those of an
Ickle or Mielikki resident. The man wears ragged chain mail and
other armors, and he raises his sword in defiance. In one hand he
holds what seems to be a wand. Cloudy vapors seem to cling to the
tip of the wand. A bronze plaque at the base of the statue has
seen many better days.$d$),
  (120, 105, ARRAY['plaque']::text[], $d$The plaque reads:

                  And so we call the mists.$d$),
  (120, 133, ARRAY['door']::text[], $d$The door's made of thick blackened wood. At some point in the past,
it must have been set on fire, but it still seems strong.$d$),
  (120, 141, ARRAY['tree']::text[], $d$The tree is easily the biggest, mightiest plant you've ever
seen in your life. Oddly enough, though, someone's put a gate
into its trunk, near the floor.$d$),
  (120, 142, ARRAY['texts', 'text']::text[], $d$The texts are ancient, clearly, and they are written on some kind
of thick parchment. They all seem to have pictures of animals
on them.$d$),
  (120, 157, ARRAY['bark']::text[], $d$The bark seems to have a regularity to it that looks almost unnatural.
Careful inspection of the tree's trunk reveals a little panel set into
it.$d$),
  (120, 157, ARRAY['panel']::text[], $d$The panel has a tiny little lock embedded into its surface. If you hadn't
gone looking for it, you'd never have found it.$d$),
  (123, 0, ARRAY['footprints']::text[], $d$It's hard to judge numbers from the remaining tracks, but it seems like a large
number of people recently traveled through here.$d$),
  (123, 1, ARRAY['Footprints']::text[], $d$It's hard to judge numbers from the remaining tracks, but it seems like a large
number of people recently traveled through here.$d$),
  (123, 2, ARRAY['Depression', 'depressions', 'channel', 'channels', 'ditch', 'ditches', 'trench', 'trenches', 'embankment', 'embankments']::text[], $d$The channels here are barely noticeable with all the groundcover and grasses
growing over them.  Since this path seems to predate the use of roads in South
Caelia, it's unlikely these are gutters.  Most likely they served as a trail
marker or something more ceremonial to delineate between the cultivated and the
wild.$d$),
  (123, 2, ARRAY['trees']::text[], $d$The towering trees are a mix of species, from oak to Rhell.  None of them seem
to be moving of their own volition, but with so many, its hard to be certain.$d$),
  (123, 3, ARRAY['Depression', 'depressions', 'channel', 'channels', 'ditch', 'ditches', 'trench', 'trenches', 'embankment', 'embankments']::text[], $d$The channels here are barely noticeable with all the groundcover and grasses
growing over them.  Since this path seems to predate the use of roads in South
Caelia, it's unlikely these are gutters.  Most likely they served as a trail
marker or something more ceremonial to delineate between the cultivated and the
wild.$d$),
  (123, 3, ARRAY['trees']::text[], $d$The towering trees are a mix of species, from oak to Rhell.  None of them seem
to be moving of their own volition, but with so many, it's hard to be certain.$d$),
