  (123, 7, ARRAY['debris']::text[], $d$Over the centuries, branches and trees have fallen over the avenue, making the
path impassable.  It would take an extraordinary amount of work to clear the
avenue again.$d$),
  (123, 7, ARRAY['trees']::text[], $d$The towering trees are a mix of species, from oak to Rhell.  None of them seem
to be moving of their own volition, but with so many, it's hard to be certain.$d$),
  (123, 7, ARRAY['Lights']::text[], $d$Pale motes of various pastel colors fade into being and slowly vanish.
Perhaps they're fireflies, but they seem rather large for bugs...$d$),
  (123, 8, ARRAY['trees']::text[], $d$The towering trees are a mix of species, from oak to Rhell.  None of them seem
to be moving of their own volition, but with so many, it's hard to be certain.$d$),
