  (123, 45, ARRAY['footprints']::text[], $d$At first, the prints clearly show they were left by people with booted feet.
Studying them a moment longer, you realize it wasn't a group of people, but
just a single person, walking constantly in the same direction.  It seems
someone has been constantly walking in a circle along the path, though the
reason is unclear.$d$),
  (123, 45, ARRAY['trees']::text[], $d$The towering trees are a mix of species, from oak to Rhell.  None of them seem
to be moving of their own volition, but with so many, it's hard to be certain.$d$),
