  (123, 97, ARRAY['Symbols,', 'drawings,', 'symbol,', 'drawing']::text[], $d$Most of the imagery appears devotional in nature.  Numerous images depicting
the stars, the sun, and the moon, and various kinds of beings observing or
perhaps singing to them cover the cave.  One of the images depicts three sacred
Druidic symbols, the Holly, the Mistletoe, and the Sickle, combined with the
moon and a pentagram.  Yet another portrays the moon hanging over a pond or
spring.$d$),
  (123, 98, ARRAY['Symbols,', 'drawings,', 'symbol,', 'drawing']::text[], $d$Most of the imagery appears devotional in nature.  Numerous images depicting
