  (125, 34, ARRAY['door', 'doors']::text[], $d$The door is a single block seemingly carved from the wall mass itself.  Three
protrusions extend from the door into the wall, and in the cracks between the
protrusions and the wall, a stone rod goes through the protrusions and the
wall, forming a giant stone hinge.
(No pun intended)$d$),
  (125, 34, ARRAY['stone', 'stones', 'circle', 'inset']::text[], $d$There are fourteen stones set in a circle.  Each stone has a rune carved out of it, filled with
gold.$d$),
  (125, 45, ARRAY['circle', 'stones']::text[], $d$A full circle is depressed in the in the ground.  Twelve trapezoidal stones are
spaced evenly about the circle, with a thirteenth spot open.  Each of the
stones has an rune carved into it, and filled with gold.$d$),
  (133, 17, ARRAY['hole', 'odd', 'walls']::text[], $d$   It looks like this is a place where the dwarves saw a small mineral
inclusion they wanted and mined it out of the sides of the walls.$d$),
  (133, 18, ARRAY['bench', 'benches', 'walls']::text[], $d$   There are a few stone benches along the walls here, set up in case some
dwarves need to take a short break.$d$),
  (133, 28, ARRAY['shadows']::text[], $d$   The shadows in this room barely conceal a rough emblem chiselled into the
western wall: an inverted triangle surrounded by three spheres.  Someone
apparently put it here as homage to the goddess Kourrya.$d$),
  (133, 29, ARRAY['alcove', 'eastern', 'wall']::text[], $d$   Upon closer inspection, the sides of the drilled alcove look to be made of
kimberlite.  There were diamonds here once.$d$),
  (133, 56, ARRAY['stalactite', 'stalagmite', 'stalactites', 'stalagmites']::text[], $d$   There is one due north, and then othersto the northeast, northwest,
southeast, and southwest.  If one were to connect them in the right way, they
would form a pentagram.$d$),
  (133, 58, ARRAY['runes']::text[], $d$These runes give off a picture of a hungry person giving a wonderfull reward
for helping him.$d$),
  (133, 60, ARRAY['sign']::text[], $d$The sign in the room reads.  Make your self at home drink and fill your
canteens if needed.$d$),
  (160, 6, ARRAY['well']::text[], $d$As you peer into its depths, you notice that there are metal spikes
jammed into the walls, something like a makeshift staircase. An aura of
mystery and danger surrounds you...... You are unsure whether or not
you should venture down. A trap maybe?$d$),
  (160, 9, ARRAY['hoofprints', 'track', 'tracks']::text[], $d$The tracks look fresh, as if horses had just been stabled here. But as you
look closer, you realise that no animal you know had made these tracks.$d$),
  (160, 9, ARRAY['stable']::text[], $d$The stables looks run down and battered but you notice that there are
fresh tracks leading out from the building.$d$),
  (160, 18, ARRAY['masonry', 'stones', 'wall']::text[], $d$The masonry has been badly shattered, rubble lies everywhere. You have to
tread carefully as not to trip on the loose rock.$d$),
  (160, 20, ARRAY['masonry', 'stones', 'wall']::text[], $d$The masonry has been badly shattered, rubble lies everywhere. You have to
tread carefully as not to trip on the loose rock.$d$),
  (160, 22, ARRAY['engines', 'siege']::text[], $d$The great siege engines which once defended this keep were reduced to
shattered burnt out hulks.$d$),
  (160, 22, ARRAY['masonry']::text[], $d$The stonework has been shattered, and debris lies all over the ground.
You have to walk carefully to avoid tripping over all this rubble. This
mist only makes the conditions worse.$d$),
