  (160, 37, ARRAY['creature']::text[], $d$It seems to be waving it's hands around in the fog. Sometimes, the
fog suddenly lights up as if there is lightning in there, just like
a storm cloud.$d$),
  (160, 39, ARRAY['creature']::text[], $d$It seems to be waving it's hands around in the fog. Sometimes, the
fog suddenly lights up as if there is lightning in there, just like
a storm cloud.$d$),
  (160, 41, ARRAY['creature']::text[], $d$It seems to be waving it's hands around in the fog. Sometimes, the
fog suddenly lights up as if there is lightning in there, just like
a storm cloud.$d$),
  (160, 43, ARRAY['creature']::text[], $d$It seems to be waving it's hands around in the fog. Sometimes, the
fog suddenly lights up as if there is lightning in there, just like
a storm cloud.$d$),
  (160, 50, ARRAY['crest', 'emblem']::text[], $d$A faded crest with an eagle rampart is painted onto the floor. You can see
that the colours were once very bright but the passage of time had reduced
their splendour.$d$),
  (160, 50, ARRAY['plaque', 'sign']::text[], $d$The sign reads :

                TRAINING ROOM
     PLEASE COLLECT YOUR WEAPONS AT THE
                   ARMOURY$d$),
  (160, 51, ARRAY['embers', 'fireplace', 'fire', 'ember']::text[], $d$   It looks like someone had just roasted some meat over the fire here. It
smells rather pleasant, though, something about it unsettles you. Your eyes
drifts off to look at the spit, and you recoil with horror. There are traces
of clothing stuck onto it!$d$),
  (160, 54, ARRAY['cupboard']::text[], $d$As you touch the cupboard, it swings out a little. You notice that there
is a passageway behind the cupboard! This must lead somewhere.$d$),
  (160, 66, ARRAY['skeleton', 'bones', 'bone']::text[], $d$   The skeleton appears to belong to a human knight, as it is still in its age
tarnished armour. A broken longsword is gripped in its right hand, and in its
left, the battered remains of a heater shield. All around it are the hacked
off limbs and bodies of his opponent. It seems like the conquerers of this
castle saw fit not the disturb the body of this valiant warrior.$d$),
  (160, 66, ARRAY['armour']::text[], $d$   The armour is of a very ancient design, at least 600 years old. There is a
nasty gash in the breastplate, as if a sharp object had penetrated it. Other
than that, there are no other signs of damage on it.$d$),
  (160, 66, ARRAY['longsword', 'sword']::text[], $d$   Inscribed into the hilt of the blade are the words,

          'The rock of Dagmarck'$d$),
  (160, 66, ARRAY['heater', 'shield']::text[], $d$   The shield bears a proud coat of arms, one which seems vaguely familiar to
you.$d$),
  (160, 69, ARRAY['skeleton']::text[], $d$This looks the like skeleton of a man. He seems to have been killed in his
sleep. The rotten remains of his clothing still hangs on the bones. It looks
like velvet or silk. You realise that this was the late Lord of this castle.$d$),
  (162, 71, ARRAY['walls', 'wall']::text[], $d$This wall seems to be covered with more hyroglyphics than the others. It
shows Neris and Imanhotep in the royal hall with a group of sorcerers.
The head sorcerer speaks something aloud which seems to cause Neris
great pleasure....$d$),
  (162, 78, ARRAY['wall', 'walls']::text[], $d$On the walls around the undead you notice pictograms of
their life and times.  The great advancements made by
Imanhotep in the building of cities and monuments is
stunning. The common people are depicted as being lower
life forms not worthy of life itself.  Imanhotep
was a cruel ruler and had no concern for his people.
Neris is then introduced into the story and she changes
Imanhoteps treatment of his people.  The next series of
hyroglyphs are unreadable but it seems Neris possessed a
very powerful magical ruby scarab on a short staff.
The scarab was a gift from a group of sorcerers who had
heard of her kindness. The last set of writing shows a
grand hall with the King and Queen, the group of sorcerers
making the presentation, many members of the royal court
line the walls watching in approval, there is also a
royal scribe writing into a large book.$d$),
  (162, 78, ARRAY['west']::text[], $d$There seems to be a hole in the wall that you can just
squeeze into.$d$),
  (163, 16, ARRAY['tree', 'oak', 'oak-tree']::text[], $d$The tree looks almost as old as the woods itself. You feel rather
comfortable under its shade. A cool breeze seems to keep blowing here.$d$),
  (163, 39, ARRAY['tree', 'oak', 'oak-tree']::text[], $d$The tree looks almost as old as the woods itself. You feel rather
comfortable under its shade. A cool breeze seems to keep blowing here.$d$),
  (163, 52, ARRAY['tree', 'oak', 'oak-tree']::text[], $d$The tree looks almost as old as the woods itself. You feel rather
comfortable under its shade. A cool breeze seems to keep blowing here.$d$),
  (163, 55, ARRAY['circle', 'stone']::text[], $d$The stone blocks are at least 35 feet high and made of granite. They are
well spaced to form a perfect circle around the hill.$d$),
  (163, 55, ARRAY['altar']::text[], $d$The altar is a perfectly square granite block. There seems to be some
scorch marks on it. It also feels cold to the touch.$d$),
  (163, 73, ARRAY['footprint', 'footprints']::text[], $d$All manner of prints are here: sandals, boots, and horses.  Scattered among
these are some prints that appear to be from wolves, and also, some large
clawed prints of strange origin.  Oddly, some of the hoofprints are not shod,
though they keep to the road like all the rest.$d$),
  (164, 6, ARRAY['throne']::text[], $d$It is made of stuffed human parts and bones. You feel sick to your stomach
but you must admit, it is rather majestic in a macabre way.$d$),
  (169, 1, ARRAY['cobwebs']::text[], $d$The cobwebs looks like it has been here for ages, and its inhabitants seem
to have become quite robust. Stuck on one of the cobwebs is the carcass of
a doormouse. It seems to have fallen prey to a spider.$d$),
  (169, 3, ARRAY['bookshelves', 'book', 'shelves']::text[], $d$These books are badly damaged. They crumble even as you touch them.
Some of the bookshelves are also broken, as if someone came around
and started smashing up the place.$d$),
  (169, 4, ARRAY['bookshelves', 'book', 'shelves']::text[], $d$These books are badly damaged. They crumble even as you touch them.
Some of the bookshelves are also broken, as if someone came around
and started smashing up the place.$d$),
  (169, 8, ARRAY['window']::text[], $d$The garden is in rather bad shape. Weeds are growing everywhere.
It seems like nobody has lived here for a very long time.$d$),
  (169, 12, ARRAY['hoops', 'hoop', 'croquet']::text[], $d$The hoops are rusted, metal rings stuck in the ground. Ladies used to have
parties around these things. It looks like they won't be seeing any more
parties.$d$),
  (169, 13, ARRAY['skeleton', 'fish']::text[], $d$The bones are extremely weather beaten and yellowed. You find it strange
however that the bones can be seen so obviously from the top of the well.
Then you realise, the bones seem to be glowing a little.$d$),
  (169, 20, ARRAY['lake', 'artificial']::text[], $d$The lake was probably commissioned by one of the owners of the house who
probably wanted the view. Years of disuse has clogged up the water inlet
and the lake has already dried up.$d$),
  (169, 23, ARRAY['bed']::text[], $d$The springs are all rusty and jutting out of the mattress, and the quilts
are all moth eaten. This would not make a good place to sleep in now,
although it may have once been very comfortable.$d$),
  (169, 24, ARRAY['bed']::text[], $d$The springs are all rusty and jutting out of the mattress, and the quilts
are all moth eaten. This would not make a good place to sleep in now,
although it may have once been very comfortable.$d$),
  (169, 25, ARRAY['bed']::text[], $d$The springs are all rusty and jutting out of the mattress, and the quilts
are all moth eaten. This would not make a good place to sleep in now,
although it may have once been very comfortable.$d$),
  (169, 32, ARRAY['small', 'scraps', 'tattered', 'paper']::text[], $d$Someone has just shredded some papers here into small pieces.  You attempt to
piece the scraps back together to create the original message.$d$),
  (169, 32, ARRAY['original', 'message']::text[], $d$   It reads: Fair Maiden, We have tried all that our science and medicine can
offer, but alas I regret to inform you that your fiance has perished.  We would
like to convey our most sincere and heartfelt apologies.  With Sympathy, The
court doctors and scientist of the King.$d$),
  (169, 44, ARRAY['bones', 'bone', 'yard']::text[], $d$Upon inspection, you discover that the bones shows signs of being gnawed on.
Whatever ate them seems to have quite large and sharp teeth.$d$),
  (169, 45, ARRAY['bones', 'bone', 'yard']::text[], $d$Upon inspection, you discover that the bones shows signs of being gnawed on.
Whatever ate them seems to have quite large and sharp teeth.$d$),
  (169, 46, ARRAY['bones', 'bone', 'yard']::text[], $d$Upon inspection, you discover that the bones shows signs of being gnawed on.
Whatever ate them seems to have quite large and sharp teeth.$d$),
  (169, 47, ARRAY['bones', 'bone', 'yard']::text[], $d$Upon inspection, you discover that the bones shows signs of being gnawed on.
Whatever ate them seems to have quite large and sharp teeth.$d$),
  (169, 48, ARRAY['bones', 'bone', 'yard']::text[], $d$Upon inspection, you discover that the bones shows signs of being gnawed on.
Whatever ate them seems to have quite large and sharp teeth.$d$),
  (169, 49, ARRAY['bones', 'bone', 'yard']::text[], $d$Upon inspection, you discover that the bones shows signs of being gnawed on.
Whatever ate them seems to have quite large and sharp teeth.$d$),
  (169, 50, ARRAY['oval', 'mirror', 'oval-mirror']::text[], $d$   A beautiful mirror with fine hand carved wood is here.  It really needs to
be cleaned, it is covered with fingerprints.$d$),
  (172, 8, ARRAY['word', 'words', 'sign', 'glowing']::text[], $d$In red glowing letters, the sign reads :
        The sinister leads the way$d$),
  (172, 15, ARRAY['words', 'word', 'portal']::text[], $d$The words say:
       Enter and Begin.$d$),
  (172, 29, ARRAY['words', 'word', 'glowing']::text[], $d$Yellow words state:
       Right ways go astray$d$),
  (172, 38, ARRAY['words', 'word', 'glowing', 'silver']::text[], $d$The silver words read:
       Escape is denied to those who heed signs now.$d$),
  (172, 45, ARRAY['words', 'word', 'portal']::text[], $d$The words say:
       Advance at your own risk.$d$),
  (172, 50, ARRAY['words', 'word', 'portal']::text[], $d$The words say:
        Go forth and succeed$d$),
  (172, 54, ARRAY['words', 'word', 'glowing']::text[], $d$Glowing blue words enigmatically states:
        Beware how far you go, one step may be too much.$d$),
  (172, 56, ARRAY['words', 'word', 'portal']::text[], $d$The words say:
        Forward to your destiny$d$),
  (172, 59, ARRAY['words', 'word']::text[], $d$Small words say:
       To keep going west is a trap. I hope you have the sense to
look for words which aren't there.
                                                   Timun$d$),
  (172, 63, ARRAY['words', 'word']::text[], $d$Small words says:
       To keep going west is a trap. I hope you have the sense to
look for words which aren't there.
                                                   Timun$d$),
  (172, 67, ARRAY['words', 'word', 'portal']::text[], $d$The words say:
        Are you ready?$d$),
  (172, 68, ARRAY['words', 'word', 'glowing']::text[], $d$Orange words state:
        Look before you leap$d$),
  (172, 70, ARRAY['words', 'word', 'portal']::text[], $d$The words say:
        Go forward, for your goal is near.$d$),
  (172, 73, ARRAY['words', 'word', 'glowing']::text[], $d$This time, in blazing white letters, the words are:
        Only the guardian stands in your way.$d$),
  (172, 77, ARRAY['pentagram', 'floor']::text[], $d$As you study the pentagram, you realise that it possesses runes for a
transport ward.$d$),
  (173, 1, ARRAY['statues', 'statue']::text[], $d$   The statues are jet black in colour but they are strangely soft to the touch
and has a texture similar to flesh. Some sport an astonishing array of
appendages, and all look totally horrifying.$d$),
  (173, 10, ARRAY['walls', 'wall', 'red']::text[], $d$   As you place your hand on the wall, it feels rather sticky and wet. A
horrible wail fills the air as you remove your hand from the disgusting
surface.$d$),
  (173, 11, ARRAY['statues', 'statue']::text[], $d$   The statues are jet black in colour but they are strangely soft to the touch
and has a texture similar to flesh. Some sport an astonishing array of
appendages, and all look totally horrifying.$d$),
  (173, 17, ARRAY['statues', 'statue']::text[], $d$   The statues are jet black in colour but they are strangely soft to the touch
and has a texture similar to flesh. Some sport an astonishing array of
appendages, and all look totally horrifying.$d$),
  (173, 18, ARRAY['statues', 'statue']::text[], $d$   The statues are jet black in colour but they are strangely soft to the touch
and has a texture similar to flesh. Some sport an astonishing array of
appendages, and all look totally horrifying.$d$),
  (173, 24, ARRAY['statues', 'statue']::text[], $d$   The statues are jet black in colour but they are strangely soft to the touch
and has a texture similar to flesh. Some sport an astonishing array of
appendages, and all look totally horrifying.$d$),
  (173, 45, ARRAY['red', 'stone']::text[], $d$   You try to scratch the surface of the chamber, but in spite of your best
efforts, it is unmarked. Then you realise, this chamber is made of one large
piece of ruby.$d$),
  (173, 46, ARRAY['red', 'stone']::text[], $d$   You try to scratch the surface of the chamber, but in spite of your best
efforts, it is unmarked. Then you realise, this chamber is made of one large
piece of ruby.$d$),
  (173, 51, ARRAY['red', 'stone']::text[], $d$   You try to scratch the surface of the chamber, but in spite of your best
efforts, it is unmarked. Then you realise, this chamber is made of one large
piece of ruby.$d$),
  (173, 52, ARRAY['red', 'stone']::text[], $d$   You try to scratch the surface of the chamber, but in spite of your best
efforts, it is unmarked. Then you realise, this chamber is made of one large
piece of ruby.$d$),
  (178, 36, ARRAY['totem-pole', 'totem', 'pole']::text[], $d$   The totem-pole is a large pice of timber an armswidth in size and about 20
feet tall. At the top of the pole, the carved head of a cougar stares
proudly towards the east.$d$),
  (178, 69, ARRAY['paintings', 'painting', 'pictures']::text[], $d$   The pictures are very crudely done, with motives of various animals. The
cougar, bear and eagle are quite common among the myriad pictures. You realise
that some of them are painted in blood.$d$),
  (180, 20, ARRAY['gazebo']::text[], $d$The gazebo is a rather large, white open structure. There are whitewashed
benches in it. Planted around the gazebo are sweet smelling flowering plants.$d$),
  (180, 26, ARRAY['gazebo']::text[], $d$The gazebo is a rather large, white open structure. There are whitewashed
benches in it. Planted around the gazebo are sweet smelling flowering plants.$d$),
  (185, 8, ARRAY['altar']::text[], $d$A large marble edifice of the patron saint of this monastery is placed
at the centre of the altar. He has a kindly and wise face, and he holds
a large tome in his hand.$d$),
  (185, 13, ARRAY['fireplace', 'fire']::text[], $d$You can't resist the temptation to warm your hands on the fire.
It feels good as the warmth creeps up your hand.$d$),
  (185, 18, ARRAY['desk']::text[], $d$Arranged on the desk are stacks of sealed letters. It seems like this
abbey gets quite a lot of correspondence.$d$),
  (185, 19, ARRAY['words', 'word']::text[], $d$The words upon the arch reads:

                     Fiat Justitia, ruat coelum$d$),
  (185, 20, ARRAY['gruel', 'pot']::text[], $d$You dip your finger in the pot and get a taste. It tastes quite okay, but
you realise that it isn't something that would exactly tantalise the taste
buds.$d$),
  (185, 40, ARRAY['gears', 'gear']::text[], $d$The array of machinery and gears are beyond your ability to understand.
But you can see that it is quite efficient at grinding the grain.$d$),
  (185, 42, ARRAY['casks', 'cask']::text[], $d$Unfortunately, the casks are still empty. Looks like you can't get a free
drink.$d$),
  (185, 46, ARRAY['pond', 'fish']::text[], $d$As you peer into the pond, you can see fish of all shapes and sizes
swimming around. You try to catch one, but you are just not fast enough.$d$),
  (185, 57, ARRAY['statue']::text[], $d$This large statue is shaped after the founding monk of this library.  His
memory is served well, in the strong expression on his face.  His personal
inner strength shows through the hard stone which embodies him.$d$),
  (185, 66, ARRAY['cross', 'holy', 'holy-cross']::text[], $d$The cross is very large and highly decorated.  It seems to glow brightly,
casting warmth upon those who get captured in its light.  Before the cross is a
small mat.$d$),
  (185, 74, ARRAY['sign']::text[], $d$The sign stands here, pointing east and west towards quiet places to study,
north to the stacks, and south down a passageway leading to more stacks and
offices.$d$),
  (185, 89, ARRAY['leaves', 'leave']::text[], $d$There is a clustered pile of leaves pushed into the corner between the western
railing and the wall of the library.  They are constantly swirling about, moved
by the relentless weather that pesters this entire complex.$d$),
  (185, 94, ARRAY['window']::text[], $d$Through this window is a beautiful view of the surrounding lands.  There is
much to be seen and experianced beyond these walls.$d$),
  (187, 0, ARRAY['door']::text[], $d$The heavy wooden door is new looking and very sturdily made.
It's bordered with metal reinforcements and accoutrements.
There is a carving in the center of the door.$d$),
  (187, 0, ARRAY['carving']::text[], $d$The carving is a circle composed of five circles linked together.
In the center of the five circles is carved the guild icon.$d$),
  (187, 1, ARRAY['door']::text[], $d$The heavy wooden door is new looking and very sturdily made.
It's bordered with metal reinforcements and accoutrements.
There is a carving in the center of the door.$d$),
  (187, 1, ARRAY['carving']::text[], $d$The carving is a circle composed of five circles linked together.
In the center of the five circles is carved the guild icon.$d$),
  (187, 2, ARRAY['tapestry']::text[], $d$The tapestry depicts a scene of Paladins and Priests doing battle with a
demon lord.  Off to one side is a ranger fighting an ice dragon.$d$),
  (187, 2, ARRAY['table']::text[], $d$The table is very old, of oaken wood, with worn edges and many scratches.
It is carved in the center with the same design seen on the door.$d$),
  (188, 0, ARRAY['painting']::text[], $d$Framed in magnificent silver, the painting depicts a small grouping of
dark-cloaked people, In the center, a slender half-elf woman in pale blue robes
sits on a black chair, smirking slightly beneath tresses of silvery hair.  To
the right, a gnarly gnome dressed in black robes scowls at the painter, his
beady black eyes frowning impudently.  On the left, a dashing warrior in shiny
armor grins mischievously, resting his right arm casually on a black greatsword
on his belt.  On either side of the painting stand lithe, fairly nondescript
men in loose, navy garb.  They both smile disarmingly, belying their true
vocation.  There is a small inscription at the bottom of the frame.$d$),
  (188, 0, ARRAY['inscription', 'frame']::text[], $d$The inscription reads:<b>
            Dronar, Karde, Kendris, Zenitul, Arreeleo
                     The Clandestine Degree</>$d$),
  (188, 0, ARRAY['shadows', 'floor']::text[], $d$Clouds passing over the cathedral cause the shadows to periodically shift, but
at times of equilibrium, the shadows coalesce to the shape of a rearing fox.
$d$),
  (188, 1, ARRAY['walls', 'wall']::text[], $d$The wall encompasses the entire circular room, wide stone columns rising every
few armwidths from the floor to meet pointed arches leading up to the center of
the domed ceiling above.  Light lines of blue steel are inserted between
columns, tastefully adding to the walls' solid blocks of stone.  Atop each
column rests a small gargoyle, peering down upon the rotunda with piercing
stone eyes.$d$),
  (188, 1, ARRAY['stained-glass', 'window']::text[], $d$About four times a man's height, the window reaches high above in a somewhat
rounded arch.  Its colored glass is almost exclusively blue and gray, depicting
the image of a blue fox against a murky grayish background.  The fox is rearing
up on its hind legs, reaching up viciously towards an amethyst-hued raptor
flittering above it.  In the bird's mouth, a small golden olive leaf is clasped
tightly, hanging just out of the fox's reach.$d$),
  (188, 2, ARRAY['telescope', 'scope']::text[], $d$   Although the telescope is pointed at the opaque window before it, looking
through the viewfinder reveals a startlingly clear view of the Village of
Mielikki, as if one were looking down upon it.  It might even be possible to
observe individual rooms from this perspective.$d$),
  (188, 3, ARRAY['walls', 'shelves', 'books']::text[], $d$The shelves wrap around the room's walls, literally covered in books from all
eras of time.  Starting just to the east of the doors, the oldest books rest in
magical stasis, looking as though they might crumble under the slightest touch.
The books continue around the room ending just west of the doors, where the
newest books of the realm are collected.  A tall metal ladder is mounted on a
rail at the top of the shelves, able to slide completely around the room,
providing easy access to even the highest books.$d$),
  (188, 5, ARRAY['table']::text[], $d$The heavy oak table is circular, with a single, wide support beneath it.  In
the center of the table, the image of a rearing fox is etched lightly in the
wood.  Various papers and trinkets are strewn across the table, many bearing a
seal similar to the imprint on the table.  A small collection of indigo-colored
papers has silver writing on them.$d$),
  (237, 13, ARRAY['stone', 'fungus']::text[], $d$   The stone is cold and damp if felt, and the fungus grows well in the moist
environment.$d$),
  (237, 39, ARRAY['beacon', 'fire', 'fires', 'side']::text[], $d$   Leaping out of basins made of smoky quartz, the purple flames light up the
entrance to House Trenkessda quite well.$d$),
  (237, 75, ARRAY['paper', 'papers', 'text']::text[], $d$   Written in a blocky, alien script, these papers are neatly scattered, as if
someone wanted to give the appearence of a mess but still wanted to be able to
find information quickly.$d$),
  (237, 95, ARRAY['carving', 'carvings']::text[], $d$A quick glance at the carvings shows a pack of drow riding a gargantuan spider
into a forest, leaving complete destruction in their wake.  Just below, in a
larger section, the drow and spiders can be seen standing together in a circle
while a half-formed demon rises out of the smoke.  All of the carvings are
extremely well polished.$d$),
  (238, 27, ARRAY['dragon', 'image', 'abstract', 'curves', 'lines', 'arcane', 'symbol', 'symbols']::text[], $d$   The signs, though they appear random, decorate the rather eye-catching form
of a dragon on the stairs.  Carved directly into the blue stone, the dragon's
true color is unknown.$d$),
  (238, 28, ARRAY['runes', 'rune']::text[], $d$   Runes are inscribed on the stairway here.  Upon closer inspection, they are
revealed to be Dwarven runes, which read: "To the great lord Dargentan in
return for a service to the Kingdom" with the year "423" noted below the
inscription.  However, there is no record of which Kingdom is referred to,
which Dwarves worked on the building, or what the service was.$d$),
  (238, 28, ARRAY['pattern', 'patterns', 'figure', 'figures']::text[], $d$   A variety of creatures can be seen on the walls here, though many are simply
abstract representations.  The arcane symbols are those representing stability,
prosperity, and security.$d$),
  (238, 29, ARRAY['flame']::text[], $d$   A lonely flame burns here, all in silver.  It is the symbol of the holy
favor of the god Pergus.$d$),
  (238, 29, ARRAY['arcane', 'symbol', 'symbols']::text[], $d$   Symbols of warding against evil and general security are subtly worked into
the decorations for this room.  Some unfamiliar patterns may be arcane in
nature, but it is possible they are simply decorative.$d$),
  (238, 29, ARRAY['hexagon', 'hexagonal', 'unfamiliar', 'abstract', 'abstracts']::text[], $d$   Points and curves flow into six-sided patterns, every one unique.  They are
scattered randomly around the room, their silver sheen reflecting pleasantly in
the light.  Suddently it dawns on you what they are supposed to represent:
Snowflakes!$d$),
  (238, 30, ARRAY['beast', 'beasts', 'building', 'buildings', 'shape', 'shapes']::text[], $d$   Though the symbols are more abstract than realistic, someone with an active
imagination could pick out griffins, angels, a phoenix, an elemental and other
creatures of the sky in the engravings of silver on the blue stone walls.
There is one that definately resembles a building with arching windows and tall
spires - perhaps it is a temple to some god or goddess.$d$),
  (238, 30, ARRAY['temple']::text[], $d$   On the leftmost spire of the temple is a symbol: an inverted triangle with
spheres on all three sides.  In tiny Elven runes it says, "Kourrya 2006".$d$),
  (238, 31, ARRAY['bird', 'arch']::text[], $d$   The bird carved into the arch here resembles a phoenix, but where a phoenix
is a creature of fire, this is a creature of ice.  Tiny silver snowflakes trail
from its in-flight pose, and its feathers resemble ice crystals.$d$),
  (238, 32, ARRAY['pattern', 'patterns', 'gems', 'ceiling']::text[], $d$   The smoky quartz is inset into many patterns both arcane and mundane.  On
the ceiling there is a mural of sorts, with a young girl and an older,
powerful-looking woman.  The older woman's eyes are inset with crystals of
smoky quartz.$d$),
  (238, 32, ARRAY['pillar', 'northeast']::text[], $d$   A massive pillar of dark blue stone supports the ceiling.  Inscribed on it
are the arcane runes for stability and flight.$d$),
  (238, 33, ARRAY['pillar', 'pillars', 'northeast', 'northwest']::text[], $d$   Pillars of dark blue stone stand to the northeast and northwest here,
inscribed with arcane runes of safety and flight.$d$),
  (238, 33, ARRAY['fresco', 'frescoes', 'ceiling']::text[], $d$   The ceiling frescoes here show a young woman gesturing rudely to a man in a
black cloak.  The man's eyes are represented by small smoky quartz gems.  The
scene is richly colored.$d$),
  (238, 34, ARRAY['ceiling']::text[], $d$   The ceiling frescoes here show a young woman with dark hair peering into a
cave, while an older-looking woman stands far away and laughs.  The older
woman's eyes are set with smoky quartz gems.$d$),
  (238, 34, ARRAY['pillar', 'pillars', 'northwest', 'southeast']::text[], $d$   Large pillars of blue stone stand to the northwest and southeast, supporting
the ceiling.  Inscribed with runes for safety and flight, they are surely
essential to the structural integrity of the building.$d$),
  (238, 35, ARRAY['pentagram', 'inscribed']::text[], $d$   The circle around this pentagram is not a solid line at all, but letters in
tiny, flowing script.  It reads: "The cleric was known to like violet".$d$),
  (238, 35, ARRAY['triangle', 'circle', 'circles', 'shape', 'shapes']::text[], $d$   A few triangles and circles are scattered around on the walls and ceiling,
some accented by smoky quartz and some looking like they could form pictures.
There are also spirals and squares, but not as many as there are triangles.
$d$),
  (238, 35, ARRAY['runes', 'rune', 'line', 'lines']::text[], $d$   A few runes and lines are scattered at random here.  They don't seem to
indicate anything in particular.$d$),
  (238, 36, ARRAY['fresco', 'frescoes', 'ceiling', 'walls']::text[], $d$   The frescoes on the ceiling here show a grim scene of a young woman
imprisoned in a cave with bars accented by smoky quartz.  Her expression is one
of despair.$d$),
  (238, 36, ARRAY['pillar', 'pillars', 'northeast', 'southeast']::text[], $d$   Pillars of large blue stone stand to the northeast and southeast, inscribed
with the magical runes of safety and flight.  Beyond them, the hall stretches
out even farther.$d$),
  (238, 37, ARRAY['pillar', 'pillars', 'northwest', 'southwest']::text[], $d$   To the northwest and southwest, large pillars of blue stone support the
gently arched ceiling.  They have the arcane runes for safety and flight
inscribed on them, probably keeping the building afloat.$d$),
  (238, 37, ARRAY['ceiling', 'scene', 'scenes']::text[], $d$   The frescoes on the ceiling show a man with black hair and a long cloak
travelling through mountainous terrain.  His eyes are represented by tiny,
radiant smoky quartz gems.$d$),
  (238, 38, ARRAY['inscription']::text[], $d$   The inscription reads, "The Death of Gods searches for his beloved Raven".
$d$),
  (238, 38, ARRAY['painting', 'paintings', 'ceiling']::text[], $d$   Though slightly encrusted with ice, the paintings that decorate the ceiling
are nonetheless beautiful and bright.  Their subject, however, is not.  A man
with black hair and a long cloak, his eyes represented by smoky quartz,
searches for something through many different terrains with a look of despair
on his face.  There is an inscription at the eastern end of the painting.$d$),
  (238, 39, ARRAY['pillar', 'northwest']::text[], $d$   A pillar stands to the northwest, made of the same blue stone as the rest of
the structure.  It is covered with arcane runes indicating flight and safety.
$d$),
  (238, 39, ARRAY['inscribed', 'pentagram', 'circle']::text[], $d$   The circle is not a line, but rather a thin, flowing script.  It reads: "The
one from Ogakh stood on one end".$d$),
  (238, 39, ARRAY['triangle', 'humanoid', 'shaped', 'line', 'lines', 'wavy', 'abstract']::text[], $d$   A vivid imagination is all that is needed to turn these seemingly random
figures into a tale of betrayal and hope...  Or maybe they are just shapes.
$d$),
  (238, 39, ARRAY['figure', 'figures']::text[], $d$   Humans and tiny, dragonlike creatures play in this section of the walls.
One of the little dragonlike figures is breathing a fiery stream of rose
quartz.$d$),
  (238, 40, ARRAY['pillar', 'northeast']::text[], $d$   A pillar of dark blue stone rises to the northeast, supporting the wide
hall.  Inscribed on it are runes for flight and safety.$d$),
  (238, 40, ARRAY['fresco', 'frescoes', 'ceiling']::text[], $d$   Brilliant greens and blues dominate this picture, which is of two figures
wearing armor riding over a hill.  An unconscious figure is on the other side
of the hill waiting for them, and a wall of shadow roils in the background.
$d$),
  (238, 41, ARRAY['celestial', 'bodies', 'wavy']::text[], $d$   Suns, stars and moons decorate the southern and eastern walls, representing
many different planes.  Maybe that one is Ethilien?$d$),
  (238, 41, ARRAY['testing']::text[], $d$   The circle around this pentagram is not a line, but rather tiny script.  It
reads: "The one who wore purple stood next to the half-elf".$d$),
  (238, 41, ARRAY['indent', 'chipped', 'southern', 'wall', 'broken']::text[], $d$   The wall's smoothly polished surface is roughly broken here, interrupting a
nice carving of a pentagram.  Perhaps if the missing piece of wall could be
found, the carving would made whole again.$d$),
  (238, 42, ARRAY['mosaic', 'stones', 'picture', 'ceiling']::text[], $d$   The ceiling here is inlaid with a colorful mosaic depicting a small fortress
near some dark, ominous-lookig mountains.  Two figures on horseback aproach the
castle with a third figure, either dead or unconscious, slung on the back of
one of the horses.$d$),
  (238, 42, ARRAY['stone', 'rose', 'quartz']::text[], $d$   The pieces of the mosaic, called tesserae, interlock snugly with each other
to form a beautiful picture.  Some tiles are made of the rose quartz, and
others have tiny, faceted rose quartz gems decorating them.$d$),
  (238, 43, ARRAY['divine', 'solar', 'four', 'pointed', 'four-pointed', 'symbol']::text[], $d$   The symbol here is a beaten copper sun with four long rays pointing in the
cardinal directions.  In its center is a smooth, pink rose quartz.$d$),
  (238, 43, ARRAY['pentagram', 'inscribed', 'circle']::text[], $d$   Here is a five-pointed star inscribed in a circle, but the circle is not a
line.  Rather, it is tiny, flowing script which reads: "The dwarf was laughed
at, for his favorite enemies were giant bugs".$d$),
  (238, 44, ARRAY['colors', 'ceiling', 'mosaic']::text[], $d$   This mosaic shows a brown-haired man in a purple shirt sitting at a desk
covered in papers and trophies.  He writes a document with a quill pen, but
smiles as he does so.  The walls of his office are lavishly decorated, showing
his wealth.$d$),
  (238, 44, ARRAY['decorated', 'wall', 'west']::text[], $d$   Rose quartz stones accent the carvings and grooves on the western wall, but
they seem random rather than solid representations of anything in particular.
The carvings are, however, quite pleasant to look at.$d$),
  (238, 45, ARRAY['decoration', 'decorations', 'ceiling']::text[], $d$   The ceiling here is decorated with a colorful mosaic, though it is slightly
icy due to the constant exposure to the weather.  The mosaic shows a
brown-haired man in a purple tunic walking through a colorful marketplace,
smiling.$d$),
  (238, 45, ARRAY['cloud', 'clouds', 'mountain', 'mountainous']::text[], $d$   To the south, clouds billow intermittently, forming shapes of mountains and
valleys higher and deeper than the ones land-dwelling creatures are probably
comfortable with.$d$),
  (238, 46, ARRAY['ceiling', 'mosaic', 'colorful', 'ice']::text[], $d$   The mosaic here shows a brown-haired man pleading with a man in a general's
uniform.  It is unclear what he is pleading for, but he looks quite urgent.
The general looks thoughtful.  The entire scene is glazed over with a thin
layer of ice from the constant winds.$d$),
  (238, 46, ARRAY['south', 'platform', 'cloud', 'clouds']::text[], $d$   The clouds are on an even level with you for the most part, though some are
actually below you.  You must be very high up in the sky.$d$),
  (238, 47, ARRAY['circle', 'inscribed', 'pentagram']::text[], $d$   This pentagram is inscribed inside a circle, but the circle is not a solid
line.  Instead, it is a tiny flowing script which reads: "The human wore purple
and stood to the right of the one who fought dragons".$d$),
  (238, 47, ARRAY['symbol', 'arcane', 'oak', 'triangle']::text[], $d$   The oak tree, ever sacred to druids, is a symbol of protection and
stability.  Triangles in perfect equilibrium are for balance.  Other symbols
also decorate the walls here, but those two seem very prominent.$d$),
  (238, 48, ARRAY['pillar', 'northwest']::text[], $d$   A large pillar of blue stone is here, supporting the high ceiling.
Inscribed on it are the arcane runes for safety and flight.$d$),
  (238, 48, ARRAY['ceiling', 'painting', 'paintings']::text[], $d$   The ceiling painting here shows a rather grim scene - a fortress near some
mountains being attacked by dark shadows.  Still figures line the ground, but
in the back hills there is a column of fleeing figures who look like they have
escaped the worst.$d$),
  (238, 49, ARRAY['pillar', 'pillars', 'northwest', 'northeast']::text[], $d$   Large columns of blue stone rise to the northeast and northwest, inscribed
with the arcane runes for safety and flight.  They provide both physical
support for the hall and, no doubt, magical support to keep it flying.$d$),
  (238, 49, ARRAY['ceiling', 'painting', 'fresco', 'frescoes']::text[], $d$   The colorful frescoes in this room show a man in general's garb leading a
band of refugees through a forest.  Some of the refugees are injured, and a few
of them are looking around themselves nervously.  The general has an expression
of determination on his face.$d$),
  (238, 50, ARRAY['ceiling', 'fresco', 'frescoes']::text[], $d$   Brilliantly colored figures are painted on the ceiling here, showing a
picture of refugees exiting a tunnel into a verdant forest.  The refugees are
led by a man in a general's uniform and a brown-haired man in a purple tunic,
both of whom have eyes of aventurine crystal.$d$),
  (238, 50, ARRAY['northeast', 'pillar']::text[], $d$   A massive pillar stands to the northeast, supporting the hallway.  It is
carved with many arcane runes of safety and flight, adding to the structural
and magical integrity of the building.$d$),
  (238, 51, ARRAY['pillar', 'pillars', 'northwest', 'southeast']::text[], $d$   Blue pillars rise majestically to the northwest and southeast, engraved with
arcane runes that symbolize flight and safety.$d$),
  (238, 51, ARRAY['ceiling', 'fresco']::text[], $d$   This bright painting shows an elven man and his family in a forest village,
surrounded by brilliant greens.  The man seems blissfully happy, and his son
looks excited and clutches a four-pointed sun symbol.$d$),
  (238, 52, ARRAY['pillar', 'northeast']::text[], $d$   A massive pillar of blue stone is here, solidly supporting the ceiling of
the great hall.  Carved into it are arcane symbols of flight and protection.
$d$),
  (238, 52, ARRAY['hexagon', 'chain', 'circles', 'symbols', 'symbol']::text[], $d$   The symbols are artistically arranged here into an arrangement that pleases
the eye.  The chain of circles in particular has a wavy, almost mesmerizing
appearance.$d$),
  (238, 52, ARRAY['inscribed', 'pentagram']::text[], $d$   The pentagram is inscribed in a circle of flowing text, which reads: "The
human stood next to his friend from Mielikki".$d$),
  (238, 53, ARRAY['symbol', 'symbols', 'magical']::text[], $d$   The symbols all glow with a faint white light, warm to the touch although
the constant wind and cold has left a thin sheet of ice over everything else.
$d$),
  (238, 53, ARRAY['spiral', 'spirals', 'oak', 'tree', 'deity', 'holy', 'rune', 'runes']::text[], $d$   There must be at least thirty different symbols here, all unique.  Next to
some of them, in the small indent, there are various precious gems: rubies,
sapphires, emeralds, and even diamonds.$d$),
  (238, 53, ARRAY['pentagram', 'inscribed']::text[], $d$   Next to an empty indent there is a pentagram inscribed in a circle.  The
circle is not, however, a solid line.  It is a line of script, which reads:
"The sorcerer valiantly fought undead".$d$),
  (238, 54, ARRAY['pillar', 'pillars', 'northeast', 'southeast']::text[], $d$   Massive pillars of blue stone stand to the northeast and southeast, engraved
with the magical runes for flight and safety.  Perhaps they conduct the magic
that keeps the structure afloat?$d$),
  (238, 54, ARRAY['ceiling', 'painting', 'pintings']::text[], $d$   Reds and blacks color this painting, which seems almost out of place in the
blue peace of the hall.  It shows an elf held captive by demons with fiery
manes, all with expressions of anger on their faces.  The elf's eyes are
represented with shards of blue aventurine.$d$),
  (238, 55, ARRAY['pillar', 'pillars', 'northwest', 'southwest']::text[], $d$   Huge pillars support the ceiling to the northwest and southwest, engraved
with arcane symbols of flight and protection.  They are very similar to the
other pillars scattered around this building.$d$),
  (238, 55, ARRAY['intricate', 'painting', 'ceiling']::text[], $d$   The ceiling shows a dark scene - a horde of demons covered in fire attacking
a small forest village.  Most of the population is lying on the ground, dead or
unconscious, but some are being held captive by the demons.  The demons are
lead by a hulking figure encased in flames.$d$),
  (238, 56, ARRAY['pillar', 'southeast']::text[], $d$   A giant blue pillar rises to the southeast, covered in runes and stones.
Though the stones are the same chrysoprase that cover the rest of the hall, the
runes are quite magical, representing flight and safety.$d$),
  (238, 56, ARRAY['painting', 'paintings', 'ceiling', 'decor']::text[], $d$   The painting on the ceiling is quite ornate, showing a destroyed
hellish-looking fortress and a retreating army of brilliant, white figures.
Amid the wreckage stands a scarred and broken elf, looking confused and alone.
The elf's eyes are tiny gems.$d$),
  (238, 57, ARRAY['pillar', 'southwest']::text[], $d$   A blue pillar lies to the southwest, decorated with many runes.  Perhaps
"decorated" is not the right word - as they are arcane runes symbolizing flight
and safety, they are probably functional rather than just for show.$d$),
  (238, 57, ARRAY['magical', 'arcane', 'symbol', 'symbols', 'sign', 'signs', 'elemental']::text[], $d$   These magical signs are interwoven with chrysoprase, giving them a beauty
unrelated to their power.  Some on the east wall are made of silver rather than
just engraved in the stone.$d$),
  (238, 58, ARRAY['ceiling', 'painting', 'arch']::text[], $d$   These paintings show a beautiful landscape of forests and mountains with a
lost-looking, badly scarred elf with chrysoprase eyes stumbling through the
beauty.$d$),
  (238, 58, ARRAY['walls', 'wall', 'north', 'west']::text[], $d$   Abstract engravings are studded with green chrysoprase gems, though their
cold is a good indicator that this is one of the outside walls of the building.
$d$),
  (238, 59, ARRAY['bark', 'totem', 'ash', 'crown', 'symbol', 'symbols']::text[], $d$   A bark totem of the goddess Mielikki is carved into the wall here, near a
crown of ashes.  Unusual symbols indeed.$d$),
  (238, 59, ARRAY['circle', 'inscribed', 'pentagram']::text[], $d$   A circle of flowing text surrounds a pentagram here.  The text reads: "The
mercenary stood to the left of his friend from Anduin".$d$),
  (238, 60, ARRAY['ceiling', 'tile', 'tiled', 'mosaic']::text[], $d$   Tesserae of many colors, some probably made from precious gemstones, show
the story of an injured elf taking refuge in a mountain city that looks
suspiciously like Anduin before the Riftwars.$d$),
  (238, 60, ARRAY['corner', 'southeast']::text[], $d$   Green and silver form themselves into the shape of a giant dragon flying
over the trees.  Silver seems like an unusual color for a dragon, but then
maybe the artist didn't have any dragon-shaped pieces of chrysoberyl.$d$),
  (238, 61, ARRAY['ceiling', 'mosaic', 'bright']::text[], $d$   The mosaic shows a handsome but cruel-looking elf standing outside a jail
cell, where a brown-haired man clad in a ruined violet tunic is kept prisoner.
$d$),
  (238, 61, ARRAY['wall', 'walls']::text[], $d$   The green chrysoprase is set into the blue stone of the walls very
skillfully, and many of the carvings have a Dwarven touch.$d$),
  (238, 62, ARRAY['world', 'heights', 'below', 'down', 'north']::text[], $d$   To the north lies the world.  Water gleams, clouds shadow, and trees grow
wherever the eyes turn.  It is a veritable living tapestry, though you are too
high up to see the forms of living creatures.  It is quite a mesmerizing view.
$d$),
  (238, 62, ARRAY['mosaic', 'ceiling']::text[], $d$   Brilliant tiles show the image of a dirty-looking girl in a barbarian
village.  Though she is clad only in animal skins, she is grinning brightly and
her hair has the glint of silver.  Her eyes are tiny chrysoprase stones,
seeming very green.  Barely noticeable on her forehead is the symbol of two
concentric circles.$d$),
  (238, 63, ARRAY['water', 'body', 'far']::text[], $d$   The slight sparkle of a body of water far to the north is probably the Blue
Fog Sea.  However, from here is color is unclear.$d$),
  (238, 63, ARRAY['cloud', 'clouds']::text[], $d$   The clouds below you are definately magical in nature, behaving nothing at
all like normal clouds.  The normal clouds, on the other hand, are visible for
many miles and have their own beauty.  What god makes them?  What god sweeps
them into such formations, each so different and ever-changing that one can
stare at it and see anything?$d$),
  (238, 63, ARRAY['ceiling', 'mosaic']::text[], $d$   The ceiling mosaic is covered with a thin layer of ice due to the constant
elemental exposure, but its subject remains clear.  A young, silver-haired
woman looks in astonishment at a priestess and an aging druid in a rustic
forest village.  The young woman is dressed plainly, like the others in the
village, but the two heroes greeting her are richly attired.  A few of their
ornaments are studded with smoky quartz to add emphasis to their wealth.$d$),
  (238, 64, ARRAY['circle', 'pentagram', 'inscribed']::text[], $d$   The pentagram is inscribed not with a line, but with flowing text which
reads: "The gnome stood in the middle, surrounded by the others".$d$),
  (238, 64, ARRAY['magical', 'symbols', 'runes', 'angelic', 'being', 'angel', 'triangle']::text[], $d$   Some seem merely decorative while others shimmer with contained power.
Though it is unusual to use smoky quartz in runic writing, the effect is
pleasing to the eye.  The other symbols are etched into the stone.$d$),
  (238, 65, ARRAY['painting', 'ceiling', 'design', 'designs']::text[], $d$   This painting shows the figure of a woman with silver hair diligently
studying texts written in various scripts.  Her eyes are represented by tiny
studs of smoky quartz.$d$),
  (238, 65, ARRAY['pillar', 'southeast']::text[], $d$   A large pillar of blue stone stands here inscribed with the magical runes
for fight and safety.  It is probably necessary for support of the wide hall.
$d$),
  (238, 66, ARRAY['hero', 'heroes', 'northern', 'wall', 'ceiling', 'figure', 'figures']::text[], $d$   The paintings in this room depict two heroes, a silver-haired woman wearing
the garb of a ranger and a dark-haired man in a druid's robe.  They are holding
hands and smiling.$d$),
  (238, 66, ARRAY['pillar', 'pillars', 'southeast', 'southwest']::text[], $d$   Large blue pillars stand to the southeast and southwest, made of the same
stone that the rest of the structure uses.  Both are inscribed with magical
runes of flight and safety.$d$),
  (238, 67, ARRAY['shapes', 'shape', 'rectangle', 'spiral', 'clover']::text[], $d$   If the shapes have a pattern, it is not readily obvious.  The quartz seems
to be scattered at random, aesthetically pleasing intervals.$d$),
  (238, 67, ARRAY['circle', 'pentagram', 'inscribed']::text[], $d$   The circle in which this pentagram is not a line, but small, flowing script.
It reads, "The rogue learned to like indigo in his hometown of Anduin".$d$),
  (238, 67, ARRAY['pillar', 'southwest']::text[], $d$   A large pillar of blue stone stands to the southwest, supporting the hall.
It is inscribed with the magical runes for safety and flight.$d$),
  (238, 68, ARRAY['pillar', 'pillars', 'northeast', 'northwest']::text[], $d$   Solid blue pillars rise to the southeast and southwest, providing the
structural integrity necessary to support a hall of these proportions.  They
are also inscribed with magical runes for safety and flight.$d$),
  (238, 68, ARRAY['ceiling', 'painting', 'paintings']::text[], $d$   The ceiling is painted with a beautiful portrait of a sad child, His pointed
ears show that he is either elven or half-elven, and, while other children play
together in the background, he stands alone.$d$),
  (238, 69, ARRAY['pillar', 'southwest']::text[], $d$   A giant pillar of blue stone stands to the south, bearing the weight of the
ceiling.  Inscribed on it are arcane runes of flight and safety.$d$),
  (238, 69, ARRAY['perfect', 'triangle', 'burning', 'heart', 'symbol', 'symbols']::text[], $d$   These symbols, some accented by gemstones, shimmer slightly in the light.
The burning heart represents passion and the oak tree protection, though
whether they are functional or merely decorative is unknown.$d$),
  (238, 69, ARRAY['pentagram', 'inscribed']::text[], $d$   It is a pentagram inscribed in a circle, though upon second glance the
circle is not a solid line.  Rather, it is a flowing script, which reads: "He
who fought orcs was always clad in magenta".$d$),
  (238, 70, ARRAY['carved', 'formed', 'fantastic', 'shapes']::text[], $d$   Rather than simply being spires, some of the crystals that make up the
chamber are shaped like jagged bolts of lightning, talons of a monstrous bird,
air elementals and clouds.$d$),
  (238, 71, ARRAY['spire', 'spires']::text[], $d$   Quartz crystals usually have six-pointed spires, and diamonds occur
naturally in cubes or octahedrons, but these crystals come in all shapes.
They were probably formed artificially.$d$),
  (238, 72, ARRAY['pattern', 'patterns', 'carvings', 'carving']::text[], $d$   If you focus your eyes one way, you can see a giant bird, but look again and
the image is lost.  Or maybe it wasn't a bird, but a beast?  Looking too hard
could give one a headache.$d$),
  (238, 73, ARRAY['stair', 'stairs', 'stairway']::text[], $d$   Very solid-looking, the stairway is made of the same blue stone that the
rest of the castle seems to be constructed of.  Tiny number runes are on each
stair, "1" at the bottom, "2" next, and so on.  Apparently there are 43 stairs
total.$d$),
  (238, 74, ARRAY['ceiling', 'painting']::text[], $d$   The painting on the ceiling shows a happy, silver-haired woman holding hands
with a druid and being chased by two children.  The kids look to be around
seven or ten years old, one with silver hair and one with golden hair.$d$),
  (238, 75, ARRAY['malachite', 'green', 'gem']::text[], $d$   Malachite is a striped green stone that is usually considered too soft to
work with, but here it has been added to the ceiling painting to accent parts
of the clothing, plants, and other green objects.$d$),
  (238, 75, ARRAY['ceiling', 'painting']::text[], $d$   The painting shows an angry-looking druid yelling at a hooded figure who
holds a tiny, purple-haired baby.  A silver-haired woman clad in green looks
exhausted and sad, laying in a bed - she probably just gave birth.$d$),
  (238, 76, ARRAY['inscribed', 'pentagram']::text[], $d$   Here in the corner is a pentagram inscribed in a circle of flowing text.
The text reads: "The one who hailed from Nordus stood to the left of the one
clad in violet".$d$),
  (238, 76, ARRAY['oak', 'tree', 'flame', 'symbols']::text[], $d$   The oak tree, a potent symbol of nature, is skillfully embedded with
malachite stones as leaves, making it look vibrant.  The flame is small but it
is beautiful, calling to mind the warmth and life-giving properties of fire
rather than the destructive, harmful ways it has often been used.$d$),
  (238, 77, ARRAY['cloudscape', 'cloudscapes']::text[], $d$   Many kinds of clouds are visible in the sky, some wispy and higher up and
some puffy, about on a level with you.  There are also some clouds that form a
wall you can't see through down closer to the ground, making it impossible to
make out some of the land's features in some areas.  Other places are clear,
though, and allow blurry shapes to be seen.  Details are not visible from this
height.$d$),
  (238, 77, ARRAY['ceiling', 'painting', 'ice']::text[], $d$   A thin layer of ice covers this beautiful painting, which depicts a druid
and a silver-haired woman in ranger's garb sailing on a boat towards a large,
green landmass.  The ocean is a stunning blue, but there seems to be no other
crew on the ship they are in, though it is quite large.$d$),
  (238, 78, ARRAY['wall', 'walls']::text[], $d$   The walls to the north and east are very cold to the touch.  They probably
open directly on to the outer atmosphere...  But they seem quite thick enough
to keep out the worst of the cold.$d$),
  (238, 78, ARRAY['ceiling', 'complex', 'carving', 'carvings']::text[], $d$   The blue stone which makes up the ceiling is carved into a bas-releif
picture of a ranger and a druid making a pact with a variety of forest spirits.
The ranger is clad in heavy furs, though the forest looks to be temperate.
The druid has a new moon symbol on his forehead.$d$),
  (238, 79, ARRAY['ceiling', 'bas', 'relief', 'bas-relief', 'carving', 'carvings', 'figures', 'figure']::text[], $d$   The carvings here show a maliciousl demon laughing cruelly at an injured
druid, while a ranger looks on in horror.  Moonstones speckle the picture,
especially around the ranger and the druid.$d$),
  (238, 79, ARRAY['moonstone', 'moonstones', 'gems']::text[], $d$   Moonstone is a soft-looking, pale greyish stone with tiny flecks of gold or
silver in it, though sometimes it is clear..  It is called "moonstone" because
the color is similar to that of a white or silver moon.$d$),
  (238, 80, ARRAY['pentagram', 'inscribed', 'circle']::text[], $d$   There is a pentagram inscribed in a circle, nearly covered in ice, on the
western wall.  However, the circle is not a solid line, but rather a line of
flowing text which reads: "He who liked indigo was fond of fighting bugs".$d$),
  (238, 80, ARRAY['Cloud', 'clouds', 'landscape', 'cloudscape']::text[], $d$   Sharp and fluffy, thin and thick, clouds of every descriptor are visible.
The higher ones are thinner and sharper-looking, blowing about swiftly in the
heavy winds.  Down lie some softer-looking clouds and, below them, the ground.
It looks like a long drop.$d$),
  (238, 81, ARRAY['ceiling', 'walls', 'engravings', 'figures', 'scenes']::text[], $d$   The carvings in this part of the hall show a beautiful woman in ranger's
garb pleading with some stubborn-looking forest spirits while a druid lies
badly injured nearby.  The woman's hair is silvery, and all the eyes in the
picture are replaced with moonstones.$d$),
  (238, 82, ARRAY['ceiling', 'carving', 'carvings', 'bas', 'relief', 'bas-relief']::text[], $d$   The carvings here are masterful but sad.  The subject of the ornamentation
is a woman descending into madness over the death of her beloved.  The woman is
beautiful in her sorrow, but it is a rather chilling scene.$d$),
  (238, 82, ARRAY['door', 'south', 'sun']::text[], $d$   The door is inset with moonstones in the shape of the rising sun.  Someone
must have had a strange sense of humor.$d$),
  (238, 83, ARRAY['ceiling', 'carving', 'carvings']::text[], $d$   The carvings on the ceiling are precise and eye-pleasing, though their
subject is somewhat grim.  They show a woman in ranger's garb howling in grief
near a grave marker while the forest decays around her.  It is as though a
shadow is eminating from her, turning the once-beautiful forest into a swampy
wasteland.  Her forehead shows a symbol of two concentric circles in gold,
edged in black.$d$),
  (238, 84, ARRAY['carving', 'carvings', 'ceiling', 'detailed']::text[], $d$   Carefully carved bas-relief style figures on the ceiling show a bereaved
woman in a dark swamp looking pleadingly at the image of a goddess.  The
goddess is marked with an ancient symbol for destiny and endings, and a wave of
her hand in the next panel shows the woman dead and peaceful expressions on
both faces.  Celestite accents both panels beautifully.$d$),
  (238, 84, ARRAY['sun', 'door', 'north', 'rising', 'gold', 'red']::text[], $d$   Inlaid with rare, expensive red gold is the image of the rising sun on the
door to the north.  It shimmers gorgeously in even the faintest light, standing
out all the more because it is surrounded by the dark blue stone of the walls
and the pale blue celestite crystals.$d$),
  (238, 85, ARRAY['celestite', 'crystal', 'crystals']::text[], $d$   Celestite is a pale blue stone, very rare in most parts of the world.  Its
crystals form four-pointed shapes that catch the light and sparkle easily,
multiplying any light in the hall into a brilliant glimmer.$d$),
  (238, 85, ARRAY['emblem', 'dragon', 'dragons', 'battle', 'ceiling']::text[], $d$   On the ceiling are two dragons locked in battle, the carving so realistic
that the artist must have studied at least one live dragon.  On the southern
end is a massive wyrm done in silver with sapphire eyes and diamond talons and
fangs.  Snarling at it viciously from the northern end of the room is a dragon
inlaid with a green metal with emeralds for eyes and ruby blood dripping from
its diamond fangs and talons.  The reason for their battle cannot be concluded
from the picture, but it surely shook the world if it actually happened.$d$),
  (238, 86, ARRAY['circle', 'inscribed', 'pentagram']::text[], $d$   There is a pentagram inscribed in a circle, barely noticeable against the
eastern wall.  The circle is a line of text which reads: "The gnome was often
clad in lavendar".$d$),
  (238, 86, ARRAY['alchemist', 'circles', 'rune', 'runes', 'symbols', 'arcane']::text[], $d$   The symbols are scattered here, many glowing with a cool light.  The runes
are arcane runes of light and protection, and the alchemical circles seem to be
decorative rather than functional.$d$),
  (238, 90, ARRAY['decorations', 'decoration', 'sapphire', 'sapphires']::text[], $d$   The sapphires are either carved with exquisite skill or shaped by magic,
because fist-sized chunks of the blue gem are shaped like many dangerous and
beautiful creatures.  Here is a dragon, there is a seraph, over there is a
couatl...$d$),
  (300, 3, ARRAY['pole', 'poles', 'fabric', 'fabrics']::text[], $d$The long, slender poles and gaily colored fabrics could only have come from the
outdoor stalls that sellers could rent on a daily basis to hawk their wares.
Now they are rent and broken, and piled in a smouldering heap.$d$),
  (300, 4, ARRAY['shard', 'shards', 'pottery', 'pot']::text[], $d$The pots appear to have been simple and large, with wide mouths.  Their
presence reinforces the rumor that the Tyllweddians liked their fish extremely
fresh, so that some sellers would keep them alive in large clay urns in Market
Square.  Alas, it has all been spoiled.$d$),
  (300, 13, ARRAY['rubble', 'wreckage', 'rubbish', 'trash']::text[], $d$Burnt and broken planks are shoved into two piles to either side of the path.
They look to have been carefully whitewashed and well-cared for for many years.
Many varied pieces of pottery lie underfoot and in the piles of rubbish as
well.  Closer inspection reveals that a variety of plants have sprouted,
hinting that this may once have been a grocer's shop.$d$),
  (300, 14, ARRAY['crater', 'craters']::text[], $d$They are pretty small, being only a couple of feet across, but the force of the
explosions that created them must have been substantial.  There is even some
bloodstaining on nearby bits of wood.  Whatever caused them failed to save the
building, however.$d$),
  (300, 14, ARRAY['smoke', 'sulfur', 'sulphur']::text[], $d$The smoke seems to be pouring out of a hole hidden under a very large pile
of rubble. It is yellowish-gray in color, and highly obnoxious in odor.$d$),
  (300, 44, ARRAY['tail', 'bronze', 'mermaid', 'mermaid''s', 'mermaids']::text[], $d$The tail is rather large, but its wide fan-shape marks it as the tail of a
fish, not a mermaid.  Local rumors tell that the inn once had an entire bronze
fish, but it was broken during the invasion.  The enterprising new inkeeper
made the best of the situation, knowing that orc soldiers are connoissers of
neither fish nor mermaids.$d$),
  (300, 68, ARRAY['signpost', 'sign']::text[], $d$Upon the signpost is a slab of wood with a charred inscription. An image
lies below, depicting a nest of serpents. The inscription reads:

        Mokh-ob
    Krimpphosh-hudh$d$),
  (302, 1, ARRAY['bootprints', 'footprints', 'prints', 'tracks']::text[], $d$Several cart tracks crisscross the dust, but the overwhelming majority of
visible traffic appears to be booted individuals.  They cover the road and lead
in both directions.$d$),
  (302, 2, ARRAY['mountains']::text[], $d$The mountains are far off in the distance to the southeast.  They are gray or
black and topped with white.  Many high peaks are visible.  This road appears
to be heading in the general direction of a low point, where there may be a
pass.$d$),
  (302, 2, ARRAY['forest']::text[], $d$The trees of the forest blend together, being so far away, but they are dark
green and thick. A few orange or yellow patches stand out, which are
probably trees in their fall colors.$d$),
  (302, 2, ARRAY['outcrop', 'outcrops']::text[], $d$The outcrops are dry and flaky stone. They are a bit weathered but jagged.
Yellow, orange, and gray lichens cover their surfaces like spatter from
a bored painter.$d$),
  (302, 3, ARRAY['oak', 'oaks']::text[], $d$They are medium-sized, with dry light-gray bark and blueish-green leaves.
They look as though they use less water than a kangaroo rat.$d$),
  (302, 5, ARRAY['tracks', 'bootprints']::text[], $d$The tracks are too many to make much out, overlapping and intermingling
as they do. It is obvious that many boot-shod persons use this road, along
with horses and wheeled vehicles.$d$),
  (302, 8, ARRAY['bramble', 'brambles', 'sapling', 'saplings']::text[], $d$They look like recent growth, the oldest perhaps three years old. They are
growing in the road, where a decent maintainer would not tolerate them.
They have been cleared from a smaller pathway, however.$d$),
  (302, 12, ARRAY['road']::text[], $d$The traffic on the road seems to turn south away from the main route. It is
quite overgrown to the east.$d$),
  (302, 35, ARRAY['creek', 'water']::text[], $d$The creek flows down off the hillside to the north, crosses the road, and
continues south.  The water looks clear enough, but it is by no means clean,
for bits of trash and debris lie in its bed.$d$),
  (302, 35, ARRAY['metal', 'wood', 'debris', 'trash']::text[], $d$Debris is scattered all around here.  It is composed of old nails, scraps of
metal, rotten leather, and splintered boards.  There are also a couple of hilts
or mace handles, now cracked.  Even a few bones are visible, some of them
human.$d$),
  (302, 36, ARRAY['creek', 'bed']::text[], $d$The creek's clear water burbles as it runs over the broken stones and
battle debris. There are definitely no white stones, however.$d$),
  (302, 36, ARRAY['debris', 'trash']::text[], $d$Broken pieces of armor armor and weapons lie scattered all about.  Many of them
are barely visible beneath the broken rock; perhaps a more determined search
would find something of value.$d$),
  (302, 41, ARRAY['valley', 'farm', 'farms']::text[], $d$Farmouses and barns lie in ruins, some burned, others simply knocked down.
The fields are muddy and overgrown with weeds for the most part.  At least one
field seems to be planted, however.$d$),
  (302, 42, ARRAY['scat', 'pile', 'piles', 'poop', 'feces', 'faeces']::text[], $d$Indeed, the small furry critters that scurry about feeding on hardy mountain
grasses have left unmistakable evidence of their digestive processes.$d$),
  (302, 43, ARRAY['valley', 'farm', 'farms']::text[], $d$The valley is bisected by a shimmering river that flows in from the northeast.
It is dotted with farmhouses.  The extents of each field are visible, though to
the trained eye it is clear that few crops now grow.  It is hard to tell from
this great distance, but it appears that many of the farmhouses lie in ruins.$d$),
  (302, 54, ARRAY['boulder', 'boulders']::text[], $d$The boulders are huge and jagged.  They look like the kind of scree that might
collect in the bottom of a ravine below steep rocky ridges.  There are
innumerable crevices and hiding places among them.  Is that a board sticking
out from under one?$d$),
  (302, 54, ARRAY['board', 'coach', 'stagecoach']::text[], $d$Speaking of stagecoaches, it looks as though one may have crashed here.
Closer examination reveals the hub of a wheel - with broken spokes -
and a bleached bones, which seem to have come from horses.$d$),
  (302, 60, ARRAY['pile', 'baubles']::text[], $d$Somehow, whoever gathered these items has managed to miss anything of value.
Colored stones and broken wishbones are piled high among pretty maple leaves.
Not even a scrap of leather awaits the enterprising looter.$d$),
  (350, 2, ARRAY['boulder', 'rock', 'rocks']::text[], $d$There is a huge rock slab lying here.  It looks to have fallen from the slope
to the west, but there are so many other rocks littering the path its hard to
tell for sure.$d$),
  (350, 187, ARRAY['waterfall', 'curtain', 'water', 'falls']::text[], $d$Gazing towards the waterfall you can see what looks to be an entrance to a cave
just behind the curtain of water.  The waterfall looks small enough to walk
through without much trouble.$d$),
  (350, 188, ARRAY['veins', 'vein', 'mineral', 'minerals', 'mineral-veins']::text[], $d$The veins are about an inch thick, and each glows with a gentle yellow light.
There are many of these mineral veins streaking the walls of this cave.$d$),
  (350, 189, ARRAY['veins', 'minerals', 'vein', 'mineral', 'mineral-veins']::text[], $d$The veins are about an inch thick, and each glows with a gentle yellow light.
There are many of these mineral veins streaking the walls of this cave.$d$),
  (350, 190, ARRAY['vein', 'mineral', 'veins', 'minerals', 'mineral-veins']::text[], $d$The veins are about an inch thick, and each glows with a gentle yellow light.
There are many of these mineral veins streaking the walls of this cave.$d$),
  (350, 191, ARRAY['vein', 'veins', 'mineral', 'minerals', 'mineral-veins']::text[], $d$The veins are about an inch thick, and each glows with a gentle yellow light.
There are many of these mineral veins streaking the walls of this cave.$d$),
  (360, 1, ARRAY['tapestry', 'symbol', 'rug', 'book', 'eternity']::text[], $d$A book set within a shimmering golden pyramid reflects the
light in an array of colors. The book is infinite in length
and etched on its cover is a symbol. The symbol gleams in
the purest silver and seems to twist about itself.$d$),
  (360, 2, ARRAY['statue', 'stone', 'priest', 'priests']::text[], $d$A simple priest well armored for battle holds up a
holy symbol as if in an empowered shout.$d$),
  (360, 3, ARRAY['statue', 'priest', 'cleric']::text[], $d$The statue is of Girr'Kaaz, an ancient priest who was destroyed by the vile
Blackmourne in an act of jealous treachery.  Blackmourne's chosen one was
installed into power long ago and is rumored to be an evil guildmaster to
this day.  No one knows what became of the Kaaz lineage...$d$),
  (360, 3, ARRAY['glass', 'case', 'sphere']::text[], $d$An ornate cabinet stands near the corner of the stage. It's closed by a
simple glass door that shields an orb of pure crystal. The sphere glows
slightly and you feel better in its presence.$d$),
  (360, 11, ARRAY['statue', 'sorcerer', 'mage', 'ne', 'kaaz']::text[], $d$The statue is of Ne'Kaaz the ancient arcane one. Brother in the Kaaz
clan, he disappeared after Blackmourne's vile sin against the mortals.
No one is sure of what ever happened to him. Rumors circulate that he
is a god now or just wanders as a sage in the wilderness...$d$),
  (360, 11, ARRAY['cauldron', 'pot', 'silver', 'glass', 'case']::text[], $d$The cauldron boils slightly but seems cool to the touch. The posts of the
pyramid are short and you can easily reach the glass case housing the glowing
sphere within.$d$),
  (360, 12, ARRAY['statue', 'warrior', 'elia', 'kaaz']::text[], $d$The statue is of the sister of the Kaaz clan, Elia.  She is posed in a
form of great rage, as though she were about to strike. Her face is
sad though, at the loss of her brother Girr. Elia'Kaaz is also missing
from the realms as is the entirety of the Kaaz clan. Those who are
said to find and befriend them are rumored to gain powerful skills from
their ancient knowledge.$d$),
  (360, 13, ARRAY['door', 'trapdoor', 'wood', 'ring']::text[], $d$You look up and notice a trapdoor at the top of the stair with a simple
ring to open it.$d$),
  (361, 26, ARRAY['idol', 'structure']::text[], $d$The idol is about 30 feet high and resembles a druid in a
casting pose.  Beneath the staff of the druid is a circle
of stones resembling a well.$d$),
  (361, 26, ARRAY['well']::text[], $d$This structure is about three feet high and six feet across
and the wind seems to flow down into it.  No water has been
pulled from here in recent years.$d$),
  (363, 9, ARRAY['flower', 'flowers']::text[], $d$They appear to be an ordinary assortment of wildflowers, though they do grow
suspiciously thick near the path and the cavern entrance.  There are buttercups
and paintbrush, among other plainer flowers.$d$),
  (363, 9, ARRAY['waterfall']::text[], $d$It is tall, perhaps over one hundred feet.  Much of it has devolved into mist
by the time it reaches the ground.  Far up near the top, on the opposite side,
there seems to be a platform of some kind in the cliff wall.$d$),
  (363, 28, ARRAY['flower', 'flowers', 'pot', 'pots', 'flowerpot', 'flowerpots']::text[], $d$These little pots contain an assortment of violets.  They are blue, red, and
indeed, violet.  Their perfume drifts subtly in the air, competing with the
aroma of baked bread.$d$),
  (363, 37, ARRAY['flower', 'flowers', 'plant', 'plants', 'marigold', 'marigolds', 'snapdragon', 'snapdragons', 'buttercup']::text[], $d$The flowers are growing nicely in small clay pots.  They look a little out of
place in this lawless hideout.  Nevertheless they brighten up the room with
their colors and scents.$d$),
  (364, 21, ARRAY['sign', 'post', 'signpost']::text[], $d$The sign is written with spiky runish letters. It reads:

    Travelers beware -- the western lands abound with dangers
    of unknown nature. The terrain is far too dangerous for
    any travel at this time. This is the only warning I can give.

It is signed with a single word, probably a name: "Sirestis".$d$),
  (370, 0, ARRAY['sign', 'additional']::text[], $d$                                NO TRESPASSING!

Entering this mine is considered a foolish act, and therefore all who enter
are entering at their own risk! All who enter will be prosecuted if they are
ever found alive...
Signed this 23rd day of the Month of the Firestorm
Year 458
By the Dwarves of Anduin$d$),
  (370, 5, ARRAY['rock']::text[], $d$It covers the entire floor in one solid piece. It appears as if several
attempts were made to move the rock.$d$),
  (370, 8, ARRAY['bones', 'bone']::text[], $d$Some of the bones look to be rather large for a human, and the other bones
look to be too small to be human.$d$),
  (370, 9, ARRAY['rubble']::text[], $d$Large boulders and rocks are scattered about the ground. A big piece
of dornick catches your eye.$d$),
  (370, 10, ARRAY['bones', 'bone']::text[], $d$Some of the bones look to be rather large for a human, and the other bones
look to be too small to be human.$d$),
  (370, 11, ARRAY['maps', 'map']::text[], $d$The maps show the site of the cave-in and several proposed rescue tunnels
to attempt to find survivors.$d$),
  (370, 11, ARRAY['table', 'makeshift']::text[], $d$This table couldn't have possibly fit through that hole assembled. The
table is made out of a few scraps of wood...nothing you'd consider even
eating on!$d$),
  (370, 14, ARRAY['rocks', 'rock', 'boulder', 'boulders']::text[], $d$Those rocks and boulders are HUGE, no wonder why they were unable
to dig around them.$d$),
  (370, 15, ARRAY['rocks', 'rock', 'boulder', 'boulders']::text[], $d$Those rocks and boulders are HUGE, no wonder why they were unable
to dig around them.$d$),
  (370, 16, ARRAY['rocks', 'rock', 'boulder', 'boulders']::text[], $d$Those rocks and boulders are HUGE, no wonder why they were unable
to dig around them.$d$),
  (370, 37, ARRAY['lock', 'combination']::text[], $d$The lock has three dials. Each dial contains 2 digits. The lock's
current setting is 12.11.96. There's a small inscription to the right
of the three dials.$d$),
  (370, 37, ARRAY['inscription', 'writing']::text[], $d$Trolls take note:
     I made this lock easy for you moronic trolls! I gave each of
     you the numbers, so you don't forget! Type 'open ##.##.##'
     to open the door.

        -Baldathor$d$),
  (370, 48, ARRAY['tree', 'roots', 'n', 'north', 'root', 'broken', 'cut']::text[], $d$   The roots look like oak or some other strong wood.  Many of the cuts are
healed over, but not all of them.  The roots seem to hungrily caress the water
where it pools on the floor, seeking its life-giving nourishment.$d$),
  (370, 49, ARRAY['bones', 'pile', 'corner']::text[], $d$   A small pile of animal bones lies here, quite brittle to the touch.  Some
appear to have teeth marks on them.$d$),
  (370, 72, ARRAY['boulder', 'rock', 'down', 'd']::text[], $d$   Down lies a huge boulder of rough granite, black and pink and filled with
shiny mica and opaque white quartz inclusions as well as an oddly colored
mineral, barely visible beneath the lichens of all colors: black, grey, green,
and even orange.  Even an ogre could not move this boulder.$d$),
  (410, 1, ARRAY['track', 'tracks']::text[], $d$The tracks are perfectly circular with a deep depression in the center
of each.$d$),
  (410, 1, ARRAY['debris', 'chunks']::text[], $d$Each hunk of dirt is approximately the size of your fist. They are slightly
molded into hourglass figures.$d$),
  (410, 2, ARRAY['track', 'tracks']::text[], $d$The tracks are perfectly circular with a deeper depression in the center
of each.$d$),
  (410, 2, ARRAY['path', 'trail']::text[], $d$The path runs straight up and down the steep side of the mound with no
switchbacks.$d$),
  (410, 5, ARRAY['paper-lining', 'paper', 'lining']::text[], $d$Very rough to the touch, it is amazingly tough. Your sweaty palms are
thoroughly dry after just a brief contact. It seems to absorb the moisture
from the surrounding air and dissipate it into the soil, keeping the
humidity level well-regulated.$d$),
  (410, 6, ARRAY['paper-lining', 'paper', 'lining']::text[], $d$Very rough to the touch, it is amazingly tough. Your sweaty palms are
thoroughly dry after just a brief contact. It seems to absorb the moisture
from the surrounding air and dissipate it into the soil, keeping the
humidity level well-regulated.$d$),
  (410, 7, ARRAY['hiver', 'hivers']::text[], $d$The line of Workers marches past you without a single glance. They move
together in perfect coordination as though they share a single thought.
Each is fully aware of the job the Hive needs her to perform and you
just aren't on the list.$d$),
  (410, 7, ARRAY['trail', 'gooey']::text[], $d$A clear amber fluid drips slowly from their feet, forming a small trail.
A few of the Workers stop briefly to clean a bit of it up, but it's a
futile effort. Each one leaves a little more in passing.$d$),
  (410, 7, ARRAY['paper-lining', 'paper', 'lining', 'coating']::text[], $d$The tough coat of the tunnel has been damaged by the sticky fluid. Bits
and pieces have been lifted and carried away. It will take the workers
some real effort to repair the damage here.$d$),
  (410, 8, ARRAY['wax', 'floor', 'coat', 'hard', 'waxy']::text[], $d$A yellowish wax has been liberally applied to all surfaces of the chamber.
The seal helps give this area it's own environment, distinct from the
rest of the Hive. A light, cinnamony odor assaults your nostrils from
the southeast.$d$),
  (410, 8, ARRAY['packages', 'package']::text[], $d$Spherical containers of wax are filled with a clear, amber colored fluid
and stuck into the wax seal of the chamber for storage. The containers
look like they've been melted into place to ensure their safety.
It's quite a food store!$d$),
  (410, 9, ARRAY['wax', 'floor', 'coat', 'hard', 'waxy']::text[], $d$A yellowish wax has been liberally applied to all surfaces of the chamber.
The seal helps give this area it's own environment, distinct from the
rest of the Hive. A light, cinnamony odor assaults your nostrils from
the south.$d$),
  (410, 9, ARRAY['packages', 'package']::text[], $d$Spherical containers of wax are filled with a clear, amber colored fluid
and stuck into the wax seal of the chamber for storage. The containers
look like they've been melted into place to ensure their safety.
It's quite a food store!$d$),
  (410, 10, ARRAY['packages', 'package']::text[], $d$Spherical containers of wax are filled with a clear, amber colored fluid
and stuck into the wax seal of the chamber for storage. The containers
look like they've been melted into place to ensure their safety.
It's quite a food store!$d$),
  (410, 10, ARRAY['wax', 'floor', 'coat', 'hard', 'waxy']::text[], $d$The natural settling of the earth mound has opened several deep pressure
cracks in the wax sealing here. Many of the food storage packages have
been broken open. One has been displaced and lies on the floor.$d$),
  (410, 11, ARRAY['packages', 'package']::text[], $d$Spherical containers of wax are filled with a clear, amber colored fluid
and stuck into the wax seal of the chamber for storage. The containers
look like they've been melted into place to ensure their safety.
It's quite a food store!$d$),
  (410, 11, ARRAY['wax', 'floor', 'coat', 'hard', 'waxy']::text[], $d$A yellowish wax has been liberally applied to all surfaces of the chamber.
The seal helps give this area it's own environment, distinct from the
rest of the Hive. A light, cinnamony odor assaults your nostrils from
the east.$d$),
  (410, 12, ARRAY['gem', 'gems']::text[], $d$The gems pulse faintly with colored light... After a second glance,
you realize that you've been deceived. They aren't gems. They're
Hiver eyes, plucked from their owners and mounted like trophies in
the wall.$d$),
  (410, 13, ARRAY['flakes', 'lining', 'tunnel']::text[], $d$Flakes of chitin as large as your head dot the walls and floor of the
tunnel. Their crimson hue gives you an eerie feeling as they crumble
between your fingers like dried cakes of blood.$d$),
  (410, 19, ARRAY['mulch', 'lining']::text[], $d$Chewed plant fibers, flakes of yellow chitin, and some sort of adhesive
have been mixed to perfection, laid down, and allowed to harden. The
surface is very rough to the touch. A few crags stick out and grab at
your clothing as you pass down the tunnel.$d$),
  (410, 21, ARRAY['spit', 'spitting', 'spittle']::text[], $d$Well, now you know how the Hivers line their tunnels. The Workers scoop
a mouthful of plant fiber from a nearby pile, add a scoop from a pile
of cast-off chitin from the queen, and chew. Their own saliva is the
unknown adhesive that binds it all together. When the mix has just the
right consistency, they spit it at the wall and pack it down with four
of their eight legs.$d$),
  (410, 23, ARRAY['scratch', 'scratches', 'flooring', 'gouge', 'gouges']::text[], $d$Narrow but incredibly deep gouges have been sliced out of the walls and
floor here. It almost looks like someone took a sword and hacked
randomly. Or... maybe blows were deflected in some mighty battle...$d$),
  (410, 24, ARRAY['depression', 'depressions', 'deep']::text[], $d$The blades penetrated through the entire layer of lining to the bare earth
underlying the tunnel.$d$),
  (410, 24, ARRAY['scratch', 'scratches', 'gouge', 'gouges', 'floor']::text[], $d$A thin, incredibly sharp blade has scooped out a deep depression. Actually,
eight depressions run in a nearly straight line to the south.$d$),
  (410, 25, ARRAY['patch', 'plug', 'plug-like', 'opening']::text[], $d$This plug once served as a door to let something through, but the new
patch holds it securely shut. None of your efforts can open it.$d$),
  (410, 26, ARRAY['hiver', 'large', 'drone']::text[], $d$Something has ripped the legs and budding wings from the immature body of the
Drone. The body has been so mangled by the ferocity of the attack that you
cannot tell what color the young male was in life. Green would probably be
a good guess, based on the Hivers' tendency to color-code everything.$d$),
  (410, 27, ARRAY['stain', 'dark']::text[], $d$A fluid foreign to the usual coating mixture has left a permanent spray
mark. The deep musky odor catches in the back of your throat as your
eyes begin to water.$d$),
  (410, 28, ARRAY['gems', 'gem', 'small', 'green']::text[], $d$On closer examination, you realize that they aren't gems. They're the
multi-faceted eyes of Hivers.$d$),
  (410, 29, ARRAY['barrier', 'low', 'entrance', 'passage']::text[], $d$The Workers are busily narrowing the entrance to the next chamber,
leaving just enough open space for their narrow bodies to slide through.$d$),
  (410, 36, ARRAY['gems', 'gem', 'small', 'blue']::text[], $d$On closer examination, you realize that they aren't gems. They're the
multi-faceted eyes of Hivers.$d$),
  (410, 37, ARRAY['gems', 'gem', 'small', 'blue']::text[], $d$On closer examination, you realize that they aren't gems. They're the
multi-faceted eyes of Hivers.$d$),
  (410, 38, ARRAY['gems', 'gem', 'small', 'blue']::text[], $d$On closer examination, you realize that they aren't gems. They're the
multi-faceted eyes of Hivers.$d$),
  (410, 42, ARRAY['line', 'plug', 'concealed']::text[], $d$The Blue Drone evidently tried to conceal his secret passage. He
hasn't done a very good job. Of course, tunnelling isn't exactly his
main purpose in life.$d$),
  (410, 43, ARRAY['gem', 'gems', 'milky']::text[], $d$Eyes, plucked from various Hivers, gleam with gem-like facets
from the walls. Their light waxes and wanes in concert. Even
now, these Hivers work together in perfect cooperation.$d$),
  (410, 45, ARRAY['gem', 'gems', 'milky']::text[], $d$Eyes, plucked from various Hivers, gleam with gem-like facets
from the walls. Their light waxes and wanes in concert. Even
now, these Hivers work together in perfect cooperation.$d$),
  (410, 46, ARRAY['egg', 'eggs', 'egg-sacks', 'sacks']::text[], $d$They feel warm to the touch and shift beneath your hand as though
the unborn larvae can sense your presence.$d$),
  (410, 49, ARRAY['gem', 'gems', 'milky']::text[], $d$Eyes, plucked from various Hivers, gleam with gem-like facets
from the walls. Their light waxes and wanes in concert. Even
now, these Hivers work together in perfect cooperation.$d$),
  (410, 50, ARRAY['chrysali', 'chrysalis']::text[], $d$The discarded chrysali are a vibrant blue-green in color, reminding you of
the color of the sky on the clearest winter mornings. Their split sides
reveal their construction of overlapping fibers.$d$),
  (410, 50, ARRAY['pupae', 'pupa']::text[], $d$The hapless offspring remain suspended... their birth-shells transformed
by fate into their coffins.$d$),
  (410, 51, ARRAY['egg-cases', 'egg-case', 'egg', 'eggs']::text[], $d$All the colors of the rainbow ripple across the surface of the cases in
quick succession as the unborn larvae squirm and twist, locked in the
dreams of the restless.$d$),
  (410, 51, ARRAY['chrysalis']::text[], $d$The pearly chrysalis is vaguely tinted with red. It is warm to the touch
and throbs softly beneath your fingers, pulsating with the beat of the Hive.$d$),
  (410, 52, ARRAY['gem', 'gems', 'milky']::text[], $d$Eyes, plucked from various Hivers, gleam with gem-like facets
from the walls. Their light waxes and wanes in concert. Even
now, these Hivers work together in perfect cooperation.$d$),
  (410, 57, ARRAY['lesser']::text[], $d$The Attendant's body has been violently dismembered. It looks like she died
in a valiant effort to protect her Queen.$d$),
  (410, 57, ARRAY['husk', 'dead', 'dried']::text[], $d$Scratches and holes cover the Queen's once magnificent chitin. Stains mark
trails where the blood flowed from her body in her final death throes. Her
mandibles are locked as though still biting at her attacker.$d$),
  (410, 66, ARRAY['spot', 'tiny-spot', 'dark-spot', 'tiny-dark-spot']::text[], $d$The spot is actually an opening! Something has drilled into the very
heart of the gem, creating a hole just the right size for a Hiver to
reach inside.$d$),
  (410, 66, ARRAY['gem']::text[], $d$The single large gem casts rainbows of light about the room. Patterns of
green, red, blue, and yellow light cover the walls. Its only flaw is a
tiny dark spot in its exact center.$d$),
  (410, 70, ARRAY['gems', 'gem']::text[], $d$On closer examination, you realize they aren't gems at all. They are
the faceted eyes of Hivers.$d$),
  (410, 70, ARRAY['drone', 'prismatic', 'father', 'body']::text[], $d$The father of the race sleeps peacefully in death. No hint of violence
mars his body.$d$),
  (410, 71, ARRAY['gems', 'gem']::text[], $d$On closer examination, you realize they aren't gems at all. They
are the faceted eyes of Hivers.$d$),
  (411, 2, ARRAY['moss-like-seaweed', 'moss-like', 'seaweed', 'seaweeds', 'mossy']::text[], $d$Thin root-like tendrils grasp the rocks in an unbreakable grip. What appears
to be many seaweeds at first glance proves to be a single entity on closer
examination. One incredibly hardy alga seizes its chance at life in this
narrow zone where sea water mists the cool air just enough and lone rays of
sunlight sneak by the cliff.$d$),
  (411, 2, ARRAY['chalky-cliff', 'cliff', 'chalky']::text[], $d$The thick calcium coat of the cliff crumbles beneath your fingers, leaving
a damp white powder clinging to your hand.$d$),
  (411, 2, ARRAY['sand', 'fine-grained', 'fine-grained-sand', 'fine']::text[], $d$The creamy sand is amazingly dry. You would have expected it to feel damp
beneath you, but through some miracle, no water penetrates it. The soft
powder shifts to conform to your shape then slides back. Almost no trace
of your passage is left behind...$d$),
  (411, 3, ARRAY['fish-scales', 'scales', 'fish', 'litter']::text[], $d$A slightly smelly collection of discarded fish heads, tails, fins, and
scales stick to the breaker's top in every sheltered cranny.$d$),
  (411, 3, ARRAY['fish-bones', 'bones']::text[], $d$Fine bones and thick ones lie among the litter of fish heads. THICK fish
bones? Another look reveals that some of these aren't from fish at all.
Tiny finger bones from a human hand are caught deep in a narrow fissure.
Suddenly, the breeze seems more chill than refreshing...$d$),
  (411, 6, ARRAY['rock', 'rocks', 'jagged-rocks', 'jagged']::text[], $d$The greenish sea-foam fills the spaces and narrow gaps of the field of
head-sized stones. The stiff easterly breeze sculpts the foam into
fantastic forms that are just as quickly blown away by the strength of
their own creator.$d$),
  (411, 8, ARRAY['red', 'slime', 'gel']::text[], $d$The clear red substance oozes between your fingers and falls back into the
water with a plop. A slimy residue is stuck on your hand now. Ick.$d$),
  (411, 10, ARRAY['sand', 'sandy']::text[], $d$You see nothing exceptional about the light brown sand of the shallow
bottom. The ripples do form a rather pretty pattern of ridges...$d$),
  (411, 10, ARRAY['isthmus']::text[], $d$The low isthmus winds upward in two directions: north toward the peninsula
and south toward the mainland.$d$),
  (411, 11, ARRAY['tracks', 'track', 'deep-set-tracks', 'deep-set-track']::text[], $d$The track is slightly larger in width than your hand and very deep, as
though the animal was moving at great speed across this beach. The top
portion is oval -- similar to that of a horse -- but two forward
facing triangles indicate some type of projection, like a claw.$d$),
  (411, 18, ARRAY['path', 'pathway']::text[], $d$The rocky path looks like it's more suited to mountain goats than to
humans, but you could probably make the steep climb. It looks like it
gets a lot of traffic.$d$),
  (411, 26, ARRAY['rock', 'rocks', 'jagged', 'jagged-rock', 'jagged-rocks']::text[], $d$The knife-edged rocks thrust boldly upward, promising deep lacerations
to any traveller foolish enough to attempt a crossing that is less than
cautious.$d$),
  (411, 26, ARRAY['shoe']::text[], $d$The round piece of leather once wrapped snugly around a small foot. A single
thong threaded through the edges to hold it in place. Evidently, the force
applied by the knife-edged rocks was enough to snap the thong, allowing the
shoe to be pulled off and held by the rocks like some bizarre keepsake.$d$),
  (411, 26, ARRAY['tatters-of-clothing', 'tatters', 'clothing', 'tattered-clothing']::text[], $d$Threads and small pieces of cloth are caught between the teeth of the
rocks, remnants of some meal taken from many travellers.$d$),
  (411, 27, ARRAY['path', 'pathway']::text[], $d$Broken tops are the only remains of the jagged rocks that once thrust
boldly up here. They have been used to fill in the angles and holes that
once separated them from each other. Seaweed has been packed into the
remaining spaces in an attempt to make the makeshift road more stable.$d$),
  (411, 28, ARRAY['path', 'pathway']::text[], $d$Crushed rock has been packed tight with seaweed to smooth out the natural
cavities and heights between the boulders that make up this isthmus.$d$),
  (411, 28, ARRAY['drop-off']::text[], $d$The edge of the cliff threatens to break away beneath your weight. A few
small rocks clatter down the face and into the shallows below.$d$),
  (411, 29, ARRAY['boulder', 'boulders', 'loose-boulder', 'loose-boulders']::text[], $d$The line of boulders that form the isthmus once made a tall column
up the side of the cliff. Some mighty force ripped the column from
its home to form the narrow land bridge.$d$),
  (411, 29, ARRAY['ocean']::text[], $d$Deep blues, grays, and greens shift and play in an ever-changing, never-
ending pattern. The grumbling of the sea is a comforting murmur, like the
low protestations of a caring mother.$d$),
  (411, 29, ARRAY['tree', 'trees', 'shrub', 'shrubs', 'trees-and-shrubs']::text[], $d$Twisted to odd shapes by the winds that sweep the peninsula, the trees
and shrubs that grip the top of the cliffs bend and sway easily, long
conditioned to the capricious breezes.$d$),
  (411, 29, ARRAY['path', 'pathway']::text[], $d$Founded on less uneven ground, the path here is much more stable than the
switchbacks below.$d$),
  (411, 30, ARRAY['path', 'pathway']::text[], $d$Fine fracture lines criss-cross the paving. A symbol is engraved on one of
the surfaces.$d$),
  (411, 30, ARRAY['tree', 'trees', 'shrubs', 'shrub', 'shrubbery']::text[], $d$The trees and shrubs atop the cliff are twisted into bizarre shapes. The
winds sift mournfully through their branches.$d$),
  (411, 31, ARRAY['herbs', 'bed', 'herb-bed', 'garden']::text[], $d$This would be a very useful garden for any adventurer. Comfrey for cuts
and bruises. Thyme for headaches. Vervain? Aphrodisiac and spell-component!
You wonder why these people need that! Especially with witch-repelling
elder growing next to it... Rue and rosemary for memory. Hmmm... You wish
you had some of that pennyroyal when you went through the swamps to repel
the insects... So many herbs here, and so little time!$d$),
  (411, 34, ARRAY['monoliths', 'monolith']::text[], $d$Well, which one do you want to look at -- the stag-topped or
the pole-topped?$d$),
  (411, 34, ARRAY['pole-topped']::text[], $d$The engravings on the pole-topped monolith show a group of young girls
holding a cup in one hand, a rope or string in the other as they dance
about a tall post. The ropes lead to the top of the post. All of the
girls wear a crown of greenery. A few of them are shown drinking from
their cups.$d$),
  (411, 34, ARRAY['stag-topped']::text[], $d$A skillfully carved stag head rides proudly on the top of the stone block.
Engraved below is the scene of a man with a stag's head giving many people
some type of drink.$d$),
  (411, 34, ARRAY['carving', 'carvings']::text[], $d$Well, which one do you want to look at -- the one on the stag-topped
or the one on the pole-topped?$d$),
  (411, 34, ARRAY['stag', 'stag-head']::text[], $d$Wide antlers grant the stag an air of majesty. You count seven tines on
each side of the mighty rack. Black onyx has been inlaid as eyes, granting
it a glittering stare that is incredibly life-like seen from this angle.$d$),
  (411, 34, ARRAY['pole', 'post', 'spike']::text[], $d$The pole is gaily colored with stones of red and green spiralling down its
sides. Ribbons attached to its top flap in the easterly breeze that slips
through the trees.$d$),
  (411, 36, ARRAY['tree', 'trees', 'branches', 'branch']::text[], $d$It's odd that these trees have spread their branches INTO the wind instead
of away from it.$d$),
  (411, 38, ARRAY['man', 'smiling-man']::text[], $d$Clad in loose flowing robes, holding a bladed weapon in one hand, and a
cup in the other, he makes an unusual figure.$d$),
  (411, 38, ARRAY['woman', 'young-woman', 'recumbant-woman']::text[], $d$A sleeping young woman pillows her head on top of one arm with the other
resting on her stomach. Her garment is shown draping closely about her
in a series of folds as though it had twisted tight in some spiralling
movement. A twining circlet of boughs graces her head even in sleep.$d$),
  (411, 38, ARRAY['woman-topped']::text[], $d$A deep engraving shows a young woman collapsed beneath a pole or post.
Several other young women stand nearby, hanging onto ropes that run
to the top of the pole with one hand and cups with the other. All are
gaily dressed with crowns of greenery in their hair.$d$),
  (411, 38, ARRAY['man-topped']::text[], $d$The smiling man stands behind a young woman resting on a large stone.
In one hand, he holds a long knife or a short sword. It's hard to tell.
Seagulls fill the sky behind him.$d$),
  (411, 38, ARRAY['monoliths', 'monolith']::text[], $d$Well, which one do you want to look at -- the man-topped or the
woman-topped?$d$),
  (411, 38, ARRAY['carving', 'carvings']::text[], $d$Well, which one do you want to look at -- the ones on the man-topped
or the ones on the woman-topped?$d$),
  (411, 42, ARRAY['letters', 'inscribed', 'inscription']::text[], $d$An inscription almost hidden behind grass reads:

     "Through the pain of One, Wishes granted to All"$d$),
  (411, 42, ARRAY['carving', 'carvings']::text[], $d$Well, which ones do you want to look at -- the ones on the dagger-topped
or the ones on the circlet-topped?$d$),
  (411, 42, ARRAY['monoliths', 'monolith']::text[], $d$Well, which one do you want to look at -- the dagger-topped or the
circlet-topped?$d$),
  (411, 42, ARRAY['circlet-topped', 'vine-topped']::text[], $d$An amazingly detailed circlet carved to look like hemlock tops this stone.
Its message of death seems to be carried out below in the scene of final
preparations for a ritual sacrifice. Several smiling young men and women
are tying another young woman to an altar stone of some kind with vines
woven of hemlock twigs. A larger crowd looks on, smiling, and raises cups
in a silent toast.$d$),
  (411, 42, ARRAY['dagger-topped']::text[], $d$The dagger-crowned monolith shows a macabre scene of celebration. A group
of happy revellers looks on as a young man in ornate robes carefully carves
the symbol of twined vines into the stomach of a young woman. Tears of pain
roll from her eyes and fall to the ground into a patch of flowers. A line of
letters is inscribed at the base of the monolith.$d$),
  (411, 44, ARRAY['rowan', 'rowan-tree']::text[], $d$This tough tree, bane of witches, is having a very difficult time in
this grove. The tree huddles among its fellows. It almost looks lonely
-- standing, not touching the others -- almost... like an unwanted party
guest.$d$),
  (411, 45, ARRAY['center', 'middle']::text[], $d$The middle of the stand of trees is scarred by a long-ago fire. Any tree
that grew too closely must have been totally consumed.$d$),
  (411, 46, ARRAY['ledge']::text[], $d$The ledge is covered in a mat of moss, but you can still make out where
someone tried to carve something into the stone.$d$),
  (411, 46, ARRAY['carved', 'carving', 'scratch', 'stone']::text[], $d$Crudely scratched into the rock is a single word:  Friends
Below it is the rough drawing of a hemlock leaf.$d$),
  (411, 47, ARRAY['patch', 'thick-patch']::text[], $d$As you examine the patch more closely, you notice that it conceals a
steep pathway leading downwards to a small ledge.$d$),
  (411, 48, ARRAY['grasses', 'clumps', 'grass', 'clump']::text[], $d$The grass is a tough variety with wiry blades. It has been ripped from between
the stones of the plaza ahead of you to the north and tossed carelessly here.$d$),
  (411, 49, ARRAY['woman', 'young-woman', 'enchanting', 'enchanting-woman']::text[], $d$Long tresses wind around her body, hiding her bare torso from view. She
glances at you sidelong from sparkling, sea-green cabochon eyes. A faint
smile twists her mouth up at the corners. Her finely webbed hands beckon
to you. The tiny scales that cover her body are exquisitely carved. Wait
a minute! Webbed hands? Scales?$d$),
  (411, 49, ARRAY['leaves', 'leaf', 'broad', 'flat', 'broad-flat-leaves']::text[], $d$On closer examination, you realize these are the same type of seaweed you've
seen washed up on the shore, but twisted together with boughs of hemlock.$d$),
  (411, 49, ARRAY['vine', 'vines', 'weed', 'weeds', 'mass']::text[], $d$The broad, flat leaves look like no plant you've ever seen, but do
seem familiar.$d$),
  (411, 49, ARRAY['inscription', 'chiselled']::text[], $d$  Selfless loss,
   Hemlock to adorn,
    New life from death,
     Through one scorned.$d$),
  (411, 49, ARRAY['carving', 'carvings']::text[], $d$Well, which ones do you want to look at -- the ones on the vine-topped
or the ones on the woman-topped?$d$),
  (411, 49, ARRAY['monoliths', 'monolith']::text[], $d$Well, which one do you want to look at -- the vine-topped
or the woman-topped?$d$),
  (411, 49, ARRAY['woman-topped']::text[], $d$The enchanting young woman teasingly beckons to you from her perch high
above. Carved below, is a picture of her swimming away into the ocean.
She looks very happy. Weeds trail behind her in the water. An inscription
has been chiselled into the base.$d$),
  (411, 49, ARRAY['vine-topped', 'weed-topped']::text[], $d$A bundle of weeds or vines drapes the top of the stone. In the carving
below, a group of people are wrapping the same type of weed around the
body of a young woman lying on a cliff near the sea.$d$),
  (411, 50, ARRAY['grasses', 'clumps', 'grass-clumps', 'clump']::text[], $d$The grass is a tough variety with wiry blades. It has been ripped from between
the stones of the plaza ahead of you to the north and tossed carelessly here.$d$),
  (411, 53, ARRAY['tree', 'tiny-tree', 'hemlock', 'hemlock-tree']::text[], $d$The tree has sent firm roots deep into the ledge. It leans outward, away
from the cliff as if embracing the east wind. The leaves rustle and glisten.
Moisture drips from them like tears.$d$),
  (411, 53, ARRAY['behind-tree', 'behind-hemlock', 'behind-hemlock-tree', 'behind-tiny', 'behind']::text[], $d$Someone took much time and effort to lovingly chisel the face of the cliff.
The carving shows a young girl and a large, strange looking woman sitting
on the seashore together. The woman is giving the girl a hemlock bough.
Words are carved below the picture.$d$),
  (411, 53, ARRAY['words', 'word', 'below', 'below-picture']::text[], $d$          Kindred souls,
          Love the Sea,
          One wish only,
          Grant to me$d$),
  (411, 55, ARRAY['stone', 'flint', 'gray-flint']::text[], $d$The pieces have been carefully chosen and matched for color, then inlaid
to form a wave pattern similar to what you see in the seas below this
headland.$d$),
  (411, 56, ARRAY['patterns', 'pattern', 'inlay', 'inlaid', 'inlaid-stone']::text[], $d$The detailed melding of the two patterns is flawless. You find it hard
to trace the exact point where they merge, but the final product, in
the precise center, is exquisite -- a twined wreath of hemlock leaves
wrapped in waves from the sea in the never-ending caress found only
in the perfection of a circle.$d$),
  (411, 57, ARRAY['leaf', 'pattern']::text[], $d$Delicate veins have been inlaid into each leaf with contrasting gray stone.
The effect is incredible. It is though you stand on a tree top.$d$),
  (411, 60, ARRAY['mist', 'mists', 'white-mist']::text[], $d$The mists roil and swirl, churned by something inside that you cannot
see... Thin tendrils reach out towards where you stand...$d$),
  (411, 62, ARRAY['stone', 'block', 'block-of-stone', 'square-stone']::text[], $d$The stone is very solid and has been covered with relief carvings on its
side and cap. The grassy growth surrounding its base shows that it has been
here for several years at the very least. An inscription stands out at the
head.$d$),
  (411, 62, ARRAY['relief', 'relief-carving', 'side', 'sides', 'leaves', 'leaf', 'twining-leaves']::text[], $d$Hemlock and rowan twist and turn around each other in an unending dance around
the sides of the stone.$d$),
  (411, 62, ARRAY['rope', 'ropes']::text[], $d$The slender ropes were twisted together from a combination of hemlock and
rowan twigs. They are rough, but very strong.$d$),
  (411, 62, ARRAY['inscription', 'head']::text[], $d$Exhaustion shows the worthy soul
Sea's love and wishes
Hemlock and Rowan gambol

Honor, Scorn, Transform!$d$),
  (411, 63, ARRAY['rowan']::text[], $d$The rowan pieces, while fresh, are bone-dry. They even seem to have absorbed
water from around themselves.$d$),
  (411, 64, ARRAY['sapling', 'saplings', 'trees', 'tree']::text[], $d$The three rowan saplings are completely dry, as though the sea mists
cannot touch them at all. The grasses all around them are wet. How odd.$d$),
  (411, 70, ARRAY['figure', 'man-like', 'man-like-figure']::text[], $d$While being man-shaped, the figure is sexless. It stretches one hand
towards a dancer collapsed among the others. A nearby dancer hides
a dagger behind his back and is shown creeping up on the fallen one.$d$),
  (411, 70, ARRAY['cauldron']::text[], $d$The cauldron is huge and iron. Its bottom glows with the heat of the fire.
Inside, a delicious smelling concoction bubbles and splats.$d$),
  (411, 71, ARRAY['carving', 'carvings', 'carved']::text[], $d$Do you want to look at the pole, the lesser pole, the image, or
the figure?$d$),
  (411, 71, ARRAY['image']::text[], $d$A huge man-like figure cradles the tiny body of a young woman in its
arms. It seems very protective. The young woman appears to be unconscious.
Her delicately webbed hand hangs down past the figure's grasp. The sea
laps about its huge lower end.$d$),
  (411, 71, ARRAY['figure', 'man-like']::text[], $d$The figure is vaguely man-shaped, but sexless. Two dark eyes stare past
you almost sightlessly. A wreath of hemlock adorns its head.$d$),
  (411, 71, ARRAY['pole', 'post']::text[], $d$The large center post rises twelve feet into the air. Carved from the trunk
of a single rowan, it is now wound about with ribbons of green and red. From
its top, multicolored ribbons explode downwards in cascades to the dancers
who grip them as they weave their pattern between the lesser poles.$d$),
  (411, 71, ARRAY['lesser']::text[], $d$The smaller poles are barely three feet high. They, too have been wound
from top to bottom in bright green and red ribbons. Baskets made of hemlock
rest on them and have been filled with fish and seaweed.$d$),
  (411, 74, ARRAY['wall', 'scars', 'scarred', 'scarred-wall']::text[], $d$It looks like something is trying to widen the tunnel or, maybe, add a
new branch to it.$d$),
  (411, 75, ARRAY['puddle', 'damp', 'small-puddle']::text[], $d$The foul liquid feels slippery and smells very similar to ammonia. It's
too dark here to detect color, but you have your suspicions.$d$),
  (411, 77, ARRAY['branches', 'upper', 'upper-branches', 'glow', 'green', 'green-glow']::text[], $d$The branches seem to be covered with a luminescent fungus of some type.
It crumples beneath your fingers as you touch it, releasing a scent that
reminds you of dried seaweed.$d$),
  (411, 90, ARRAY['mist', 'mists']::text[], $d$The white mists close in on you from all directions, swathing you in
a cool blanket. An overwhelming sense of sadness and wrongness makes
you choke back tears.$d$),
  (411, 91, ARRAY['mist', 'mists']::text[], $d$The white mists close in on you from all directions, swathing you in
a cool blanket. An overwhelming sense of sadness and wrongness makes
you choke back tears.$d$),
  (411, 92, ARRAY['mist', 'mists']::text[], $d$The white mists close in on you from all directions, swathing you in
a cool blanket. An overwhelming sense of sadness and wrongness makes
you choke back tears.$d$),
