you choke back tears.$d$),
  (411, 103, ARRAY['grass', 'bundles', 'bundles-of-grass', 'grass-bundles']::text[], $d$The fresh grasses smell strongly of the ocean. What an aromatic bed!
Hemlock leaves have been woven into the grasses, providing an extra tang.$d$),
  (411, 103, ARRAY['red', 'substance', 'red-substance']::text[], $d$Old, dried blood is solidly caked into the inscription. It's glowing
with a malevolent light.$d$),
  (411, 103, ARRAY['inscription', 'inscribed', 'words']::text[], $d$One wish only asked of thee!
One wish only granted me!
Malicious watcher, cursed be!
No more wishes granted to THEE!

Foul Rowan by Hemlock cleansed,
Ocean's breath sent to avenge,
Sea's rage never bends!
To this madness, bring an end!$d$),
  (411, 105, ARRAY['mist', 'mists']::text[], $d$The white mist almost seems to have a life of its own, running cool tendrils
through your hair and down your spine... haunting you with its touch like a
ghostly lover's cold caress.$d$),
  (411, 105, ARRAY['wave', 'waves']::text[], $d$The miniature wavelets march southward steadily. Any sound of their
minor collision with shore drowned totally by the malevolent mists.$d$),
