  (411, 117, ARRAY['crab', 'crabs', 'tiny', 'tiny-crabs']::text[], $d$The miniature crabs dash sideways between the pools in an effort to
get out of your path.$d$),
  (411, 117, ARRAY['pool', 'pools']::text[], $d$The small tidal pools are full of life. They must be recharged on a regular
basis.$d$),
  (411, 118, ARRAY['pool', 'pools']::text[], $d$The small tidal pools are full of life. They must be recharged on a regular
