  (411, 121, ARRAY['seaweed', 'mat', 'mat-of-seaweed']::text[], $d$Someone has carefully arranged the seaweed here to conceal a tiny opening
in the face of the cliff.$d$),
  (411, 122, ARRAY['mist', 'mists']::text[], $d$The white mist almost seems to have a life of its own, running cool tendrils
through your hair and down your spine... haunting you with its touch like a
ghostly lover's cold caress.$d$),
  (411, 122, ARRAY['wave', 'waves']::text[], $d$The miniature wavelets march southward steadily. Any sound of their
minor collision with shore drowned totally by the malevolent mists.$d$),
  (411, 123, ARRAY['hands', 'hand']::text[], $d$The webbing between her fingers seems longer than most people would consider
to be normal. It begins to crumble into dust as you look!$d$),
  (411, 123, ARRAY['body']::text[], $d$The woman is dressed in a flowing white robe that has had the front slit
open. Across her belly, someone has carved a circle with multiple lines that
weave in and out around each other. She must have fallen here from the top
of the cliff. A fresh wreath of hemlock and rowan still sits upon her head.
Something seems odd about her hands.$d$),
  (411, 123, ARRAY['mist', 'mists']::text[], $d$The white mist almost seems to have a life of its own, running cool tendrils
through your hair and down your spine... haunting you with its touch like a
ghostly lover's cold caress.$d$),
