ghostly lover's cold caress.$d$),
  (411, 129, ARRAY['wave', 'waves']::text[], $d$The miniature wavelets march southward steadily. Any sound of their
minor collision with shore drowned totally by the malevolent mists.$d$),
  (411, 134, ARRAY['altar']::text[], $d$The simple stone altar holds a hand-woven figure of hemlock, the carved figure
of a fish, and one small hemlock branch.$d$),
  (411, 134, ARRAY['bottles', 'vials', 'bottles-and-vials']::text[], $d$Dark amber fluid lies thickly in the bottles and vials. It looks like a stock
of one substance, just packaged differently.$d$),
  (411, 134, ARRAY['mound', 'seaweed', 'seaweed-mound']::text[], $d$The seaweed smells of fresh ocean waves and salt air. It has been mounded
to receive a humanoid body very comfortably.$d$),
  (411, 141, ARRAY['bubble', 'air-bubble']::text[], $d$The bubble shimmers slightly as it bobs about in the ocean current.
Thin, yet... it doesn't seem to be subject to the bursting wimsies of
its lesser cousins. You hope.$d$),
  (430, 7, ARRAY['boot']::text[], $d$The boot simply seems to be protruding from the tree's bark. Upon
closer inspection, you note -- quite to your horror -- that the owner
is still wearing it.$d$),
  (430, 7, ARRAY['carving']::text[], $d$The carving in the tree reads:
"Tear drops on the sweet Kiwanis of this sunset..."$d$),
  (430, 40, ARRAY['outline']::text[], $d$You clear a path around the object with your hands as to get a
better look. To your surprise, the outline is that of a humanoid face
made of living stone. The sightless eyes of this being open and with
the sound of stone grinding, it gives you its message:
        Keep your guard for those who the Magic has set free.
        Though my Master is strong, I still can advise thee.
        Stay away from that which is warned ahead...
        Seblan the Young's redemptive light shall shed
        The illusion of safety which extolls Death's fee.
        Speed to your cause now...please, hurry!$d$),
  (430, 47, ARRAY['mirror']::text[], $d$You look into the mirror and fix your hair -- what a mess! Giving a
couple variations of your charming smile, you study the reflective
surface. Slowly, an image forms of a blue robed man and a giant red
entity situated before the remains of a magical frame. Although you can
not hear what is being said, you can discern that the man is quite
agitated and perhaps even a bit scared. The magical being, on the other
hand, flairs occasionally in what you interpret to be stages of rage.
It is clear that this poor human is on the losing end of this argument.
Tendrils of energy slowly twine and merge into a giant whip-like form
over the magical being. Then the band of energy flicks the charged air
and ... the image vanishes, only to reflect the confusion in your eyes.$d$),
  (430, 86, ARRAY['words', 'bright', 'orange']::text[], $d$The bright orange words read:
      Beware you to which the Magic calls,
      From colder realms within these halls,
      A twist of fate, the priceless slip,
      With this direction, tighten your grip.
      For null ends lure the ignorant soul,
      Thy life to be reaped as an evil goal.$d$),
  (430, 88, ARRAY['words']::text[], $d$The bright orange words read:
       Though righter words were never spoken,
     To aid thy cause, journey left not token...
     What is right is wrong in the major scheme,
       Bound to conjure up the demon's scream.
    The flair of darkness bright my soul behold,
     Just as previous regions labeled as cold...
         Heed the words of my maudlin soul,
         Free my spirit and reach thy goal!$d$),
  (430, 120, ARRAY['carvings', 'marble', 'runes', 'history']::text[], $d$The smooth, black marble walls of this chamber have several carvings on their
surface, apparently images outlining historical events.  Starting from the
center of the northern wall, the story unravels in a spiralling layout.  It
originates with what appears to be a group of sorcerers seating in a
semi-circle of thrones.  While thirteen sit attentive to an apparent leader,
another eleven appear to have their heads turned away.  The next scene depicts
the same groups, but now a symbol has been placed between them.  The dividing
rune looks spherical from its representation and appears to emit some form of
energy from which the sorcerers shield themselves.  The next image shows a
large, tentacled form with various magical script around it.  Smaller forms
cluster around the base of this dominant figure, lines streaking from their
forms indicating some sort of motion.  The next carving illustrates a magical
battle of epic proportions.  You can recognize the depictions of various spells
and techniques as the previously divided sorcerers unite to fight the new
threat.  The final image consists of an entire wall of ancient script with the
following words at the base:.

                      Nogatotum Guardia Cyprianum
$d$),
  (430, 123, ARRAY['words', 'red', 'fire', 'message']::text[], $d$The red words of fire read:
      Perhaps the last but not the last
      This riddle is meant to aid you.
      Take one step back along this path;
      Yet no steps beyond the two.
      Choose your direction wise of mind.
      Pray to your deity, good fortune you'll find.$d$),
  (430, 128, ARRAY['burn', 'mark', 'wall']::text[], $d$The marble is scorched here in a peculiar pattern, almost the
shape of a human body.$d$),
  (430, 128, ARRAY['sign']::text[], $d$The sign reads:
      Heed the warnings of a tormented soul trying to redeem himself.$d$),
  (430, 172, ARRAY['sign']::text[], $d$The sign reads:
      Right becoming left and left not quite right,
      Beware the southern passage and avoid this plight.$d$),
  (430, 186, ARRAY['hand', 'imprint', 'message']::text[], $d$   A blue imprint of a human hand has been made against the southern wall.
Upon closer inspection, you see the following words scratched into the palm:
Redemption bears this peaceful color.$d$),
  (430, 199, ARRAY['dark', 'fire']::text[], $d$The words composed of the dark fire read:
      Though set in cause were Seblan and his order,
      Our task, as opposed, came to bear anew.
      Racing to the Tower of Voliangloch,
      Our plot of disruptive Magic slowly grew.
      As the Gateway churned, screaming for release,
      The Great Voliangloch did unify our hate.
      Giant bolt made of maliciously azure fire,
      Would be the end of Seblan and this debate.$d$),
  (430, 199, ARRAY['smoke']::text[], $d$The words composed of smoke read:
      Brooding on the boundaries of Mayhem
      My thoughts made dull through the eons
      A spark of Magic did awaken my sense
      Ah, these ignorant, little peons!
      My form in flight towards the light,
      My goal the freedom of yesterday...
      I breached the barrier upon pinpoint made,
      Smashing all wards keeping me from play.
      Summoning my children through the rift,
      A tendril's worth of reality in my grip...
      I restored my order of timeless reign,
      And from the zealous mortals, life did slip.$d$),
  (430, 200, ARRAY['ice']::text[], $d$The words composed of ice read:
      From the mouth of our liege ran the wondrous words:
      The Language of Magic, leaping from tongue.
      Mighty Gateway reopened and bounds revised,
      To other planes called Seblan the Young.
      Stirrings of power, then the Great Crash...
      Thrown into disorder, the order was crushed,
      The Gateway shattered, screaming Demise.
      Cyprianum, a product of Magic trusted;
      Yet, twisted into another plane...
      As dark minions overcame the powerful defenses
      Our order's souls were easily slain.$d$),
  (430, 200, ARRAY['fire']::text[], $d$The words made of fire read:
      With time laid bare in that crucial moment,
      The neutral robes retreated to S'ien Tower.
      Gateway composed and strength combined
      With force magnified by each present power,
      The spell began of noble intent,
      Though its result we have come to resent;
      Yet, of the darkness, all were prepared,
      Their might too was also shared.
      The clash of the forces, a massive War,
      Wards of the Gateway, smashing the core...
      The magic did leap and do its Master's bidding;
      Yet, no one now knew which Master was fitting.
      From the darkness of fire emerged a darker being,
      Cyprianum, the Entity of Reaping.$d$),
  (430, 222, ARRAY['foreign', 'script', 'lines']::text[], $d$The script reads:
      Nogatotum verim cantra fulfir. Moodrem separul nogatoshis.$d$),
  (430, 237, ARRAY['door', 'spidery', 'words', 'magic']::text[], $d$The spidery words unravel to transport their message:
      Cast for the subversion of strife,
      The spell let its spiral fly free.
      Amidst the chaos of runes bright...
      Evil minions cackled with glee.
      No more the master, now the slave,
      Young Seblan fell into said state.
      No longer a fool, yet not improved,
      Maudlin soul forever behind this gate.$d$),
  (462, 17, ARRAY['symbols']::text[], $d$The hides aren't decorated with paint, but rather blood.  The symbols bear a
striking resemblance to those used by the dark cultists near Fangorn Forest and
the Cultists of Zzur in Split Skull.  They are most definitely demonic in
nature.$d$),
  (462, 17, ARRAY['hides']::text[], $d$Looking closer, you realize these skins are definitely not from animals.
Judging by the chunks of corpses left behind, these belonged to people the
gnolls hunted down.  Each one is covered with a variety of symbols.$d$),
  (462, 18, ARRAY['symbols']::text[], $d$The hides aren't decorated with paint, but rather blood.  The symbols bear a
striking resemblance to those used by the dark cultists near Fangorn Forest and
the Cultists of Zzur in Split Skull.  They are most definitely demonic in
nature.$d$),
  (462, 18, ARRAY['hides']::text[], $d$Looking closer, you realize these skins are definitely not from animals.
Judging by the chunks of corpses left behind, these belonged to people the
gnolls hunted down.  Each one is covered with a variety of symbols.$d$),
  (462, 21, ARRAY['symbols']::text[], $d$The hides aren't decorated with paint, but rather blood.  The symbols bear a
striking resemblance to those used by the dark cultists near Fangorn Forest and
the Cultists of Zzur in Split Skull.  They are most definitely demonic in
nature.$d$),
  (462, 21, ARRAY['hides']::text[], $d$Looking closer, you realize these skins are definitely not from animals.
Judging by the chunks of corpses left behind, these belonged to people the
gnolls hunted down.  Each one is covered with a variety of symbols.$d$),
  (462, 22, ARRAY['symbols']::text[], $d$The hides aren't decorated with paint, but rather blood.  The symbols bear a
striking resemblance to those used by the dark cultists near Fangorn Forest and
the Cultists of Zzur in Split Skull.  They are most definitely demonic in
nature.$d$),
  (462, 22, ARRAY['hides']::text[], $d$Looking closer, you realize these skins are definitely not from animals.
Judging by the chunks of corpses left behind, these belonged to people the
gnolls hunted down.  Each one is covered with a variety of symbols.$d$),
  (462, 34, ARRAY['symbols']::text[], $d$The symbols represent the strong devouring the weak.  The image of a
three-tailed flail, each headed with a spiked orb, is also depicted.$d$),
  (462, 44, ARRAY['book']::text[], $d$This book is highly out of place.  Glancing through the pages, it seems to be a
spellbook of some kind, but none of the spells are combat magic.  It seems to
be mostly magic for love and romance, and possibly some poetry?  An odd trophy
for a gnoll to keep.$d$),
  (462, 44, ARRAY['troll-hide']::text[], $d$Like all the other flayed skins on display in this grisly den, this one bears a
depiction of a foe slain by a giant ax.$d$),
  (462, 44, ARRAY['skull']::text[], $d$The skull is clearly draconic.  Judging by the shape and size of the horns and
the fan-shaped bone plates on either side of the head, this was most likely a
young adult brass dragon.  A powerful foe indeed!$d$),
  (462, 52, ARRAY['bodies']::text[], $d$The three bodies appear to have been victims of a particularly brutal crushing
weapon.  Their position is unique, almost ceremonial.  It looks like there may
be a reason they're attached to this wall.$d$),
  (462, 52, ARRAY['symbol']::text[], $d$Drawn in blood is the image of a three-headed flail.  Impaled on the wall next
to the symbol are three bodies, their heads completely crushed in.$d$),
  (462, 62, ARRAY['statue', 'yeenoghu']::text[], $d$The statue shows Yeenoghu as a gaunt bipedal hyena.  The skin of the statue
remains a pale granite gray, while what would be patchy, mangy fur is colored
yellow with bile.  His large, protruding eyes are replaced with chunks of
amber.  In his right hand he wields a three-headed flail with spiked balls, his
holy symbol.$d$),
  (464, 4, ARRAY['sign', 'large']::text[], $d$                       Welcome to the Ickle Aviary


     Within these walls you shall find a brief refuge from the arctic cold so
many of us call home, a glimpse of a land and environment far to the south.
Beyond these immense portals you shall find nary a flake of snow nor crystal of
ice.  Instead you will discover lush rain forests, thick wooded land, and waves
upon a grassy sea.
     When the good lady Ariana Shelti was wooed to the north by her love she
left behind those lands of the south, and though her love was warm soon the
chill of this frosty realm did eat at her heart.  To ease the homesickness of
her native land thus the good residents of Ickle did build this sanctuary and
populate it with the colors of the birds of the south.
     The Aviary is more than merely a place to sight-see; indeed, industrious
young adventurers might find glory and honor to be won, and perhaps the dark
hearts of those more bent from light and happiness might feel some of the
weight lifted from their burden.$d$),
  (464, 4, ARRAY['gates', 'gate', 'sturdy']::text[], $d$     The gates are made of thick, burnished brass that the weather and time
have etched black in places.  Standing perhaps ten feet high and each hinged
door just under half that wide, the gates must weigh tons.  From the moisture
condensing on their surface and the warmth of the metal, the doors must contain
an atmosphere more suited to the tropics than the arctic city of Ickle.$d$),
  (464, 5, ARRAY['bench']::text[], $d$     Long, unending winter storms have bleached away the paint that once made
this bench stand out against the cold white all around you.  The wooden planks
are pitted and worn but stable enough to still give the weary traveler a brief
reprieve from the wanderlust that wears his or her boots thin.$d$),
  (464, 5, ARRAY['vines']::text[], $d$     The cold chill of the arctic has made everything within sight an almost
universal, blinding white.  Yet here are vines perhaps more suited to the
southern environs, creepers whose tendrils have etched their way into the very
stone of the wall.  Though they are brown, brittle, and withered, at one point
surely they had some form of nourishment and warmth to have spread so
completely over the eastern wall.$d$),
  (464, 21, ARRAY['hatch', 'door']::text[], $d$     The hatch appears to have been carved so as to appear part of the paving
stones at your feet, blending almost perfectly into the ground.  In fact, you
were rather lucky to find it at all, and it takes a few minutes of study to
discover the mechanism that opens it.$d$),
  (464, 36, ARRAY['eucalyptus-tree', 'tree', 'eucalyptus']::text[], $d$     The large tree before you towers above the others of the forest, its limbs
nearly tickling the shimmering magical boundary high above that keeps out the
chill arctic sky.  Only the touch of the gods - or likely that of the goddess
Selina - could create such a magnificent creature.  Indeed, a creature, as the
life force flowing from the tree is more than that of a mere plant.
     Birdsong fills the woods around you, a symphony only such creatures could
manage, but there is one voice that stands out above the rest, a solo amongst
the magnificent chorus.  Squinting up into the branches in search of the lovely
creature who must create this song, you can see only what might be a large nest
nestled in some of the uppermost branches.
     Though most of the branches spread over the sky far above you, there seem
to be enough placed about the lower portions of the trunk to support a climb
should you choose to investigate the upper extremities of the eucalyptus.$d$),
  (464, 39, ARRAY['rainbow', 'arc']::text[], $d$     Rainbows are actually not arcs at all but rather full circles that light
the sky with the illumination of the sun on a misty day.  Looking up at the
small portion of this rainbow that is visible from the ground you are reminded
of nursery school and names like Roy G. Biv, of mixing colors of paint and
wondering how yellow and blue made green.  Yet with light the combinations are
different, the primaries being red, green, and blue, their hues blurring
between the stripes of the rainbow to create the many colors visible as water
bends light.$d$),
  (464, 49, ARRAY['telescope', 'small']::text[], $d$     Though the telescope is nothing near what it would take to spy out the
details of the moon or the heavens above, it does have the look of craftmanship
about it.  The main tube is long and worked of a seamless cylinder of matte
black metal ringed with gold at the ends.  A small dial acts as a vernier of
sorts to focus the optics, and the pivot the scope stands attached to moves
smoothly and noiselessly.  Peering through the lens you can make out all manner
of birds throughout the aviary, all oblivious to your spying.  In particular,
the large marble fountain to the northeast offers the most stunning views of
the birds as they frolic in the cool waters.  Looking closely, you see a large
bird looking back at you:

                               .-;
                              / /  ___,
                             | | .'.---'
                             ;  : /
                            ._\ '|
                          ./     -.
                         /     .-. \:_
                        /     ( * )`; \
                        |  **  ^-^ <__ |
                        / ****     \_,\|
                        |  **      (   '
                       /            \$d$),
  (464, 50, ARRAY['hatch', 'door']::text[], $d$     The hatch is slightly rusted from the continual moisture assaulting it
from both sides but seems to be holding up quite well, all things considered.
Though it is rather massive, made of solid metal on this side and encrusted
with a slab of marble on the other, whatever mechanism operates it allows it to
swing open and shut with hardly any effort.$d$),
  (464, 55, ARRAY['pipe', 'large']::text[], $d$     Laying your hand tentatively against the pipe that is about as thick about
as your waist, you are startled to discover it cool, nearly cold to the touch.
Beads of water condense from the steam all along its surface, and you can feel
the gurgle of water passing through the pipe down into the earth.  A similar
pipe emerges from the earth behind the boiler, out of reach, surely filled with
steam scaldingly heated by the furious earth far below.$d$),
  (472, 200, ARRAY['hedges', 'hedge']::text[], $d$Standing high above you these hedges block all sunlight from sight.  Your
light source is the only illumination.  Glancing about in your frenzy, you
spot a small branch poking out from one of the hedges.$d$),
  (472, 200, ARRAY['branch']::text[], $d$You grab ahold of the branch and tug on it.  A small tuft of foliage falls
out of place to reveal what looks to be a door hidden behind the hedges.
Upon examination of the door you notice it has no keyholes.  Instead it
has a small indenture below the handle in the shape of a ring.$d$),
  (472, 201, ARRAY['wooden', 'floor']::text[], $d$Brushing the dust aside, you notice one of the floorboards is loose.
$d$),
  (476, 9, ARRAY['inscription', 'wall', 'stone', 'writing']::text[], $d$The inscription is really nothing more than a few words carved onto the
wall of this tunnel. The inscription reads:

Whatever the outcome, may the world never forget our deeds.$d$),
  (476, 38, ARRAY['inscription', 'mound']::text[], $d$The inscription reads:

The legendary Somar fell here to while defending his comrades. He will
be remembered as an honorable and fearsome warrior.$d$),
  (476, 49, ARRAY['message', 'writing', 'inscription', 'stone', 'walls', 'wall', 'memorial']::text[], $d$The message has been chipped and carved into the stone by a sharp object.
The writing is difficult to read but after puzzling over the script for
several minutes you are able to decipher it. It reads:

On the Eve of a great battle, we wish to make it known those that follow
that a mighty warrior, the legendary Kara-Sithri, fell not far from here
while defending her comrades against the traitorous Padraeg. Her selfless
sacrifice spared the lives of many warriors and we will not allow her to
be forgotten. The murderous Padraeg was imprisoned within living stone by
mighty magic and Kara-Sithri's sacred remains placed beyond it.$d$),
  (476, 51, ARRAY['bones', 'bone', 'path']::text[], $d$The bones are scattered about the area; however, they are concentrated near
the north and east exits.$d$),
  (476, 52, ARRAY['bones', 'bone', 'path']::text[], $d$The bones are scattered about the area; however, they are concentrated near
the north and south exits.$d$),
  (476, 53, ARRAY['bones', 'bone', 'path']::text[], $d$The bones are scattered about the area; however, they are concentrated near
the south and west exits.$d$),
  (476, 54, ARRAY['skeleton']::text[], $d$The skeleton's skull is bashed in and his bones are scored with claw
marks.$d$),
  (476, 55, ARRAY['bones', 'bone', 'path']::text[], $d$The bones are scattered about the area; however, they are concentrated near
the north and south exits.$d$),
  (476, 56, ARRAY['bones', 'bone', 'path']::text[], $d$The bones are scattered about the area; however, they are concentrated near
the west and east exits.$d$),
  (476, 57, ARRAY['bones', 'bone', 'path']::text[], $d$The bones are scattered about the area; however, they are concentrated near
the north and south exits.$d$),
  (477, 0, ARRAY['rose', 'arctic']::text[], $d$The arctic rose, some five feet tall, has been carved into the walls
of the cavern and the indentations filled with an ice of a deeper,
purer blue.  The effect is simple but striking.  A sense of peace
and holiness floods through your body as you gaze at the rose.  You
recognize the arctic rose as the symbol of Haddixx, the arctic god.$d$),
  (477, 0, ARRAY['obelisk', 'huge']::text[], $d$This giant obelisk has been carved out of a single piece of pure
ice. It is perfectly carved, not a single chisel mark or blemish
mars its surface.  A soft bluish-white light radiates from deep
within the obelisk.$d$),
  (477, 0, ARRAY['spring', 'pool', 'water', 'pure', 'small']::text[], $d$Pure ice-cold water flows from a small spring directly under the
arctic rose.  It flows into a small pool in the center of the
ledge. A small circular wall about two feet high, formed from
bricks made of ice, contains the small pool. You consider drinking
from the pool, but realize that this water is sacred to a powerful
diety and you are not about to pollute it with your dirty lips.$d$),
  (478, 56, ARRAY['fountain']::text[], $d$The fountain was once beautifully sculpted of marble, but the devastation
which has swept through the city has left it a shattered heap. You look
for a trapdoor in the base of the fountain but are unable to find one.
You must be confusing this city with another city! <grin>$d$),
  (480, 38, ARRAY['writing', 'wall']::text[], $d$The writing reads, "Gaze upon those that have opposed me and know that I
am supreme."$d$),
  (480, 83, ARRAY['skeleton', 'man', 'adventurer']::text[], $d$The skeleton's armor is rusting and his clothes are in tatters. The man
apparently died in battle, for with one hand he grips the hilt of a rusty
broadsword. His other hand seems to be gripping some object...$d$),
  (481, 15, ARRAY['totem', 'pole', 'totem-pole']::text[], $d$This totem pole seems to be a warning of some sort. There are a number of
images engraved upon its surface but the predominant image features a
three-headed monster.$d$),
  (481, 35, ARRAY['pole', 'totem']::text[], $d$You look at the totem pole and wonder if one day your own skull will
decorate it...$d$),
  (481, 39, ARRAY['pole']::text[], $d$Sacrifices to the great beast which terrorizes the islanders are bound
here. The pole is blackened with fire and crusty with old blood.$d$),
  (481, 72, ARRAY['mural', 'wall']::text[], $d$You examine the scenes of this artwork and note that in your immediate area it
depicts a man with flaming red hair admiring a woman.  The man is pictured as
possessing a fiery aura; perhaps he is a god.$d$),
  (481, 98, ARRAY['mural', 'wall']::text[], $d$The mural shows a fire-god and a mortal woman exchanging vows of love and
fidelity.  Your heart goes out to the couple, for you know that stories of gods
and mortals falling in love always end in disaster.  An inscription written
beneath the mural reads: The Love of Vulkaer, Lord of Earthfire, for his bride
Zaira will remain true for all eternity.$d$),
  (481, 99, ARRAY['mural', 'wall']::text[], $d$The now familiar mural continues the story of Vulkaer and his mortal love.
Zaira, her hair damp with perspiration, is pictured holding aloft a newborn
child for Vulkaer to view.  The god's face radiates pride as he views his
daughter.  Beneath the infant is written a single phrase: Vulcera, born of
Vulkaer and Zaira.$d$),
  (481, 100, ARRAY['mural', 'wall']::text[], $d$The mural continues to show the god and his wife as happily married and
enjoying the company of their child.  However, looming in the background is a
shadow.  You recognize the shadow as Lokari, the God of the Moonless Night.$d$),
  (481, 101, ARRAY['mural', 'wall']::text[], $d$The mural continues the story of Vulkaer and his mortal wife.  The two of them
are pictured sleeping blissfully, while Lokari sneaks from their presence,
carrying a bundled load under his arm.  A tiny hand peeks from underneath the
bundle, and with a shock you realize that the evil god is kidnapping Vulkaer's
daughter.$d$),
  (481, 102, ARRAY['mural', 'wall']::text[], $d$As the mural continues the story, you realize that several years have passed
since the last drawing.  The mural reveals Lokari raising the stolen child as
his own, and in his own dark fashion.  One chilling scene shows Lokari and the
child eating the flesh of a man.  The victim's fleshless body lies at their
feet.  There is an inscription below the body.  It reads: It was through Lokari
that Vulcera learned the evil nature of her heart.$d$),
  (481, 103, ARRAY['mural', 'wall']::text[], $d$The mural shows Vulkaer tracking Lokari and finally expelling him from the
mortal plane with fierce magiks.  One scene shows Vulcera weeping over the loss
of the only father she has ever known while Vulkaer looks on, perplexed.$d$),
  (481, 104, ARRAY['mural', 'wall']::text[], $d$This section of the tunnel documents the many horrors that Vulcera delighted
in.  She learned these pleasures from her pseudo-father Lokari.  In the final
scene of this mural, Vulcera and Zaira are shown in a bitter argument.$d$),
  (481, 105, ARRAY['mural', 'wall']::text[], $d$You find yourself looking at the largest mural you have seen in the tunnel.
What is remarkable about the mural, however, is not its size but its detail and
artism.  The mural's artwork is clearly superior to any other artwork you have
ever seen-- perhaps it was done by a god.  The mural shows Vulcera slaying her
mother and then feeding upon Zaira's organs.  There is an inscription along the
top of the tunnel.  It reads: Know that on this day my heart died, for I lost
two who I loved dearly-- my daughter to evil, my wife to an evil heart.$d$),
  (481, 106, ARRAY['mural', 'wall']::text[], $d$The final mural in this sequence displays Vulkaer and Vulcera battling.
Vulkaer defeats his daughter and, lacking the resolve to kill the daughter he
once loved dearly, imprisons her in a mighty volcano, forbidding her to ever
leave.$d$),
  (481, 121, ARRAY['mirror', 'mirrors', 'wall']::text[], $d$  There mirrors are of varying size but they are all of the finest quality.
There are several mirrors which are set apart from the others, however,
due to their unusually large size and the odd, filmy reflection they cast.
As you peer into one of these unique mirrors you catch of faint glimpse
of some outwordly scene the flickers across the surface of the mirror like
ripples across water.
  You also notice that each of the filmy mirrors have an unusually thick
frame with a latch on one end and hinges on the others. The frame contains
a glass covering which protects the mirror from direct contact with your
skin. Now, why would anyone want to put a glass case over a mirror?$d$),
  (484, 0, ARRAY['mural', 'murals']::text[], $d$   After spending several moments admiring the quality of the work focus shifts
to discerning its meaning.  The murals along each wall are split into several
scenes, each scene continuing a common story.  If you wish to examine the
individual scenes, you must LOOK at mural1, then LOOK at mural2.$d$),
  (484, 0, ARRAY['mural1']::text[], $d$   The scene on the west wall is dominated by a simple theme: a shadowy, vague
presence stands unnoticed by other men, admiring a lovely young princess.
Beneath the figures in the first scene are names: below the shadowy presence is
the name Lokari, and below the princess is the name Irinia.$d$),
  (484, 0, ARRAY['mural2', 'south']::text[], $d$   The mural on the south wall has many of the same elements as the mural to
the west, but with a twist: the Princess is now aware that the shadow is
observing her, and is discomforted by the fact.  In the final scene, Lokari
asks the Princess to be his consort, but is refused.$d$),
  (484, 0, ARRAY['archway', 'inscription']::text[], $d$   The temple was raised to honor the gods, and the hall was raised to honor
the memory of our great Quest.  Mortar and stone may crumble to dust, but blood
and flesh will endure.  If the ages remember but one thing of our Quest, let it
be this: our resolve never wavered, for we marched on the side of what was
right and just.$d$),
  (484, 1, ARRAY['mural', 'murals', 'wall', 'walls']::text[], $d$After spending several moments admiring the quality of the work focus shifts to
discerning its meaning.  The murals along each wall are split into several
scenes, each scene continuing a common story.  If you wish to examine the
individual scenes, you must LOOK at mural1, then LOOK at mural2.$d$),
  (484, 1, ARRAY['mural2']::text[], $d$As you turn to the east, the images become dominated by Lokari.  In one scene,
the god is perched thoughtfully upon a throne that floats in an inky blackness.
Behind him stars streak across the void.  A silver radiance outlines Lokari's
head; at first glance, the radiance appears to be a holy aura, but a closer
inspection shows that the artisan has made the god's head eclipse the moon, so
that only the very edges of the lunar body show.  It is then you recognize the
name Lokari- he is the mysterious god of the Moonless Night.$d$),
  (484, 1, ARRAY['mural1']::text[], $d$Examining the west wall, you see various scenes in which the Princess rules her
land.  She is pictured as a wise and benevolent ruler.$d$),
  (484, 2, ARRAY['mural', 'murals', 'wall', 'walls']::text[], $d$After spending several moments admiring the quality of the work focus shifts to
discerning its meaning.  The murals along each wall are split into several
scenes, each scene continuing a common story.  If you wish to examine the
individual scenes, you must LOOK at mural1, then LOOK at mural2.$d$),
  (484, 2, ARRAY['mural2']::text[], $d$The mural returns to the dragon's rape of the land. In this midst of
this devastation one man stands forward and tracks the blue devil. The
man is identified as Severan. There is a heroic battle; Severan slays the
dragon, but is mauled by the beast as it flails madly about in its
death throes. Severan is carried to a local temple by his retainers,
where he is tended to by priests. When Princess Irinia hears of Severan's
mighty deed, she rushes to the Champion's side, to offer her thanks.$d$),
  (484, 2, ARRAY['mural1']::text[], $d$Along the north wall, Lokari is shown in his godly domain, furious over his
rejection by the Princess and brooding over how to win her favor.  In one
chilling scene, Lokari grins madly, as though considering some insidious plan.
The next scene shows Lokari unleashing a giant blue dragon upon the world.
The dragon wreaks havoc upon Irinia's kingdom, ravishing everything in its path.
The final scene depicts Lokari once again presenting himself to the Princess,
this time with an offer: marry him and he will cage the dragon; deny him and
the dragon will scourge the countryside and annihilate her people.$d$),
  (484, 3, ARRAY['inscription']::text[], $d$The inscription, which is part of the mural, appears to have been burned
onto the stone wall of the chamber where the Princess was abducted. It
reads:

Gaze upon those who oppose my will and enjoy their folly.
$d$),
  (484, 3, ARRAY['mural', 'murals']::text[], $d$After spending several moments admiring the quality of the work focus shifts to
discerning its meaning.  The murals along each wall are split into several
scenes, each scene continuing a common story.  If you wish to examine the
individual scenes, you must LOOK at mural1, then LOOK at mural2.$d$),
  (484, 3, ARRAY['mural2']::text[], $d$This mural is very different from the others you have seen. The angles
seem sharper, the colors less vibrant. Perhaps the artisans wished to
emphasize the shock and loss expressed by the events depicted in this
particular mural. Curious, you examine the mural in a desire to see how
the story will unfold. The first scene shows Lokari peering into a
window, watching the Princess as she and a few female companions huddle
before a fireplace. Another mural shows Lokari entering the room and making
his presence known to those inside. With a word and a gesture, he slays
the terrified handmaidens. The final scene shows the god departing the
mortal plane, forcing the Princess to accompany him. The lifeless bodies
of the handmaidens and an inscription burned upon a stone wall in
Irinia's room are all that remain behind to tell the tale of Irinia's
abduction.$d$),
  (484, 3, ARRAY['mural1']::text[], $d$The mural reveals that Severan and the Princess spend much time together as his
wounds heal.  The two fall in love and announce their plans to wed.  The entire
kingdom celebrates upon hearing the news that their beloved Princess and their
greatest Champion will be joined.  There is one figure who is not celebrating,
however.  The shadowy Lokari stands in the background of every scene, anger and
jealously blazing in his dark eyes.$d$),
  (484, 4, ARRAY['mural', 'murals', 'wall', 'walls']::text[], $d$After spending several moments admiring the quality of the work focus shifts to
discerning its meaning.  The murals along each wall are split into several
scenes, each scene continuing a common story.  If you wish to examine the
individual scenes, you must LOOK at mural1, then LOOK at mural2.$d$),
  (484, 4, ARRAY['mural2']::text[], $d$This mural is somewhat hazy.  It depicts the awesome and powerful figures of
three gods.  These gods seem to be debating.  At their feet a diminutive image
of Severan is always present, as though in his piousness he has touched their
hearts.  The gods, consequently, decide to assist Severan, and direct an avatar
down to earth.  In the final scene, Severan seems encouraged as he listens
closely to the words of the avatar.$d$),
  (484, 4, ARRAY['mural1']::text[], $d$This mural is entirely dedicated to displaying the panic, confusion,
anger and despair which followed the abduction of the Princess. In the
center of this tumult stands Severan. The Champion travels to a distant
temple high in the mountains, where he seeks consultation with the gods.
For seven days and nights he does nothing but fast, meditate, and
sacrifice to the gods.$d$),
  (484, 5, ARRAY['mural', 'murals']::text[], $d$After spending several moments admiring the quality of the work focus shifts to
discerning its meaning.  The murals along each wall are split into several
scenes, each scene continuing a common story.  If you wish to examine the
individual scenes, you must LOOK at mural1, then LOOK at mural2.$d$),
  (484, 5, ARRAY['mural1']::text[], $d$Severan returns to his people and shares with them the words of the
avatar. The people are heartened by the news, and soon a mighty army
forms. Heralds are dispatched to distant lands, and humanoids, heroes and
intelligent monsters from across the world gather under Severan's banner.
Personal allegiances are put aside; racial hatreds forgotten for the
moment, as the mighty army grows and people begin to believe they can
rescue the Princess and defeat the god.$d$),
  (484, 5, ARRAY['mural2']::text[], $d$Lokari is not idle as Severan gathers his army.  He assembles his own host and
prepares the defense of his realm.  In several images you see Princess Irinia
continuing to defy Lokari; this angers him, but he refuses to release her.$d$),
  (484, 6, ARRAY['mural', 'murals', 'wall', 'walls']::text[], $d$After spending several moments admiring the quality of the work focus shifts to
discerning its meaning.  The murals along each wall are split into several
scenes, each scene continuing a common story.  If you wish to examine the
individual scenes, you must LOOK at mural1, then LOOK at mural2.$d$),
  (484, 6, ARRAY['mural1']::text[], $d$The mural shows Severan's army growing even larger. Under Severan's
direction, the army constructs a temple at the site of his victory over the
dragon, incorporating the bones of the dragon into the foundation of the
temple. You recognize the area depicted in the mural as being the compound
you are currently exploring.$d$),
  (484, 6, ARRAY['mural2']::text[], $d$In this mural Severan and his army consult a number of oracles. The
oracles impart some vital information to the Host. Apparently as a result
of this information, Severan and several other Heroes leave the
burgeoning army and set off in different directions.$d$),
  (484, 7, ARRAY['mural', 'murals', 'wall', 'walls']::text[], $d$After spending several moments admiring the quality of the work focus shifts to
discerning its meaning.  The murals along each wall are split into several
scenes, each scene continuing a common story.  If you wish to examine the
individual scenes, you must LOOK at mural1, then LOOK at mural2.$d$),
  (484, 7, ARRAY['mural1']::text[], $d$This mural shows Severan completing several Quests by which the gods test his
worth.  Upon completing his final Quest, the three gods descend to the mortal
realm and congratulate Severan upon his successes.  Warning Severan that his
battle with Lokari will be a difficult, the gods give him their blessing.  You
recognize the god- they are Timun the Sun god, Rhalean goddess of Justice, and
Azkrael goddess of the Hunt.$d$),
  (484, 7, ARRAY['mural2']::text[], $d$This mural reveals that other Heroes Quested as well, and were just as
successful as Severan. These heroes return home in triumph, bearing objects
which they apparently won while Questing.$d$),
  (484, 8, ARRAY['mural', 'murals']::text[], $d$After spending several moments admiring the quality of the work focus shifts to
discerning its meaning.  The murals along each wall are split into several
scenes, each scene continuing a common story.  If you wish to examine the
individual scenes, you must LOOK at mural1, then LOOK at mural2.$d$),
  (484, 8, ARRAY['mural1']::text[], $d$In this mural, a great Host is seen to assemble before the Temple of the
Sun. Swords flash brightly as men raise their weapons to salute Severan.$d$),
  (484, 8, ARRAY['mural2']::text[], $d$This murals shows only the Temple of the Sun.  The ground is muddy around the
east face of the pyramid and appears heavily trodden.  You come to the
conclusion that Severan has lead his Host to war against Lokari.$d$),
  (484, 11, ARRAY['silveroak', 'oak', 'silver', 'tree']::text[], $d$The Silveroak...  Many stories have spawned of this legendary tree, but few
have had the opportunity to view one.  It is said the Silveroak was the first
tree planted upon the land by the gods after the world was created.$d$),
  (484, 16, ARRAY['inscription', 'writing', 'runes', 'block', 'granite', 'pyramid']::text[], $d$The inscription reads:

Timun, great Lord of the Sun, we dedicate this temple to your name, to
your philosophy, to your honour. We call upon you to help your loyal
followers in their hour of greatest need.
$d$),
  (484, 19, ARRAY['statue']::text[], $d$Following the statue's eyes it can be seen that he is looking up at a temple
upon the pyramid.  The statue's dress suggests that he is a mighty warrior, but
his bearing indicates that he is pious.$d$),
  (484, 19, ARRAY['fountain', 'inscription', 'base']::text[], $d$An inscription on the fountain reads:

Concept, Compound, Earth, Water and Fire -- Rhalean 1996
Air and Keep, Plus Many Ideas -- Azkrael 1996
Hard Work, Clever Coding, and Dedication -- Metamorpho 1992- present.
Editing for Reimplementation -- Kourrya, Dakhod, Laoris and Cronax 2006$d$),
  (484, 20, ARRAY['maiden', 'nikita', 'woman']::text[], $d$The woman is garbed in a wedding gown and has one hand placed protectively upon
her husband's arm, the paladin.  There is a tiny script beneath her.  It reads:
Nikita, wife of Timun, great Lord of the Sun.$d$),
  (484, 20, ARRAY['knight', 'paladin']::text[], $d$There is something unusual about the paladin in the centre of the ceiling.
His bearing and stance display absolute strength of sword and conviction.
Ancient lore claims that Timun, god of the Sun, is the patron deity of the
Paladin Guild...  Perhaps this mural was created to honour him.$d$),
  (484, 20, ARRAY['code', 'tablet', 'stone', 'writing', 'inscription']::text[], $d$The inscription reads:

The Code of the Paladin:
Know that this is the Code of the Paladin, as told by the great god Timun
to the First Paladin, Irik.
The Paladin will defend the weak against the wicked, respect the Gods
and do them honour, and willingly sacrifice his life to protect the
virtues of a maiden.$d$),
  (484, 21, ARRAY['ceiling']::text[], $d$Upon closer inspection specific constellations can be seen on the ceiling far
above!  It really is a reflection of the stars.  One constellation seems to
garner more attention than the rest....  The Paladin and his Sword.  Could
there be a connection?$d$),
  (484, 21, ARRAY['pool', 'liquid']::text[], $d$The pool seems to swirl and form vague, fleeting images.  You get the
impression of legends being made, stories being written, but it passes too fast
to catch.$d$),
  (484, 21, ARRAY['symbol', 'symbols', 'inscription', 'side', 'sides', 'word']::text[], $d$The symbols seem to reform, rearrange and sometimes reshape themselves.
Somehow, the symbols seems to form words in your mind...
I am the Star-Gazer,
Worldmaker, Walker of Storms,
I walked as Tale-Spinner,
Truthseeker, Bearer of...
The rest is lost, beyond mortal comprehension. This must belong to a
God, only they could be so arrogant.$d$),
  (484, 21, ARRAY['altar', 'alter']::text[], $d$   The altar is nothing more than a huge rectangular slab of white
marble, but it radiates light from somewhere within itself. A circular
pool filled with some sort of liquid is cut into its surface. Inscribed
on the sides are symbols which looks vaguely familiar.$d$),
  (484, 21, ARRAY['sunray', 'ray', 'light', 'sunlight']::text[], $d$Passing a hand through the light it is surprising to find resistance to
movement.  The light has the consistency of a thick soup.  The further away
from the disk, the more solid the light becomes.  Placing a hand into the light
ray as it nears the west wall the faint outline of your skeleton can be seen!
$d$),
  (484, 21, ARRAY['disk', 'emblem']::text[], $d$The disk is made of pure gold and throbs with power. It projects a ray of
light onto the west wall. The light forms into a shape which resembles a
door.$d$),
  (484, 59, ARRAY['stone-tablet', 'tablet', 'stone', 'board']::text[], $d$The tablet is written in an elegant script. It reads:

Severan's Doom was created to present a challenge to the many high level
characters in the game. It was designed for groups of 5-6 level 90+ PC's.
If you are a whiner, please proceed no further, for this area is
definitely not for you: it is dangerous. If you don't like danger, go
back to killing bunnies.

Severan's Doom was designed to be dangerous, but fair. There *are* rewards
for exploring the area, aside from the usual gold and xp. These rewards
(powerful items) were created to offset the high casualty rate. However,
these items should only be given to those players who demonstrate their
worth by exploring the area and braving the unknown. Therefore, we have
instituted the following rules:

1) under no circumstances, do not give other players a map, or verbal
   directions, to any location within this area.

2) do NOT give equipment from this area away to other people. Do NOT
   sell these items to other players. I repeat- they *must* get the items
   themselves!

3) god and immortals will not 'explore' this area while invisible. Unlike
   other MUDs, Fiery does not allow its gods/immortals to run amok over
   the MUD and discover the game's secrets the easy way.

4) ignorance of these rules is not an excuse to violate them.

Thank you for respecting these rules. To be honest, a lot of the above
rules will be hard to enforce... but we feel confident the majority of
players have the integrity to police themselves. However, if you are
caught violating the rules, Lokari himself just might summon you to
Oblivion.$d$),
  (484, 61, ARRAY['inscription', 'writing', 'bridge', 'stone']::text[], $d$
The inscription has been expertly chiseled into the stone. It reads:

Selina, Spirit of the Water, allow us safe passage over your swift
currents. Let not your raging torrents tear this bridge from its
foundation, nor wash soldiers from its surface, for we are your humble
servants, just as we are servants of all the gods.

Severan
$d$),
  (489, 1, ARRAY['gate', 'gates']::text[], $d$The gates are an indication of the keep itself-- huge, imposing,
metal-studded and metal-laced through wood so hard you can't scratch
it with anything you have. You can open these gates, you think, if you
have a lot of help. Most likely your adventure through the Keep will be
very similar.$d$),
  (489, 4, ARRAY['statue']::text[], $d$The statue is of a man in terrible agony, a little hunched over from some
great pain in his belly. He holds his arms to his stomach, as if to keep
his innards inside it. He looks upward, his mouth opened in a soundless,
eternal scream. On his forehead is written, terrible in its simplicity,

                    MEZU, THE FIRST GOD TO FALL

Those who look very closely at this statue will see the pentagram-shaped
indentation in its side.$d$),
  (489, 6, ARRAY['coffin', 'sarcophogus']::text[], $d$The coffin is made of stone. It lies at the bottom of a shallow pool of
water that just barely covers its lid.$d$),
  (489, 10, ARRAY['tapestry', 'curtain', 'velvet']::text[], $d$The velvet is woven into patterns: Suns, moons, planets, and on each
wall, a beautiful, well-muscled man in a flowing red cloak, his hands
outstretched through his private cosmos, swirls of light shooting from
his fingertips. But his eyes look very cruel. You understand at a glance
that this must depict Lokari, and you're not sure you want to see him
now.$d$),
  (489, 11, ARRAY['tapestry', 'curtain', 'velvet']::text[], $d$The velvet tapestries depict a powerful godlike man who spins planets
from thin air and sets them in motion, whirling amidst suns and stars.
The entire effect is unearthly, and intended to be so. You don't even
understand everything you see here. But when you push on one of the
tapestries, to the west, you can feel it give a little. You do notice a
tiny hole in the tapestry-- a keyhole, perhaps, but whatever key opens it
would be so thin it wouldn't resemble a key at all.$d$),
  (489, 12, ARRAY['tapestry', 'curtain']::text[], $d$The curtain reveals the back of a tapestry -- rough and nubby from
weaving. Near its edge, you detect a hole in the wall -- a very small
hole. It is decorated, making you suspect that it is supposed to be
there. But if it is a keyhole, the key must be very long and thin indeed.$d$),
  (489, 13, ARRAY['frieze', 'carved', 'wall', 'walls']::text[], $d$The friezes line the walls. They're intricate carvings of people, demons,
beasts, horrors you are convinced came out of your worst nightmares. The
carving is all the more remarkable because it's done in the deep black
wood of the rhell tree, which is almost impossible to carve well. But
then, as you look, the southern wall seems to be a little different...$d$),
  (489, 13, ARRAY['altar']::text[], $d$It is made of black marble, simple and elegant, being a simple
rectangular shape with rimmed edges. A few things are set on its
surface in what appear to be deliberate placings -- a stone knife
with a few flecks of dried blood on its edge, and an elegant silver
chalice set with gems and runes. No mortal may touch either of these;
any attempts will burn the hands badly.$d$),
  (489, 43, ARRAY['love-note', 'love', 'note']::text[], $d$You carefully unfold the aged paper, smoothing out the brittle creases.
Some of the yellowed paper splinters off in your hands, making you wince.
Your eyes scan the browned ink, but you can't read the neat, precise
handwriting's alien words.
   Finally you refold the paper and put it back under the threadbare
pillow. You straighten up, still thinking about the letter. Obviously,
someone cared enough for the contents of the letter to keep it all these
years. But who? And why?$d$),
  (489, 62, ARRAY['wall']::text[], $d$As you examine the wall, you admire its absolute blackness. You reach out
and touch it, and your hands almost sink into its colorless depths before
you touch the cold wrought iron. The iron is thorned, so you're very
careful not to prick your hands. The darkness seems to consume the entire
wall. How will you open that darkness?$d$),
  (489, 64, ARRAY['rubble']::text[], $d$The path looks like it was destroyed by a cave-in. One boulder in
particular looks pretty key. If you could just move it, you might be able
to clear the rest of the rubble.$d$),
  (489, 72, ARRAY['bars', 'iron', 'thorned', 'cell']::text[], $d$As you examine the iron bars of the cell, you notice that off to the
side, there's an ingenious lockbox hidden in the shadows of the dank
room. You examine it closer, and see that the box itself is actually a
covering for a simple lever device. The lever leads to a series of
pulleys and iron bars set against the ceiling.$d$),
  (489, 79, ARRAY['robe', 'ermine', 'hook']::text[], $d$The ankle-length robe is made of very heavy crimson velvet damask, lined
with dark-spotted white ermine fur. It looks beautiful, clean, utterly
new, and it's such a blazing contrast to the rest of its surroundings you
can't figure out how to categorize it. Why is it hanging here, as if to
underscore the misery of its surroundings?$d$),
  (489, 86, ARRAY['porphyra']::text[], $d$To say it's a large jar isn't doing it justice. It's a HUGE jar with a
pointed end. The lids are fitted on tightly, with hooks carved into the
stone of the lid itself, for hanging the entire jar up. Since there's
nothing in this jar, or its mates, there seems to be no reason to hang
them up. They look extremely sturdy. Their plainness just emphasizes their
utilitarian nature. The one you're most interested in is lying right at a
place in the wall where the mortar of the wall is partially eaten away.
The jars, being human-sized, are far too large to pick up, and your
efforts to smash them are repelled -- they're too sturdy. Perhaps you
need something magical to help you destroy them..?$d$),
  (489, 90, ARRAY['floor', 'symbol']::text[], $d$As you look at the golden plate in the floor, you realize you can't
decipher the arcane symbols carved into it. They seem to center on one
particular part of the plate. You look closely at the plate and see that
it has a hole in it! Well, at least the hole is intentional. You push at
the plate, but it clearly wants something more than just a push.$d$),
  (489, 93, ARRAY['bowl', 'fountain', 'pillar']::text[], $d$The bowl and pillar are made of matching alabaster stone, carved with ivy
leaves and polished until they both shine, reflecting the sourceless
light. When you look into the bowl, you are shocked to see scenes of all
four elemental planes: roiling water, rushing winds, licking flames, set
against dark stone.$d$),
  (490, 4, ARRAY['sign', 'signpost', 'post', 'roadsign']::text[], $d$Four wooden arrows point you in the right direction :
                        /\
                     The Beach

< The Megalyth                       Stone Arch >

                    The Village
                        \/$d$),
  (490, 89, ARRAY['murals', 'mural', 'wall', 'walls']::text[], $d$The murals tell the story of the great griffin god who the cult worship.
He seems to have arrived on the island one day after a tour of the universe
and decreed this island to be the only place fit for his creatures to live.
He created the cave and its altar and killed all the people living on the
island who did not accept his authority. The story seems to take place before
even the druids were here, or perhaps the painter felt it diplomatic not to
paint his master's undefeated enemies.$d$),
  (490, 90, ARRAY['mural', 'murals', 'wall', 'walls']::text[], $d$This mural seems more fanciful, as if it tells of the future not the past.
Dagon is represented as rising from the altar to destroy his enemies, among
whom you can clearly see Earle suffering. Behind Dagon is the shadow of an
even larger griffin which seems to be scorching everything it touches. Perhaps
it is just that the painter has a bad sense of perspective.$d$),
  (490, 185, ARRAY['glint', 'mirror']::text[], $d$A horrendous monster raises its fist to attack you!
Aw no, hold it, it's just your mirror image.$d$),
  (492, 18, ARRAY['blood']::text[], $d$   Ordinary enough to see blood, perhaps from pray.  Alas not much life is seen
within a wasteland.  The blood is rich red, and taints the sand as it grows
large in small puddles downward.  It looks to be a recent kill.$d$),
  (492, 18, ARRAY['skeleton', 'corpse', 'bones']::text[], $d$   Few of the bones are still intact, one of the femurs has been completely
shattered though.  Some of the rib cage has been buried under the sand.  The
structure is to large to be of human origin.  Perhaps it may have been an orge,
or a large barbarian.  Be it whatever the case, some strong must brought it
down.$d$),
  (492, 20, ARRAY['puddles', 'puddle', 'blood']::text[], $d$   Four small puddles of blood stand without doubt of certainty.  They appear
to be but an inch or so deep.  The blood must be fresh, because of its richness
of color and smell.$d$),
  (492, 21, ARRAY['blood', 'streaks', 'streak']::text[], $d$   About three deeply red lines streak downward, painting the ground beneath.
Leaving much to the imagination as the its path or the owners demise.$d$),
  (492, 22, ARRAY['blood']::text[], $d$   The same as before, rich dark red, just ozing from its owner.  Wherever they
may be.  The blood runs eastward, getting larger in amounts the further it
trails on.$d$),
  (492, 23, ARRAY['blood']::text[], $d$   The blood of innocent or damned?  Nonetheless, the pain or satisfaction of
such a site remains forward north.$d$),
  (492, 33, ARRAY['flesh', 'bone', 'fragments', 'bits', 'fragment', 'bit']::text[], $d$   Becomming of the unknown, there is no possible way to see what the slivers
of bone could have came from.  The pieces of flesh are few and very small, all
are greenish brown and appear to be decomposing.  Most of the flesh and bones
trail around the mysterious holes in the plateaus.$d$),
  (492, 33, ARRAY['holes', 'hole', 'pit', 'pits']::text[], $d$   No larger then two feet wide, they rest at the base of the mounds, moving
downward.  They appear to be deep, but there is not a way any normal size gnome
could even fit down there.$d$),
  (495, 4, ARRAY['shield', 'swords']::text[], $d$   Beautifully crafted these masses of blades and thick shields appear to
finely forged, yet it does not look that even one of them hasn't seen battle.
$d$),
  (495, 4, ARRAY['counter', 'knobs', 'engravings']::text[], $d$   This is a fine table indeed, wonderfully crafted from a strange wood.  It
appears to have been made from one piece of wood, as there isn't one nail or
separate piece noticeable.$d$),
  (495, 5, ARRAY['footprints', 'prints', 'tracks']::text[], $d$   About three inches in width and nine in length, the prints are rather large
but the winds have worn away their define.  But whatever the creature, it seems
to be large because of their depth into the stale sands.$d$),
  (495, 11, ARRAY['table']::text[], $d$   The table is beautifully crafted out of a very dark wood and uniquely
engraved with mythical demons, slaying life before them.  Sitting atop are a
few parchments mostly ruined by the damp air and an old fragile ink quill.
Only one of the papers seems remotely salvageable.$d$),
  (495, 11, ARRAY['fireplace', 'fire', 'place', 'grate']::text[], $d$   The fireplace is fairly large.  It seems deep within the wall and at least
three feet tall.  A small iron grate rest in the center, made for the wood to
rest upon.$d$),
  (495, 11, ARRAY['paper', 'parchment']::text[], $d$   Unto my liege I submit my soul, as my brothers and sisters.  The fools have
thrust me in this cell and believe I shall stay quaintly.  Foolish they are,
and thine souls will be swallowed for such an act.  Borgan my lord hear my cry!
Engourge upon the souls of the holy and innocent.  Feast so that we shall sweep
the lands and bring the new world into order.  Toturn namei furch behmeo
truepki nehas!  Nehas!  Nehas!$d$),
  (495, 13, ARRAY['statue', 'grins']::text[], $d$   With the head of grinning dog, body of a wolf, and wings of a dragon the
statue simply invokes imagination and dread as a beast even as small as this
statue seems it does not want to be friends.  The eyes seem to be encrusted
with large rubies, that glow vibrantly in this dark.  The statue has a small
inscription on its left paw: I am child of Borgan!$d$),
  (495, 14, ARRAY['flame', 'black']::text[], $d$   A wondrous feat has been accomplished, it must be so to create such a wonder
of magick The flame is as dark as the heart of Tresyn and yet stems light
through the shadows of the room.  Not removing, just displacing seemingly
showing the flame does not wish to harm any dark.$d$),
  (495, 14, ARRAY['staff']::text[], $d$   Not much of it can be see other than it appears very tall, maybe six feet in
length.  With a strange carving at the top it looks to be a head of a grinning
dog.  Either stained very deeply and for some time ere crafted from a black
wood.$d$),
  (495, 15, ARRAY['glyph', 'glyphs']::text[], $d$   The symbol seems strange and unknown, perhaps followers wrote them when
dedicating the temple to Borgan.

          |
         * *
        *{ }*
       -Regno-
        *{ }*
         * *
          |$d$),
  (495, 18, ARRAY['wall', 'brick', 'bricks']::text[], $d$   Well pieced and done fairly crafted, this wall stands about ten feet tall.
Constructed out of whole bricks of black sand it seems very strong to withstand
these winds.$d$),
  (495, 19, ARRAY['lamp', 'light']::text[], $d$   Appearing to be made from a tarnished brass the light is held upwards by a
tall pole.  The pole stands around seven feet and seems to be crafted from a
black wood.  The light from the lamp dims and glows brighter, perhaps from the
passing winds.$d$),
  (495, 25, ARRAY['statues', 'statue', 'blades', 'tapestries']::text[], $d$   Wondrously crafted statues, the head of a dog and body of wolf grin
sinisterly in the dimly lit room.  The tapestries are a vivid red and trimmed
in gold with pictures of large figures of dark knights slaying mercilessly
their foes before them.  Small statuettes of wicked swords stand on both sides
of the room, though not real blades you can feel the sting deeply as if you
could be next to receive it's dreadful pierce.$d$),
  (495, 31, ARRAY['waterfall']::text[], $d$   A lush forest flows around the waterfall, giving a peaceful feeling.  The
entire right side of the room is filled with beautiful green plant life, even
spawning some small woodland creatures to run through the miniature forest.
$d$),
  (495, 31, ARRAY['alter']::text[], $d$   The alter emits an essence of pain through its ebony apparence.  Swords
dangle along the outline of the alter.  Two torches one on each side, rest in
holder birthing black flames.  Mind-numbing fear and power seem to thrush
towards the eyes of the beholder.$d$),
  (495, 33, ARRAY['arror', 'window']::text[], $d$   The window is about two feet tall and a foot wide.  Looking outwards beyond
the boundries of the stone walls unveils the magnificence and beauty of chaos
and desctruction.  Holding within the view is the black ice desert, showing an
old decrepit tree standing tall and the sharp razor winds ripping up any life
of good heart that stands within its path.$d$),
  (495, 36, ARRAY['throne', 'shade']::text[], $d$   Holding its place in the corner without motion, the ebony throne stands
sentry.  As if crafted from pure unadulterated darkness, the pure light seems
to burn within its wicked presence.  The throne towers at least eight feet and
arms as long as a half of a giant.  The appearance boast only the strongest of
dark powers may rest there.$d$),
  (495, 41, ARRAY['murals', 'mural']::text[], $d$   The murals appear very old and worn through to the bare stone in some parts.
Pictured on this mural is a battle between black demons and an army of knights
and paladins.  The outcome doesn appear clear and the mural stems out of sight
to the west along the ceiling and walls.$d$),
  (495, 41, ARRAY['floor']::text[], $d$   This floor without doubt has been trampled and destroyed in many parts;
yet still not without brilliance a few marks still glisten in the scarce rays
of light.  The floor appears to be made out of gold, or at least an extremely
convincing substitute.$d$),
  (495, 42, ARRAY['mural', 'murals']::text[], $d$   The battle between the demons and the holy order of knights and paladins
still rages on, although it would seem that the holy army is winning this
peculiar battle.  The mural carries northward from here, and moves also to the
south.$d$),
  (495, 42, ARRAY['cart', 'pottery']::text[], $d$   Pottery litters the ground around this old wooden cart.  Odd it would seem
that it was left here still holding goods that anyone may steal.  This cart has
a small marking upon the right side.  The symbol is that of an arrow and coin,
giving suggestion that this was a merchants cart.$d$),
  (495, 42, ARRAY['slab', 'stone']::text[], $d$   This piece of stone is huge, for it must weigh at least two warhorses.  The
bottom of the stone is a marble, color and in look, though as it progresses in
thickness upwards it becomes a glass-like clear.  There is at least part of a
skeleton sealed inside, no flesh only bone.  The skull and upper torso are
viewable, alas the stone grows too clouded to see more.  The skeleton appears
human or at least human-like.$d$),
  (495, 43, ARRAY['mural', 'murals']::text[], $d$   The battle appears amazingly long with these two powers.  A little further
downward reveals a pair of huge eyes glaring over the battle field as the brave
knights battle the demons up their fiery entrance to this plane.  As the knights
move forward, a giant arm waves once across the sky.  The holy army burst into
flames where they stand, writhing in terrifying agony.  The last painting reveals
only those brilliantly dark onyx eyes glaring over the now burning white flag of
the knights.$d$),
  (495, 43, ARRAY['floor', 'chasm']::text[], $d$   An unwavering gash has ripped through this golden floor like an elven sword
through goblin steel.  The gash appears incredibly deep that the bottom is not
even visible in the light.  A light breeze emerges from the deep void.$d$),
  (495, 43, ARRAY['sign']::text[], $d$   The wooden sign dangles only by one of its two chains holding it up.  It
appears to grant view of nothing more than a shield and gauntlet.$d$),
  (495, 47, ARRAY['floor', 'engraving', 'stone', 'planks']::text[], $d$   Words stream down both sides of the planks.  The first form-able sentence on
the left side begins: "I am with thee.  " The phrase is repeated as far as the
eye can see.  On the right side the words begin with " Thou art alone.  " and
do not appear to end either within sight.$d$),
  (495, 53, ARRAY['floor']::text[], $d$   Remnants of marble floor are left, some even still intact, though, very
sparse and it's shine has diminished to a deep grey haze of tragedy.  Rather
large drops of dried blood are tainting the floor, which is mostly broken rock
now.  It appears the drops may suggest leads from north and east, neither is
discernible for now.$d$),
  (495, 54, ARRAY['blade', 'grass', 'simple']::text[], $d$   A young plant it is, very premature with it's pale green color.  It reaches
for any light near it, thirsting for any life it may grasp to sustain it.  It
is indeed a wonder how life could grow in this cavern, life and light seems to
not have existed here in centuries.$d$),
  (495, 55, ARRAY['wall', 'walls']::text[], $d$   These stone walls are quite tall and appear to stretch far into the unseen.
When touched the burnt flakes fall away like ash blows in the wind.  With such
a huge hall covered in flame, it would take a tremendous power to achieve such
disaster.$d$),
  (495, 55, ARRAY['light', 'blue', 'darkness', 'eastern']::text[], $d$   The light appears to shimmer and dim but never fade as it rises brightly
again.  It does not liken to be any flame of torch.  Perhaps magic or a simple
illusion could explain it, cautiously of course.$d$),
  (495, 55, ARRAY['rock', 'large']::text[], $d$   This large stone must weigh a small family of overweight dwarves.  It
doesn't reach very high, only a few feet tall, four at the most.  It is
however, quite wide.  Nearly blocking the path so if it were not low.$d$),
  (495, 57, ARRAY['skeleton', 'handle']::text[], $d$   It is apparent upon closer view that this is a body of a child, human from
the looks, maybe twelve or so.  The bones don't appear to be burnt but are
still blanketed in ash from over the passing time.  It appears the cause of
death is from a small dirk that has been buried deeply into the skull.$d$),
  (495, 57, ARRAY['ash']::text[], $d$A deep black ash covers all that can be seen from here.  There isn't much
left except the remnants of what was a skeleton. The ash could be from cloth or
maybe paper, nevertheless it is clear there was a great reign of fire indeed.$d$),
  (495, 58, ARRAY['well', 'crude']::text[], $d$One step up from the being merely a hole, a makeshift well stands firmly in the
earth.  Large cobblestones have been placed less than a foot in length above
the well, not firmly mind you.  With just a peek towards the murky hole the
stench is nearly over-powering with the smell of oil.  A bubble makes its way
up from the ooze occasionally.  Whether this well was meant for oil or not, not
even a drop of water can be seen.$d$),
  (495, 58, ARRAY['murder', 'mice', 'family', 'corpses']::text[], $d$   It looks to be at least eight animal skeletons has been left here.  They
may have starved without any apparent source of food or water, perhaps they
met their fate in the same flame that had painted these halls black.$d$),
  (495, 59, ARRAY['blue', 'light', 'fire']::text[], $d$The heat that surrounds the liquid fire is immense.  With but a close look it is
hard to conceive but this indeed is fire; a magnificent blue flame that flows so
much as running water does.  To add to the queerness of it all, the flame never
touches the floor, just seemingly disappears or perhaps dissipates.$d$),
  (495, 60, ARRAY['imprint', 'rubble']::text[], $d$   It's rough in detail, but the imprint appears to be a giant claw or
footprint.  It would take something of tremendous weight or force to
reduce this once beautiful marble floor into but a waste.$d$),
  (495, 60, ARRAY['blue', 'light', 'darkness', 'southern']::text[], $d$   The light flickers in and out of existence without truly dying.  The light
may come from flame or magic, but doesn't look to liken to a camp fire or
torch light.$d$),
  (495, 61, ARRAY['shadow', 'grin', 'sentinel', 'western', 'wall']::text[], $d$   Standing at least six feet in height and a broad center, this reflection of
darkness is anything but comforting.  Oddly no matter where the light shifts to,
the shadow never flickers or bolts.  It does however appear to be human in
shape at least, with a troublesome grin on it's head.$d$),
  (502, 0, ARRAY['mist']::text[], $d$The mist sits motionless over all the land, as far as the eye
can see.$d$),
  (502, 3, ARRAY['object']::text[], $d$   The object is barely visible through the mist.  It appears to have sharp
corners; it may be an artifact of some kind.$d$),
  (502, 4, ARRAY['dinghy']::text[], $d$This small boat is broken and rotted. Strangely, it looks like an
accessory to an oceangoing vessel--not the sort of craft that would
ply these waters.$d$),
  (502, 5, ARRAY['hulk']::text[], $d$All that can be seen is a large, dark object far off through
the trees. It appears to be as large as a building.$d$),
  (502, 9, ARRAY['mast', 'nest', 'crow''s']::text[], $d$The crow's nest is broken, and all of the wood is rotted and mossy.
No trace of any sail may be seen.$d$),
  (502, 10, ARRAY['pottery']::text[], $d$Most of the pottery is dull and brown, with a wide curve indicating
a large vessel. However, a hint of dark blue on some fragile gray
pieces hints at finer wares. All of it is broken and worthless.$d$),
  (502, 10, ARRAY['ship', 'keel']::text[], $d$It's either lying on its side or its top--it is impossible to tell
which from this distance. The more important qustion is: what is it
doing so far from the sea?$d$),
  (502, 26, ARRAY['stove', 'iron']::text[], $d$This stove looks very heavy in spite of extensive corrosion. Moss
and fungi grow in its damp interior.$d$),
  (502, 27, ARRAY['painting', 'paintings']::text[], $d$The paintings appear to depict games played with cards, but they
are quite decayed, and only a few scraps remain.$d$),
  (502, 31, ARRAY['ceiling', 'hole']::text[], $d$Chop marks and smashed spots testify to the very intentional
attack that opened the hole.$d$),
  (502, 34, ARRAY['stump', 'stumps']::text[], $d$They appear to have been hewn down with a large, hand-held saw.
None appear to have been cut recently.$d$),
  (510, 3, ARRAY['sign', 'large', 'large-sign']::text[], $d$Welcome to the Village of Nordus, traveler!
You can find many things inside our humble village, here is a handy guide.
To the north can be found the High Council's Chambers.
Travel west to sample some of our many shops and our fine Inn.
To the east you can find the common grounds, where people meet to have fun.
To exit our fine village, go south through the gate.
Enjoy your stay at Nordus.$d$),
  (510, 8, ARRAY['wall', 'walls']::text[], $d$As you look at the walls, they seem to contract and expand, almost like a
muscle.  If you didn't know better, you'd say these walls are living!$d$),
  (510, 12, ARRAY['floor', 'slimy', 'substance']::text[], $d$As you look at the floor it is covered by a slimy substance,  that is very
cold to the touch, and smells like cinnamon.  What could it be?$d$),
  (510, 17, ARRAY['books']::text[], $d$There are many books in the shelf.  There are books about all the classical
subject matters.  There is quite an impressive collection here.$d$),
  (510, 17, ARRAY['bookshelf']::text[], $d$The bookshelf is carved with fine art work.  It is sturdy and looks as though
it has been around for a while.  It must have taken a master craftsman to
do this type of work!$d$),
  (510, 21, ARRAY['desk']::text[], $d$You look at the clutter on the desk and you can't really make out any
important information.  The papers are technical in nature and look to be
some kind of draft for a law, it's very unclear as to what was actually trying
to be written.$d$),
  (510, 21, ARRAY['trophy', 'trophies', 'plaque', 'plaques']::text[], $d$The trophies on the wall are from miscellaneous places, some are hunting
trophies and plaques, some are from public service and for Rana Theroxa's
dedication to his village.$d$),
  (510, 25, ARRAY['flowers']::text[], $d$You have never seen this type of flower before, the centre of each flower looks
almost like a human face...  Wait, it IS a human face, and it's screaming...$d$),
  (510, 30, ARRAY['chain', 'coin']::text[], $d$When you look at the coin that is attached to the chain, you notice that the
chain is also connected to something, removing more dirt you can see that
there is some kind of an opening, perhaps a grate or grating of somekind.
But what is it's purpose?  Where does it lead?  You notice there is a keyhole
in the grating.$d$),
  (510, 30, ARRAY['indented', 'indent']::text[], $d$You look at the indent in the floor and move some dirt around and you notice
that there is a coin attached to a chain under the dirt.$d$),
  (510, 30, ARRAY['dirt', 'floor']::text[], $d$As you look at the ground you can make out a single set of footprints that
are everywhere, perhaps the shopkeeper's footprints.  You notice one spot in
the dirt that looks indented a bit.$d$),
  (510, 31, ARRAY['sign']::text[], $d$The sign reads:
To all who enter here, LEAVE!
I am one of the remaining "normal" people that are left.  Our town has been
attacked by a magical force the likes that we have never seen.  People have
been slowly changing into strange, exotic and horrific creatures.  Some have
just disappeared. Some people in town, while not physically changed, have
lost their ability to think rationally, and have become crazy.  There are
only a handful of us left and we are all suspicious of each other.
Rana Theroxa and the High Council, the Elders, myself and the Pawn shop owner
and some of the villagers are all that is left!  I fear I am going soon also.
                     Be forewarned, LEAVE WHILE YOU CAN!$d$),
  (510, 37, ARRAY['sign']::text[], $d$There are no open shops on this level. This building was under construction
when IT started to happen. We have halted construction until it is safe to
continue.$d$),
  (510, 46, ARRAY['distortion', 'air']::text[], $d$You can see what seems like a shimmering of time and space.  When you try
and touch the disturbance, your hand get a quick shock, the distortion wavers
slightly and then it starts to hum.  When you back away from it, it returns
to it's original state.  Strange things are amist here.$d$),
  (510, 48, ARRAY['picture', 'painting']::text[], $d$You can see an unfinished painting on the wall.  It depicts horrible changes
of the town.  People are running scared from someone or something, there is
a soft glowing aura to the painting as if it is magical in nature.  You touch
the painting and find out it's very soft and lush, but yet, durable and
sturdy at the same time.$d$),
  (510, 48, ARRAY['paper', 'small', 'piece']::text[], $d$You look at the paper, and see that it is a letter:

To whomever finds this,
    Ever since that travelling sorcerer arrived here with his strange
trinkets for sale, things have been going wrong in this town. He must have
got some hold over the council to get elected, and after that people
started to go crazy and attack each other for no reason. Then they started
to disappear into 'rehabilitation' but never returned.
    There are now only a few of us left and even I am not safe any more,
only last night some mindless creatures tried to attack me in my own house
and when I tried to use magic against them, I found it hard to remember the
right words. I write this in the hope that someone will avenge this town.
                   May the Goddess of Mielikki have mercy on us
-Shema$d$),
  (510, 50, ARRAY['clothes', 'cloth', 'ripped']::text[], $d$You can see ripped clothing, soaked in blood, lying on the ground here. The
stains are still damp, indicating that the injury that caused the bleeding
occurred recently.$d$),
  (510, 50, ARRAY['trash', 'ground']::text[], $d$Small broken cups plates and miscellaneous items litter the floor here.  It's
like someone dropped some personal items and just left them here.$d$),
  (510, 57, ARRAY['floor', 'ground', 'dust']::text[], $d$You look at the floor and it's very scuffed up with footprints.  Recent
activity is very appearent and.  The dust in the area is very thick, except
for on the floor, it's very strange.$d$),
  (510, 58, ARRAY['desk', 'clutter']::text[], $d$You can see a clutter of papers and writing tools lying all over the desk.
Someone has been writing a lot down on paper.  You can't make much of it out,
as the writing is not too legible, however you can see something about spells
and perfecting a new technique.  The rest is garbled and unreadable.$d$),
  (510, 60, ARRAY['floor']::text[], $d$The floor is incredibly cold to the touch, in fact the cold penetrates your
footware and makes your feet chilly.$d$),
  (510, 60, ARRAY['smooth']::text[], $d$The walls are so smooth they resemble a highly polished metal or glass.
It is a very eerie feeling.$d$),
  (510, 60, ARRAY['cracked', 'chipped']::text[], $d$As you look at the wall you notice that there are many stones falling out of
this section of the wall.  As you touch the wall it crumbles a bit, causing
debris to fall on the floow.  You also notice that where the debris fell
from the wall, there is a faint outline of some sort of secret door.$d$),
  (510, 69, ARRAY['parchment', 'parchments']::text[], $d$There is some text on one of the parchments, but it looks like code:
LOIBA KZGAD WASFH WAVQA KBVQR GVQUS AUGMR MZLF$d$),
  (510, 70, ARRAY['carving']::text[], $d$The carving isn't very readable, this is what you can make out:

" Y u ha   found t e tre  ur  r  m.  Gr  t rew  ds c n be fou d.
us  you  im g n tion.  Te  p r ."

That is all you can make out and it's not much.  What could it mean?$d$),
  (510, 77, ARRAY['pattern', 'hole']::text[], $d$The pattern around the hole doesn't seem to be very regular on close inspection.
Perhaps it's actually a spell of some sort?$d$),
  (511, 17, ARRAY['sign']::text[], $d$Go back while you still have a chance!
There is no hope for those that continue to proceed along this path.$d$),
  (520, 2, ARRAY['bones', 'rubble']::text[], $d$They look humanoid, and are yellowed with age. Most of them are broken.
Sometimes a skull is even visible.$d$),
  (520, 26, ARRAY['brass', 'plate']::text[], $d$It reads:
Dedicated to the kind people of Templace.
Clan of Ne'Kaaz$d$),
  (520, 26, ARRAY['ornate', 'bench']::text[], $d$A silken cushion, now faded and mildewed, covers this beautiful bench.  A small
brass plate is fixed to the side of the bench.$d$),
  (520, 52, ARRAY['statue', 'lifelike']::text[], $d$This ultra-realisitc statue is of a warrior, in full battle armor.  The details
are magnificant, right down to the intricacy on the coat of arms that is on his
shield.  His face has a look of horrific terror and anguish.$d$),
  (520, 75, ARRAY['altar', 'black', 'massive']::text[], $d$The inscription reads plainly:

   In homage of Sagece of Raymif, master of Templace.$d$),
  (530, 135, ARRAY['north']::text[], $d$The smooth door along the north wall appears to have been designed to
only be opened from the other side. There is no handle and it appears
the door opens inward.$d$),
  (533, 0, ARRAY['footprints', 'tracks']::text[], $d$The footprints on the floor of this tunnel head in both east and west.  You
notice that there are quite a lot of them and they are definitely not
human.$d$),
  (533, 1, ARRAY['west', 'wall']::text[], $d$Strange words are carved into a smooth section of the ice along this wall.
They appear to read, "Vilantus Carmec Lhali.  " Obviously it is in some strange
language which is no doubt long vanished from use.$d$),
  (533, 3, ARRAY['west', 'wall']::text[], $d$Strange words are carved into a smooth section of the ice along this wall.
They appear to read, "Vilantus Carmec Lhali."  Obviously they are in some
strange language of which you are not familiar.$d$),
  (533, 4, ARRAY['wall']::text[], $d$Strange words are carved into a smooth section of the ice along this wall.
They appear to read, "Vilantus Carmec Lhali."  Obviously it is in some
strange language of which you are not familiar.$d$),
  (533, 11, ARRAY['north', 'wall']::text[], $d$Strange words are carved into a smooth section of the ice along this wall.
They appear to read, "Vilantus Carmec Lhali."  Obviously they are in some
strange language of which you are not familiar.$d$),
  (533, 20, ARRAY['north', 'wall']::text[], $d$Strange words are carved into a smooth section of the ice along this wall.
They appear to read, "Vilantus Carmec Lhali."  Obviously it is in some
strange language of which you are not familiar.$d$),
  (533, 40, ARRAY['south', 'wall']::text[], $d$Strange words are carved into a smooth section of the ice along this wall.
They appear to read, "Vilantus Carmec Lhali."  Obviously it is in some
strange language of which you are not familiar.$d$),
  (533, 41, ARRAY['north', 'wall']::text[], $d$Strange words are carved into a smooth section of the ice along this wall.
They appear to read, "Vilantus Carmec Lhali."  Obviously it is in some
strange language of which you are not familiar.$d$),
  (533, 45, ARRAY['shelf', 'shelves', 'wall']::text[], $d$These shelves are stacked high with old books and tomes.  It is fitted nicely
into the wall, and affords some protection to the books that it holds.$d$),
  (533, 45, ARRAY['book', 'books', 'tomes']::text[], $d$These books are quite old and begining to fade, all except one.  There is a
dark colored text which stands out from the others.  Lettered in gold along the
binding are is the title, it reads: The Text of Kzal.$d$),
  (533, 45, ARRAY['Text', 'Kzal', 'text-of-kzal']::text[], $d$The Text of Kzal is old, but still in fairly good condition.  The cover says:
Only Kzal can live to continue on through the battle.  Kzal will survive, and
triumph where all others will fall short.  The text is closed tight, held by
some magical force that cannot seem to be broken.  Whatever it is, there is no
apparent way to get a look at the insides of the mysterious book.$d$),
  (533, 48, ARRAY['east']::text[], $d$Strange words are carved into a smooth section of the ice along this wall.
They appear to read, "Vilantus Carmec Lhali."  Obviously it is in some
strange language of which you are not familiar.$d$),
  (533, 50, ARRAY['north']::text[], $d$Strange words are carved into a smooth section of the ice along this wall.
They appear to read, "Vilantus Carmec Lhali."  Obviously it is in some
strange language of which you are not familiar.$d$),
  (533, 69, ARRAY['west', 'wall']::text[], $d$Strange words area carved into a smooth section of the ice along this wall.
They appear to read, "Vilantus Carmec Lhali."  Obviously it is in some
strange language of which you are not familiar.$d$),
  (533, 78, ARRAY['west', 'wall']::text[], $d$Strange words are carved into a smooth section of the ice along this wall.
They appear to read, "Vilantus Carmec Lhali."  Obviously it is in some
strange language of which you are not familiar.$d$),
  (533, 81, ARRAY['east', 'wall']::text[], $d$Strange words are carved into a smooth section of the ice along this wall.
They appear to read, "Vilantus Carmec Lhali."  Obviously it is in some
strange language of which you are not familiar.$d$),
  (534, 100, ARRAY['sign']::text[], $d$
        +-----------------------------------------------+
        |                                               |
        |       Traveler,                               |
        |                                               |
        |               Ysgarran's Keep offers safety   |
        |       from the elements and beasts of this    |
        |       valley.                                 |
        |                                               |
        |               --Ysgarran                      |
        |                                               |
        +-----------------------------------------------+
                        |               |
                        |               |
                        |               |
                        |               |$d$),
  (534, 150, ARRAY['sign']::text[], $d$
        +-------------------------------------------------------+
        |                                                       |
        |       Greetings Traveler,                             |
        |                                                       |
        |               Please enjoy the hospitality of the     |
        |       the Clan Ysgarran.  You may find warmth by      |
        |       our fire and hot food to aid you on your        |
        |       journey.  All are most welcome to our humble    |
        |       keep.                                           |
        |                                                       |
        |                               --Ysgarran              |
        |                                                       |
        +-------------------------------------------------------+
                                |       |
                                |       |
                                |       |
                                |       |
                                |       |$d$),
  (534, 175, ARRAY['carvings']::text[], $d$The carvings are in an elaborate elven script, far too enigmatic for you to
decipher.$d$),
  (534, 178, ARRAY['BUILDNOTE']::text[], $d$This room is part of the "past elf tower."  It should have an enter trigger
that prevents players from entering.  However, it will allow mobs to enter from
the west, to create the illusion of more beyond the tower.  Those mobs will not
be able to go east or south though, because there should be enter triggers on
those rooms preventing past-elf mobs from entering.$d$),
  (550, 1, ARRAY['west']::text[], $d$The way westward seems to be closed by the vicious storm! You wonder if you can
escape this path.$d$),
  (550, 29, ARRAY['gate']::text[], $d$The symbols on the columns seem to be tribal in nature, maybe an offering to
their gods for a peaceful visit.$d$),
  (550, 77, ARRAY['cauldron']::text[], $d$You see a large open pot embedded into the floor, figures of the Snow Leopard
adorn the cauldron and mist flows freely from it. There are small openings in
the cauldron at the base of the leopard figures.$d$),
  (551, 6, ARRAY['monolith']::text[], $d$You can't quite make it out but it looks like a frightened person carved into
the granite.$d$),
  (554, 41, ARRAY['sign']::text[], $d$     ________________________________________________________________
    |                                                                |
    |    /\  North to the Arctic Village of Ickle                    |
    |    ||                                                          |
    |                                                                |
    |   ==>  East to the Iron Hills                                  |
    |                                                                |
    |                                                                |
    |    ||  South to the Forest Village of Mielikki                 |
    |    \/                                                          |
    |        Be ye ware of dangers and bandits on ye travels.        |
    |                                     --The Iron Dwarves         |
    |                                                                |
     ----------------------------------------------------------------$d$),
  (556, 80, ARRAY['sign']::text[], $d$     ________________________________________________________________
    |                                                                |
    |    /\  South: Mount Gladstone                                  |
    |    ||                                                          |
    |                                                                |
    |                                                                |
    |    ||  Down to the Dark Foothills                              |
    |    \/                                                          |
    |        Be ye ware of dangers and bandits on ye travels.        |
    |                                     --The Iron Dwarves         |
    |                                                                |
     ----------------------------------------------------------------$d$),
  (564, 1, ARRAY['burnt', 'wooden', 'sign']::text[], $d$ ---------------------------------------------------------
|                                                         |
|    BEWARE!  This kingdom was destroyed by a great       |
|             evil in an ancient age. DO NOT enter        |
|             this kingdom to battle the evils if         |
|             you are not of great skill and power.       |
|             The gods of the realm take no pity          |
|             upon mortal souls slain here!               |
|                                                         |
|       YOU HAVE BEEN WARNED!                             |
|                             -- The Iron Dwarves         |
|                                                         |
 ---------------------------------------------------------
                           |     |
                           |     |
                           |     |
                           |     |
                           |     |
                           |     |
                           |     |
                           |     |
                      ^^^^^^^^^^^^^^^^^$d$),
  (580, 1, ARRAY['lantern']::text[], $d$You have to admire the stone lantern's graceful lines.  It stands like a
sentinel, near this beautiful gate.  It is not lit, but you can see the wick
inside it.  Presumably lighting it is one of the daily traditions of the local
culture.$d$),
  (580, 2, ARRAY['gate', 'yomeimon', 'golden']::text[], $d$They are the most intricately carved gates you've ever seen. You see an
inscription near the bottom of the left-hand gate.$d$),
  (580, 2, ARRAY['pictures', 'picture', 'wall']::text[], $d$You can't imagine why a guard tower has pictures on its walls. Perhaps
there is a religious significance to them--they do, after all, all seem
to depict the same thing: Some kind of horrific sea-battle between a
gigantic, colossal serpent and some puny war-boats.$d$),
  (580, 22, ARRAY['boulder', 'boulders', 'rocks']::text[], $d$It seems this boulder has been rolled into place to cleverly disguise a cave
mouth of some kind.  Some kind of writing rings the boulder, demarcating the
cave mouth.$d$),
  (580, 22, ARRAY['writing']::text[], $d$The writing seems to tell the story of something called the "Iwa-no-to," a
confusing story of a goddess, a boulder, a shaman, and a sacred mirror.$d$),
  (580, 44, ARRAY['post']::text[], $d$The post in a thick as a grown man, and supports the twenty-foot circle
above. Smaller beams extend down from it. You can see how, if you push
against the smaller beams, the stage would revolve in a circle.$d$),
  (580, 50, ARRAY['winch', 'lift', 'turnstile']::text[], $d$The winch has ropes and pulleys connecting the lift to an elaborate
wooden framed elevator. The frame goes all the way up to the ceiling.$d$),
  (580, 52, ARRAY['wall', 'wooden']::text[], $d$It's well made, of freshly cut and cured wooden planks nailed tightly
together. You can't see what's beyond the wall, but you can see that a
building rises above it -- an outdoor stage.$d$),
  (580, 54, ARRAY['fusara', 'paintings']::text[], $d$While some societies would consider a formal painting one that is very
colourful and expressive, Odaishyozen denizens consider colour far too
frivolous to use in formal situations. None of the paintings depicts a
human person, and none are very detailed -- in fact, most of them seem to
consist of only a few black brush-strokes upon white rice paper.$d$),
  (580, 58, ARRAY['scuffle', 'scuffles', 'ground']::text[], $d$You see footprints in the dirt near the fence. One set of prints is
small, and the other set is much larger. You wonder whose they are. And
is that a strand of long, dark hair you see on the ground?$d$),
  (580, 59, ARRAY['board', 'fence']::text[], $d$   Wooden planks make up the whitewashed fence, all tightly fitted
and sanded smooth as silk or glass. The whitewashing on one board is
a little more worn away than the other boards.$d$),
  (580, 65, ARRAY['knothole', 'knot', 'hole']::text[], $d$Through the knothole you see people in beautiful, flowing
robes coming down a walk lined with mosaic-shells, laughing
and talking among themselves. You wonder where they're going.$d$),
  (580, 91, ARRAY['rack', 'shelf']::text[], $d$Against the wall you see an iron rack line with all kinds of instruments
whose function you can only guess at - short whisks and brushes, ornately
carved sticks, and more.$d$),
  (580, 96, ARRAY['towel', 'gauze', 'towels']::text[], $d$   The towels are neatly embroidered with phoenixes. The
initials "C S O" are incorporated into the phoenixes, and
the name "AZKRAEL" in stylized glyphs that look like pictures.$d$),
  (580, 102, ARRAY['plaque']::text[], $d$The plaque reads:
  Dedicated to the Goddess of Mercy, who protects the Island of
  Odaishyozen from the terror of the seas.$d$),
  (580, 104, ARRAY['cherry', 'tree', 'orchard', 'flower', 'flowers']::text[], $d$You have never seen a more peaceful scene... The soft pink petals blow
in the breeze, and sometimes you brush an errant petal from your clothes
and face.$d$),
  (580, 112, ARRAY['something', 'water', 'pond', 'pool']::text[], $d$You think the ropes going from the tree are tied around a bale of hay, as
odd as that sounds. The hay sprouts all over with delicate, finger-long
rice plant seedlings. The bale is almost completely submerged under the
pool.$d$),
  (580, 116, ARRAY['girl', 'gem', 'topaz', 'sculpture', 'statue']::text[], $d$The statue seems to be made of yellow gemstone; its facets glitter in
the light of the sun. The statue is a figure of a young girl, her hair
slicked back by water and flying behind her. You can tell that whoever
built this pond had to have a lot of money to afford this gem-sculpture!$d$),
  (580, 136, ARRAY['coat', 'coats', 'package', 'packages']::text[], $d$Some of the coats and cloaks seem quite expensive compared to the others
you've seen people wear here. The packages arranged neatly at the bottom
of the coatrack are wrapped in a variety of brightly coloured papers,
tied with clean white string. One has something written on it, but you
can't read the alien letters.$d$),
  (580, 164, ARRAY['mural', 'murals', 'wall', 'walls']::text[], $d$You marvel at the magnificent talent and skills of whoever painted
these murals. In sparse, unsparing brushstrokes, the story is told.
Humans and gods and fantastic beasts are almost a side interest beside
fabulous vistas and incredible backdrops of mountains, oceans, storms, and
howling winds. The Sea Serpent figures in rather prominently, its bulky
form blotting out the sun as it towers above the comparably puny walled
city of Odaishyozen. The glowing figure of a beautiful woman stands before
it, arms outstretched as if to stop it single-handedly. She stands on the
wall of the city, her black hair streaming out behind her, her robes
plastered to her body in the storm.$d$),
  (580, 181, ARRAY['cubbyhole', 'cubby', 'hole']::text[], $d$A vase is inside the cubbyhole. The vase is carved and painted with
flowers and birds, of such a realistic and lifelike nature that if it
weren't for their fantastic appearance you'd swear some artist had
somehow put real flowers and birds on the vase. It has a few plants
in it -- some long, thin shoots ending in exotic and obscure-seeming
spearhead-shaped flowers, and some kind of bare fern.$d$),
  (580, 184, ARRAY['window', 'outside']::text[], $d$As you look outside, you are thunderstruck with the beauty of a tiny
pocket garden. At once wild and manicured, it rolls in all directions.
You can see a fountain of some sort, and a shrine.$d$),
  (580, 186, ARRAY['outside', 'window', 'platform', 'pond', 'wall']::text[], $d$The room is open-ended, with one wall entirely missing. The construction,
however, seems deliberate. You can easily see the pond south of the room,
elegant and utterly simplistic in its lines and form. You can only
imagine how beautiful it must look when the moon is shining perfectly in
the center of that missing wall.$d$),
  (580, 196, ARRAY['line', 'wall', 'back']::text[], $d$Your hands scrabble to find the way back east, but no matter how hard
you look, you can't find a way back.$d$),
  (580, 199, ARRAY['mirror']::text[], $d$You're quite sure that this is the way through to the woman in the
mirror, but none of your efforts open a way through. Perhaps you need a
special object... One that the wizard Yajiro thought no one would guess.$d$),
  (580, 199, ARRAY['woman']::text[], $d$She screams out in anguish at being captured -- and it is fairly obvious
that she has been tortured, as well, judging by her many injuries. She
glows with an otherworldly light. You cannot understand her words, but
it's clear that she is both tormented and furious.$d$),
  (580, 200, ARRAY['cage', 'thorns']::text[], $d$The cage has a woman in it. Without getting closer, though, you can tell
only that it's a dark, dank place.$d$),
  (583, 1, ARRAY['sign', 'signpost', 'post']::text[], $d$The sign reads:

          The Syric Mountain Pass is newly discovered.
             No one knows yet what lies beyond it.
                Travel here at your own risk!

It is signed with a spiky runish word: "Sirestis".$d$),
  (583, 26, ARRAY['sign', 'post', 'signpost']::text[], $d$The post is sunk into the obsidian of the pathway. It rises to just above
head-height. The sign is written in very stern block letters engraved
into its iron surface. The sign reads:


       -------------------------------------------------------
      /                                                      /
      /            ^                                         /
      /          /   \                                       /
      /           | |       The Syric Mountain Trail         /
      /           | |                                        /
      /                                                      /
      /           | |                                        /
      /           | |       Demise Keep                      /
      /          \   /                                       /
      /            `                                         /
      /                                                      /
      /       BEWARE: Demise Keep is not for the weak        /
      /    or the inexperienced! Travel at your own risk!    /
      /                                                      /
       ------------------------------------------------------
                    |                       |
                    |                       |
                    |                       |
                    |                       |
                    |                       |
                    |                       |

$d$),
  (584, 27, ARRAY['mural', 'carvings', 'three', 'figures']::text[], $d$One figure is of someone who is clearly a king, dressed in royal
robes and wearing a crown. Beside him stands a woman who is just
as clearly his queen -- and your breath catches in your throat
at her raw majesty and power. This is no fainting flower of a
woman, but, rather, a warrioress with clear and obvious strengths.
She must be one of the most powerful fighters of her age. Standing
in front of the first two is a youth, his face full of hope and
joy -- and power of his own. Though the tablet is old, their
expressions are not weathered away; you can see that they are a
proud and regal family.$d$),
  (584, 27, ARRAY['circle', 'stone', 'tablet', 'marker']::text[], $d$The stone tablet is circular in shape. Its diameter is easily the
length of a man's body. Made of elegant marble, it is carved with
three proud humanoid figures.$d$),
  (584, 41, ARRAY['helmets', 'chain', 'vests', 'swords']::text[], $d$They're not in any particular order -- in fact, they appear to have
been tossed onto the ground randomly. Moss and plants grow up around
and through most of them.$d$),
  (584, 82, ARRAY['drawbridge']::text[], $d$In point of fact, it'd be more accurate to say that the drawbridge
has no choice in the matter of whether or not it's raised. The
mechanism that raises it, a short, stout wheel-like device, is
clearly visible from here; it's just as clearly rusted clean through.$d$),
  (584, 85, ARRAY['panel']::text[], $d$It is quite difficult to read the words on the panel, but you
try to do it anyway.$d$),
  (584, 85, ARRAY['words']::text[], $d$The words read:
   This panel is enchanted! To open it, you must open a secret
   door. The name of the secret door is the name of the man who
   was Cardinal of Templace after the Kaaz were destroyed. Beware,
   though, of foolhardiness; beyond this panel lie many dangers.$d$),
  (584, 86, ARRAY['question']::text[], $d$The question reads:
    The name of the door is the name of the Gypsy Prince's bride.
    --Sirestis$d$),
  (584, 86, ARRAY['patch', 'mildew']::text[], $d$The patch, upon closer examination, frames a question that is inked
right onto the stones.$d$),
  (584, 86, ARRAY['wall']::text[], $d$There's a peculiar patch of mildew on the wall, in almost a perfect
circle. Now, isn't that odd?$d$),
  (584, 86, ARRAY['panel']::text[], $d$No, on second examination, you realize there isn't a panel there
after all. Keep looking.$d$),
  (584, 86, ARRAY['something']::text[], $d$The wall... there's just something strange about it. Oh! There's
a panel there... you think.$d$),
  (584, 92, ARRAY['cauldron', 'pot']::text[], $d$The pot's made of thick black iron. It's either too heavy to lift, or
it's bolted right into the floor. Inside the pot a very foul-smelling soup
bubbles.$d$),
  (584, 96, ARRAY['chicken', 'feet', 'legs']::text[], $d$As you watch the chicken legs, one of them lifts into the air
and begins to idly scratch its mate with those huge, curved
claws. After a moment, during which time the house wobbles
alarmingly, the foot settles onto the ground again.$d$),
  (584, 106, ARRAY['painting']::text[], $d$The painting, it seems, is of the Altar to Mielikki. How did it
end up here?$d$),
  (584, 106, ARRAY['crystal', 'ball']::text[], $d$As you look into the ball, you feel yourself growing drowsy..
You sleep, and dream..

    You are young again, and powerful, and so beautiful it makes
    men's hearts ache to look at you. And tonight you are also
    afraid. The sight of the Undead Priests in the old witch's
    crystal ball has made you fear, not for yourself, but for
    those you love. Not for your brother, though... If the
    Black Knights are here, then he must be beyond anyone's
    care but Mielikki's... For your brother you feel only an
    ache and a lust for revenge. So you've fled the safety of your
    home, to lure the evil Knights to you, and keep them from
    the Gypsies who have adopted you so kindly.

    Now, standing in a field in the darkest part of the cold
    forest, you wait for them. Your sword fairly rings with
    its hatred of the evil that is coming. You make your stand
    in the night, knowing that you must destroy every single
    one of the undead enemies, or they will quickly find the
    new life you have forged.. and they will kill your husband,
    and the son you have borne.

The strange hallucination fades, and you come out of your sleep feeling
vaguely worried and wild-eyed.$d$),
  (584, 107, ARRAY['blue', 'green', 'flame']::text[], $d$The flames dance and cavort in the bonfire. Green and blue flames
flicker -- and suddenly, you see them assume the form of a beautiful
man and woman who dance together in the heart of the bonfire before
dissipating into the fire again, to await the next chance to join.$d$),
  (584, 110, ARRAY['painting']::text[], $d$The woman in the painting is drop-dead beautiful in the way that
a very sharp sword is beautiful. She is quite obviously a warrior,
possibly the strongest of her time, but something about the way she
holds her infant suggests an uncharacteristic tenderness. She looks
down at the baby in her arms, smiling shyly at it as if still not
believing it's hers.$d$),
  (586, 16, ARRAY['sand', 'castle', 'sandcastle']::text[], $d$The sand castle seems expertly made, though surely few people
are authorities on excellence in building anything out of sand.
Its turrets and little windows are detailed carefully, and a
piece of driftwood forms a drawbridge suspended by little vines
of seaweed.$d$),
  (586, 26, ARRAY['footprints', 'prints']::text[], $d$The prints seem human, most of them.. but some aren't at all.
Most are recently made.$d$),
  (587, 1, ARRAY['gate']::text[], $d$The gate is adorned with a brightly-colored painting of a
dolphin (a mythological fish) cresting a wave. The creature
has the most outlandish smile on its face.$d$),
  (587, 6, ARRAY['bar']::text[], $d$The bar's made of wood that's been polished over decades to
achieve a high gloss. Numerous stools pull up to it, though
not many are occupied. Behind the bar, shelves of liquor
bottles cluster together.$d$),
  (587, 7, ARRAY['altar']::text[], $d$The altar is made of marble. It looks tremendously heavy! It's
carved with numerous scrolling designs and the occasional god
or goddess. You can't recognize any of them; perhaps they're
the gods of the new continent.$d$),
  (588, 9, ARRAY['sign', 'board']::text[], $d$The sign tacked above the entrance to the tent says:

                           ^
                          / \
                         /   \
                        /     \
           -----------------------------------
          /            MESS HALL             /
         /  ENTER ONLY AT AUTHORIZED TIMES  /
        /           WITH YOUR TROOP        /
        -----------------------------------$d$),
  (588, 13, ARRAY['notepad', 'pad']::text[], $d$It's a little notepad of thin beige paper backed by a bit of hardwood.
Someone has thoughtfully tied a pencil to the top of the pad so it can be
used readily. As you open the notepad's cover and look at it, you see
that it appears to be a grocery list.$d$),
  (588, 18, ARRAY['tray', 'trays']::text[], $d$They look just like the trays the soldiers put their food on as they go
through the mess line, but instead of food, they have jars and shakers of
various kinds of condiments on them. All of them smell funny.$d$),
  (588, 34, ARRAY['map', 'table']::text[], $d$You examine the map on the table closely, and see that it's of this area,
the frozen mountains. Very small amber counters are grouped all over the
map, as are similar green glass counters. You wonder what it means. There
are a lot of amber counters over the town of Ickle.$d$),
  (588, 39, ARRAY['gameboard', 'game', 'pieces', 'piece', 'stones', 'stone']::text[], $d$The gameboard is made of wood, its grain beautifully polished and stained
to display the wood to its best advantage. The criss-crossing lines make
perfect squares across its surface in a 19x19 grid. The pots are made of
dark red hardwood, polished till they are smooth as glass, and lightly
stained. The black stones feel pleasantly grainy, though they are
polished as well. The white stones are thick polished shell, striations
all across their marble-like surface. Whoever owns this game must feel
like a king.$d$),
  (588, 46, ARRAY['leaflet']::text[], $d$The leaflet appears to be a religious tract. It reads:

         -----------------------------------------
         |            MIELIKKI LOVES YOU!         |
         |          Join the army of good         |
         |          and march against the         |
         |            forces of E V I L           |
         |                                        |
         |         JOIN THE POLAR GUARD NOW       |
         |            Go to exotic places         |
         |          Meet interesting people       |
         |              And kill them!            |
         |                                        |
         |     Mayhem!           Free training!   |
         |    Uniforms!            Good food!     |
         |                                        |
         |       Recruitment Office in Ickle      |
         |                                        |
         |               GO POLARS!               |
         |                                        |
         ------------------------------------------

You notice that someone has obviously used this leaflet for darts
practice.$d$),
  (588, 48, ARRAY['symbol', 'door']::text[], $d$The door is surprisingly heavy for such a tent. On it, etched and burned
into its surface, you see:


                               *****
                             **     **
                            **       **
                             **     **
                               *****
                                 *
                                 *
                              *******
                                 *
                                 *
                                 *$d$),
  (588, 50, ARRAY['door']::text[], $d$It has a tiny inscription near the bottom hinge that says "Artemis,
copyright 1996".$d$),
  (588, 69, ARRAY['painting', 'picture', 'frame']::text[], $d$The painting depicts a beautiful woman of indeterminate age. Her skin is
as pale as moonlight, but her eyes are unnaturally indigo-black. Her full
lips are shell-pink. She wears a crimson robe lined in ermine and a silver
circlet that holds her long white hair back. She looks very cruel, though
you can't say for sure why you think that. She holds a mirror up to the
viewer of the painting, and you're shocked to see that although the mirror
is clearly painted, not an actual mirror, you see yourself in it!$d$),
  (588, 72, ARRAY['painting', 'picture', 'frame']::text[], $d$The painting is masterfully done, so lifelike you could reach out and run
your fingers down the pale cheek of the beautiful woman it depicts. She's
neither young nor old, her skin like moonlight, her hair so pure white it
glows, her features finely chiseled. Her eyes stand out in powerful
contrast, being so dark indigo they're nearly black. She wears a beautiful
dark blue dress that shimmers, with a crimson and ermine robe over it. She
holds a silver mirror in her slender hands. You're shocked to see that
although the mirror is painted, not an actual mirror, you can see your own
reflection in it!$d$),
  (588, 90, ARRAY['building', 'tent', 'coliseum']::text[], $d$This is the biggest tent you've ever seen! It looks pretty permanent, as
if it's been here for a while, and all signs seem to indicate that it'll
be here a while longer. You wonder what its function is. Obviously it's
important to the people who live here.$d$),
  (588, 92, ARRAY['fire']::text[], $d$The fire is warm, lulling you to a half-sleep. You just want to curl up
on one of these benches and watch the dancing flames. If it weren't for
the warmth of this fire, you'd most likely drop dead of cold. No doubt
someone else realized this too, and that's why it's here.$d$),
  (588, 117, ARRAY['wall', 'tent']::text[], $d$This is the biggest tent you've ever seen! But where is everyone? This
compound looks fairly large, but you haven't seen many soldiers here.
Where are they all? Have you begun to think that something's wrong here?$d$),
  (588, 118, ARRAY['wall', 'fence', 'gate', 'tent']::text[], $d$The tent is made of thick oiled cloth, and stretches far above your head
to the immediate north. You wonder what it houses, but you can't seem to
find any way into it from here.$d$),
  (590, 2, ARRAY['stone', 'wall', 'large']::text[], $d$   As you examine the stone wall closer, you see a name burnt into one of the
large stones.$d$),
  (590, 6, ARRAY['bench']::text[], $d$   The small wooden bench is well worn from years of use from the HolyGuards
and looks as if it might collapse at any time.$d$),
  (590, 9, ARRAY['barriers', 'barrier']::text[], $d$   These barriers stand about five feet tall, giving just enough space for two
guards to take cover behind.  The barriers show signs of wear as if they have
been through many fierce battles.$d$),
  (590, 12, ARRAY['bench', 'granite']::text[], $d$   The bench is made of granite, polished smooth and into a shape perfect for
sitting.  The grass around the bench is well worn from constant use.$d$),
  (590, 13, ARRAY['stones']::text[], $d$   The stones seem to have been pulled from the wall, and rest loosely in their
holes.  You might be able to move some of the stones.$d$),
  (590, 16, ARRAY['words']::text[], $d$   All that hold a holy value in their heart are welcome here.  Join us in our
crusade to rid the land of the evil spirits that degrade others souls.  Make
yourself at home and all we ask of you is your help.$d$),
  (590, 16, ARRAY['plaque']::text[], $d$   The plaque is very elaborately carved from the same worn grey stone of the
walls.  The words that are written on the plaque seem to be some sort of
welcome sign.$d$),
  (590, 19, ARRAY['window']::text[], $d$   The glass in the window is etched in a way that makes seeing into it almost
impossible.  You can only see shadows of the shapes that are in the room, and
some of the shadows seem to be moving about.$d$),
  (590, 21, ARRAY['window']::text[], $d$   You can see into what looks like the dining room of the mansion.  There is a
table set up in the middle of the room with many chairs surrounding it.  The
walls look to be covered with banners and paintings, which you cannot see clear
enough to determine what they depict.$d$),
  (590, 23, ARRAY['mural']::text[], $d$   The top half of the mural is very intricately painted, with vivid colors and
small details in every scene.  You can make out what seems to be a battle
between humans and creatures.  There is a different scene on the bottom of the
mural, which you can only see the very top part, and it looks to be of some
people all gathered around something and you cannot quite make out what it is.$d$),
  (590, 24, ARRAY['statue']::text[], $d$   A marble carved statue of a greater leader stands about fifteen feet tall.
Clad in armor and sword in hand, he looks to have been a fierce opponent.  His
eyes look almost life like and seem to follow your movements as you pass beside
it.  There is a dedication carved on a marble plaque on the base of the statue.$d$),
  (590, 24, ARRAY['dedication', 'plaque']::text[], $d$   To our beloved and fallen brother go our <b:red>hearts</> and our <cyan>souls</>.
We miss your presence and we long for the day to see you again.  Our lives
shall not be the same with your absence.$d$),
  (590, 27, ARRAY['banner']::text[], $d$The banner looks very old, and has many tears and rips throughout its length.  It is dark red
in color, with gold tassels that hang from the corners.  The words read:
Fight for your faith.  Fight for your heart.  Fight for our brother and may your strong will avenge his death.$d$),
  (590, 29, ARRAY['window', 'etched']::text[], $d$   You can barely see through the etched window making out what appears to be
the courtyard outside.  You can see shapes moving around, but cannot tell what
they are.$d$),
  (590, 31, ARRAY['window']::text[], $d$   You can see into the courtyard through the window.  There are a few people
walking around and some people sitting next to the stone wall.  The window is
large enough to let in plenty of light during the day, giving ample radiance to
light the entire room.$d$),
  (590, 33, ARRAY['game', 'board']::text[], $d$   This seems to be a complex game with twelve handmade wooden pieces, six of
which are <b:red>red</> and six which are <white>silver</>.  The board is divided so that
twenty small squares surround four large spaces, half the squares are
<b:yellow>gold</> and half are <b:blue>blue</>.$d$),
  (590, 34, ARRAY['mark']::text[], $d$   The mark is embroidered in gold and is so finely sewn that it almost looks
painted.  The mark is the letters SH within a circle, which is crossed by two
might looking broadswords.  A few leaves hang off of the swords handles and
look to be some sort of ivy.  The whole circle is then centered in a shield
which is sewn with silver thread.$d$),
  (590, 36, ARRAY['mural']::text[], $d$   The giant mural is very vividly painted with an assortment of colors.  The
scene appears to be taking place in a small village of log houses.  The main
part of the picture shows a young father playing with three of his sons.  The
father looks to be in top physical condition as if he were a warrior of some
sort.  The sons are all laughing and are having a great time with their father.$d$),
  (590, 38, ARRAY['stone', 'effigies']::text[], $d$   The stones depict warriors who stand at guard.  They are about the size of a
human and are wearing full sets of armor, with large swords at their sides.
Lucky for you they are only made of stone.$d$),
  (590, 41, ARRAY['candles']::text[], $d$   The candles burn with a slow intensity, the wax cascading down their sides
like a molten river, forming puddles at the base of each and bonding them
together and to the table.  There are four total candles, each a different size
and color.  The largest one is a dull <red>red</> color, next is a <yellow>tan</> one,
then a smaller <b:blue>blue</> one and the smallest is <green>green</> in color.$d$),
  (590, 41, ARRAY['asldkjf']::text[], $d$   The racks hold many types of weapons.  There seems to be an abundance of
swords and shields, a few looking unused but most seem to be well worn.  They
all have been cleaned, and look like they are well kept after.$d$),
  (590, 43, ARRAY['writing']::text[], $d$   This is the battle that sealed our fate in the beginning of our village,
bringing us to what we have become today.  As the battle endured, many great
men were lost, causing a great deal of heartache and pain.  The leader of the
village, a great Paladin named Thoaver, along with his three sons, lead the
defense of the village from the evil horde.$d$),
  (590, 43, ARRAY['battle']::text[], $d$   This is the largest of the tapestries that hang on the walls.  It is
embroidered with such expertise that it appears to be painted.  The scene shows
a raging clash between a small group of men, consisting of common villagers and
fierce Paladins, and a band of beasts of all color and form.  The beasts look
as if they are overrunning the men, many of which are lying on the ground,
wounded or dead.  There is some writing on the lower part of the tapestry,
which seems to describe what is going on in the depiction.$d$),
  (590, 45, ARRAY['window']::text[], $d$   As you peer out the window, you can see the east side of the Sacred Havens
guard wall.  You can also look out over the tree tops of the forest that
stretches as far as the eye can see.$d$),
  (590, 45, ARRAY['books', 'bookshelf']::text[], $d$   The bookshelf is crammed with all sorts of books, ranging from very large
fat ones to small skinny ones.  Some of the books are written in unknown
languages and several are composed about magic.  The majority of the books are
written about fighting and war strategies.$d$),
  (590, 47, ARRAY['incense']::text[], $d$   Almost <b:white>pure white</> <white>smoke</> rises from a <b:yellow>golden</> pot, forged with
small holes and crevices in the sides.  The pot looks to be well used, as the
incense is burned constantly.$d$),
  (590, 48, ARRAY['tapestry']::text[], $d$   This artwork appears to be woven to mourn the loss of the dead after a
vicious battle.  The scene displays a group of men, all trampled and sullied
from a defeat in battle, trying to regroup and help their fallen brethren.
The village from which the battle was held is ransacked and ruined, with many
people lying around on the ground.  There is some lettering on the bottom of
the tapestry.$d$),
  (590, 48, ARRAY['lettering']::text[], $d$   The consequences of this battle have been enormous, bringing two souls
together by separating three.  After collecting their thoughts, Thoaver and two
of his sons, Belward and Cyrus, search for their remaining brother, who appears
to have gone missing.$d$),
  (590, 52, ARRAY['writing']::text[], $d$   Thoaver realizes that his youngest son Drehbas is gone, and gathers together
his remaining two sons, laying out a pack to rid the realms of evil.  They
speak of a place where good souls can live and train for the purpose of
eradicating evil.$d$),
  (590, 52, ARRAY['tapestry']::text[], $d$   The bright color of this tapestry holds your gaze, letting you take in all
that is happening in the depiction.  An old man clad in armor and brandishing a
broadsword, kneels in prayer with two younger men, who are dressed in the same
armor.  All three men are bruised and bloody, as if they had just fought a
battle.  There is some writing at the bottom of the tapestry.$d$),
  (590, 54, ARRAY['carving']::text[], $d$   The carving is built out of a solid piece of dark wood, giving the picture a
deep perception of depth.  The gold that surrounds the carving reflects light
towards the picture, giving it additional intensity.  The carving is of a coat
of arms with a giant shield in the middle, crossed by two broadswords.  There
are some small flowers that hang from the swords handle and a banner draped
across the top of the shield.  There are some words on the banner.$d$),
  (590, 54, ARRAY['altar']::text[], $d$   The altar looks to be simply made, with a stone base sitting on the floor.
A wooden structure is built on top of the stones, creating a frame for a
carving that rests in the middle.  Gold trim lines all the edges of the wood,
giving the altar a splendid glow in the light.$d$),
  (590, 56, ARRAY['statue']::text[], $d$   The statue stands tall, clad in armor and displaying a figure that would be
a worthy opponent in a fight.  His muscular build and daunting eyes could
easily frighten any evil creature around.  As the light from the candles
flicker it seems to put the statue in motion.  There is an inscription at the
base of the great warrior.$d$),
  (590, 56, ARRAY['inscription']::text[], $d$   Here stands our memory of a great friend, ally and brother.  Drehbas served
his faith well and never wavered from the righteousness of his order.  May his
soul look over us as we continue to smite evil in his name.$d$),
  (590, 57, ARRAY['mural']::text[], $d$   This mural is split up into different sections, each revealing a story.
The first scene shows a group of people, surprised by an ambush in the forest,
while they were traveling.  One warrior seems to be leading the fight to defend
themselves.  The second picture shows the same group of people, setting up camp
in a clearing in some dark woods.  The same warrior sits in front of everyone,
giving a speech.  The third mural painting depicts a large stone wall that
surrounds a mansion, being attacked by evil looking creatures from the woods.
Very few of the creatures seem to have made their way over the wall.  The last
picture shows a group of people, walking away from a grassy meadow with several
gravestones set about, being lead by the same warrior from the other paintings.
There is some writing at the top of the mural.$d$),
  (590, 57, ARRAY['writing']::text[], $d$   From the time of the battle that took my youngest brothers life, I have
dedicated my life towards our idea of the Sacred Haven.  I have led this group
of people into a great existence of laying down our will for the smiting of
evil.  We have defended our haven from hoards of evil and I have led many
operations into the realm to rid our lives of their ways.  As my father passed
on I took on the responsibility to lead the Sacred Haven and keep it on task to
eradicate evil.  -Belward$d$),
  (590, 59, ARRAY['mural']::text[], $d$   The mural seems to be split up into different scenes, depicting a different
part of the story in each.  The first scene shows a group of men, women and
children, all carrying packs and walking through a trail in the forest.  The
second scene illustrates the people forming a small encampment in a clearing of
a dark portion of woods.  The third section shows a great stone wall encircling
a large mansion and some other buildings, giving them protection from what
lurks in the forest.  In the last painting a group of people, some clad in
armor and some in robes, burying a coffin made of pure gold.  The people weep
and grieve for their loss.  There is a passage at the end of the mural.$d$),
  (590, 59, ARRAY['passage']::text[], $d$   After we formed a pack to purge evil from the realm, we moved to a location
that we could prosper and form the idea we called Sacred Haven.  It was a small
camp at first, but over time it became a great place for the gathering of
Paladins and Priests, whose goodness and skills were spread to others in order
to band together and eradicate evil.  As the years went by, our great father
and leader, Thoaver took ill and passed away.  As the time goes on, my pain
from the loss of my youngest brother grows deep, feeding the passion to protect
all that is good.  My older brother Belward has stuck with me and been a great
mentor, forming who I am today.  -Cyrus$d$),
  (590, 61, ARRAY['rug', 'emblem']::text[], $d$   The emblem in the rug is gold and silver in color and seems to be very well
made, for there is a lot of wear marks on the rug, but the emblem seems to be
almost in perfect shape.  The emblem is the mark of the Sacred Haven, which is
the same as on some of the banners you have seen elsewhere in the mansion.$d$),
  (590, 64, ARRAY['table']::text[], $d$   The table is formed of shiny steel and is covered with many types of
bottles, glass tubing, vials and Petri dishes.  Some of the jars hold liquid
and others are set up to perform experiments on the various chemicals.  A large
case holding vials is set up on the corner of the desk.$d$),
  (590, 64, ARRAY['case', 'vials']::text[], $d$There are a few vials that catch your eye.  One is taller than the rest, filled
with a <b:red>red</> liquid and has a label on it.  <b:magenta>-Antidote-</>
Most of the vials are filled with a <b:blue>blue</> liquid with labels attached.  <b:magenta>-Convertor-</>$d$),
  (590, 67, ARRAY['vial']::text[], $d$   The vial is twice the size of the others that rest on the table, and seems
to be full of an unknown liquid.  Its cork stopper has been sealed with wax and
the base of the vial is firmly attached to the table top.$d$),
  (590, 72, ARRAY['flesh', 'things']::text[], $d$Small pieces of dried flesh and bone are scattered about, some looking fresh
while other pieces are smashed into the stone from foot traffic.  There is no
evidence of blood and other than that the flesh things do not appear to be
unusual, aside from being strewn all over the floor.$d$),
  (590, 73, ARRAY['piles']::text[], $d$   As you look closely at the piles, you can tell that they are made from the
flesh of creatures that have been long dead.  Some of the piles seem to be
fresh and others have decomposed into a horrible mess.  Small beetles that
number in the thousands consume the flesh, leaving just the bones lying on the
floor.$d$),
  (590, 73, ARRAY['tools']::text[], $d$   All the tools are created from iron, with long dirty wooden handles.  They
all resemble rakes of some sort.  Their only possible use would be to tend to
the piles and constantly move and churn them to aid their decomposition.$d$),
  (590, 75, ARRAY['altar']::text[], $d$   The top of the altar is formed of jet black granite with no color variation
at all.  The base is also carved from black granite but contains streaks and
veins of a metallic silver color, spreading out through the base like
lightning.  The dried flowers look to be very old, as they have all lost their
color.  The statues are of different warriors clad with armor, all posed to
look like their guarding something.$d$),
  (590, 84, ARRAY['tapestry']::text[], $d$   From what you can see of the artwork, as most of it is covered with mildew,
it looks like about five warriors leading a group of chained creatures down a
trail.  Where they are going is stained by the mildew and the person that is
leading the effort is also covered from waist up.  There is another scene on
the bottom of the tapestry, but the growth of the mildew prevents you from
seeing what it could be about.$d$),
  (590, 85, ARRAY['words']::text[], $d$Blessed be those that follow thy faith
Lessons see those that hollow thy hate
From the darkness we will rise
From the darkness we will shine
Lead the holy unto the dark
For revenge has scorned your heart
We will surely bring an end
And drown your life in your sin$d$),
  (590, 99, ARRAY['symbol', 'symbols']::text[], $d$A mighty two-headed hammer superimposed over an anvil, the holy symbol of
Moradin, God of Dwarves, stands out chiefly among the many symbols decorating
the forge.  The other symbols variously invoke the sacred act of Creation,
bless craftspeople, protect the forge as particularly holy space, and more.$d$),
  (590, 99, ARRAY['altar']::text[], $d$An idol of a stout dwarf resting his hands on the top of a two-headed hammer
rests proudly atop the worked stop altar.  An inscription on it reads,
"Moradin, All Father, in Your honor we Forge.  " Judging from the design and
layout of the stonework, this set up merely a focal point because the entire
forge is actually an altar.$d$),
  (615, 2, ARRAY['bush', 'bushes']::text[], $d$These can only be manzanita bushes, with their pale, almost grayish oval leaves
and striking reddish bark.  They interlock with one another, their strong
branches forming an impenetrable wall to the south.$d$),
  (615, 2, ARRAY['tule', 'tules']::text[], $d$Tules are rushes, growing in shallow, motionless water, and often to very large
sizes.  These are medium-sized specimens.  The sound of buzzing insects can be
heard from their sheltering embrace, and small birds flit to and fro above
them, hunting.$d$),
  (615, 2, ARRAY['pond']::text[], $d$The pond itself is obscured behind the tules.  It lies to the northeast, and
appears to be somewhat long, continuing a ways to the east.$d$),
  (615, 2, ARRAY['meadow']::text[], $d$The meadow is covered with bright flowers and tall grasses that wave gently in
the mild breeze.$d$),
  (615, 3, ARRAY['flower', 'flowers']::text[], $d$Violet shooting stars grow scattered all around. Beneath them, almost hiding
among the taller grasses, small yellow daisies are almost flat against the
ground.$d$),
  (615, 3, ARRAY['tree', 'trees']::text[], $d$The trees are beeches, of medium height, with straight trunks and large round
canopies. Their dark green leaves rustle in the wind.$d$),
  (615, 4, ARRAY['flower', 'flowers', 'reedy', 'plant', 'plants']::text[], $d$With their shocking yellow centers and streaming crimson petals, these can only
be columbines.  They tower over the other denizens of the meadow, preferring
shade to direct sunlight.$d$),
  (615, 4, ARRAY['weed', 'milkweed']::text[], $d$These tall, grayish, fuzzy plants grow in the shade near some helpful beeches.
Their broad leaves show signs of being munched on, perhaps by some tolerant
insect who doesn't mind the acrid-tasting sap that oozes from the bites.$d$),
  (615, 8, ARRAY['ridge']::text[], $d$The ridge is stony, and obscured by grass and a little bit of moss.  As you
look closer, however, it becomes apparent that the stones are laid in rows.
It appears that this is a retaining wall, although it's in poor repair.$d$),
  (615, 8, ARRAY['tree', 'trees', 'fruit', 'branch', 'branches']::text[], $d$The branches peeking over the ridge are long, spindly, and slightly curved.
Looking higher up, you can barely see a small, round, wizened fruit.  It's a
sickly shade of orangey-brown, and quite wrinkled.$d$),
  (615, 9, ARRAY['tree', 'flower', 'flowers']::text[], $d$There are some clusters of small, pale, lavender flowers high up on the tree
above the ridge.  The tree is fairly large and healthy.  Most of it is not
visible from here.$d$),
  (615, 9, ARRAY['ridge']::text[], $d$The ridge is steep and stony, and rises up about ten feet.  It blocks the way
north.  It's fairly regular and straight for a ridge, and is covered with
vegetation.$d$),
  (615, 13, ARRAY['foxglove', 'flower', 'flowers']::text[], $d$If these are foxgloves, then foxes must have small, simple paws.  At any rate,
the blooms resemble tiny caps or hoods, hung from their tips downward at an
angle.  They are a light purple or violet in color and are covered with
brownish dots.  The leaves of the plant grow mainly in a large flat circle down
at the base of the stalk.$d$),
  (615, 30, ARRAY['fungi', 'fungus', 'shelf']::text[], $d$The fungi are as large as your hand, with bright orange flat tops and spongy
yellow bottoms that taper toward the base.  They smell nice.$d$),
  (615, 32, ARRAY['tree']::text[], $d$The cherry tree seems healthy enough, with a profusion of green leaves and no
visibly diseased twigs.  However, it is not blooming, nor is it bearing fruit.$d$),
  (615, 33, ARRAY['tree']::text[], $d$The cherry tree on the other side of the wall is slender, and has few branches
for its height.  However, it is healthy and has several blooms in addition to a
single ripe purple cherry.$d$),
  (615, 35, ARRAY['ruin', 'ruins']::text[], $d$Very little can be seen from this distance - perhaps the end of a stone
wall.$d$),
  (615, 37, ARRAY['fireflies', 'firefly']::text[], $d$The silent dance of the fireflies can be rather soothing to watch.
They seem to blink almost in unison, although there must be thousands!
On closer inspection, one of the fireflies doesn't seem to be blinking
at all... and it's much brighter than the others.$d$),
  (615, 45, ARRAY['waterfall']::text[], $d$The waterfall is about twelve feet high.  Its water glistens in whatever light
is available, be it from the sun, the moon, or only the stars.  Thick mats of
moss grow on the stone to either side.$d$),
  (615, 65, ARRAY['fungi', 'fungus', 'toadstool', 'toadstools']::text[], $d$The toadstools are growing in a broad ring over a foot wide.  This is only the
southern edge; it swings east and west, curving toward the north in each case.
The toadstools themselves range from short and squat to tall and fat.  They are
somewhat slimy and smell like fungus.$d$),
  (615, 65, ARRAY['trunk', 'tree', 'fallen']::text[], $d$The tree appears to have fallen some time ago.  Even so, the rate of its decay
is remarkable: while some dead leaves still cling to a few of the
upward-pointing twigs, all of the wood near the ground is crumbling and
infested with white filaments.$d$),
  (615, 67, ARRAY['bone', 'bones']::text[], $d$A closer inspection reveals that most of them are fairy bones.  The remainder
are cruder and more difficult to identify, perhaps belonging to a predatory
bird.$d$),
  (615, 68, ARRAY['toadstool', 'toadstools']::text[], $d$The toadstools sport irregular white blotches on their caps, regardless of
color.  The orange ones are shaped like a flattened, curving cone, while the
brown ones are taller and more cylindrical.  The green ones vary, and are
usually covered with bumps and ripples.$d$)
) AS v(zone_id, room_id, kw, txt)
WHERE d.room_zone_id = v.zone_id AND d.room_id = v.room_id
  AND d.keywords = v.kw
  AND position(E'\n' in d.description) = 0
  AND btrim(regexp_replace(d.description, '\s+', ' ', 'g')) = btrim(regexp_replace(v.txt, '\s+', ' ', 'g'));

COMMIT;
